COLLDATA("humaydiur","ur",[[1154,"ابو ہریرہ رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کوئی شخص زائد پانی نہ روکے تاکہ اس کے ذریعے گھاس کم ہو۔ (1)","",{"k":"(1) صحیح البخاری (2353)، صحیح مسلم (1566)، سنن الترمذی (1272)، سنن ابن ماجہ (2478)، سنن الکبری للنسائی (5774)، مسند احمد (244/2)، مؤطا امام مالک (ص 458)، مسند ابی یعلی (6257)، المنتقی لابن الجارود (596)، سنن الکبری للبیہقی (151/6)، شرح السنة للبغوی (1668)۔","f":"اس حدیث میں زائد پانی کو روکنے کی ممانعت وارد ہوئی ہے، جب کوئی زائد پانی مانگے تو اس کو دے دیا جائے تاکہ اس سے گھاس وغیرہ اُگے اور جانوروں کے کام آئے، جب کوئی زائد پانی کو روکے گا اور پانی نہیں دے گا تو گویا وہ گھاس کو اگنے سے روک رہا ہے۔ نوٹ: زائد پانی سے مراد وہ پانی ہے جس کے حصول میں کوئی مشقت نہ ہو، اور بغیر پیسوں کے حاصل ہو، موجودہ دور میں موٹر پمپ، ٹربینیں اور انجن کا پانی بڑی مشکل سے حاصل ہوتا ہے، اور ان کا بہت زیادہ بل آتا ہے، اس طرح کے پانی کا مالک اگر کسی کو فری پانی نہ دے تو اس کی مرضی، ایسے شخص پر یہ حدیث فٹ نہیں ہوتی۔ ہاں ضرورت مندوں کی ضرورت پوری کرنا بہت بڑا عمل ہے، اگر کوئی زمیندار تنگدست ہے، ذاتی موٹر نہیں لگوا سکتا اور نہ ہی بجلی کا بل دے سکتا ہے، تو اس کے ساتھ موٹروں کے مالک کو خصوصی توجہ دینی چاہیے، اور اسے پانی اپنی طاقت کے مطابق فری دینا چاہیے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اضافی پانی سے کسی کو نہ روکا جائے ورنہ اس کے نتیجے میں قدرتی گھاس کی پیداوار کم ہو جائے گی‘‘۔\nتخریج: ايضا"}],[1155,"حمیدی نے سفیان سے، انھوں نے ابو زناد سے، انھوں نے اعرج سے، انھوں نے ابو ہریرہ سے روایت کی ہے۔ (1)","",{"k":"(1) صحیح البخاری (8288)، صحیح مسلم (1337)، مسند احمد (258/2)، صحیح ابن حبان (19)، مسند ابی یعلی (6305)، من طریق ابی الزناد عن الاعرج عن ابی ہریرة۔","u2":"یہی روایت ایک اور سند کے ہمراہ بھی منقول ہے۔"}],[1156,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم مجھ سے پوچھنے سے باز رہو، یہاں تک کہ خود ہی بیان کردوں، یقیناً تم سے پہلے کچھ لوگ اس لیے تباہ ہوئے کہ انھوں نے اپنے انبیاء سے بکثرت سوال کیے اور لوگ اختلاف میں پڑ گئے، میں جس چیز کی ممانعت کروں تو اس سے رک جاؤ اور جس کا حکم دوں وہ کرو، جو تمھیں طاقت ہو۔ ابن عجلان نے یہ زائد بیان کیا کہ یہ حدیث مجھے ابان بن صالح نے بیان کی، وہ اس کلمے پر تعجب کرتے تھے: تم اپنی استطاعت کے مطابق ان پر عمل کرو۔ (1)","",{"k":"(1) صحیح: مسند احمد (247/2)، مسند الشافعی (19/1)، صحیح ابن حبان (18)، من طریق محمد بن عجلان عن ابیہ عن ابی ہریرة۔","f":"اس حدیث میں کثرت سوال سے مراد فضول قسم کے سوالات ہیں، اور اس میں وہ فروعی سوالات بھی شامل ہیں جن مسائل کا وجود ابھی تک ہوا ہی نہیں۔ نیز اس حدیث میں قرآن وحدیث سے مخالفت کی وجہ سے ہلاکت کی وعید ہے، کیونکہ انبیاء کی دعوت وحی کے مطابق ہوتی ہے، اس میں اختلاف کی گنجائش نہیں ہوتی، لیکن پھر بھی جو اختلاف کرے گویاوہ وحی الہی کے ساتھ اختلاف کرتا ہے۔ مقلدین حضرات کھلم کھلی قرآن وحدیث کی مخالفت کرتے نظر آتے ہیں، ان کو ہوش کے ناخن لینے چاہئیں کہ کیوں مخالفت کر کے اللہ تعالیٰ کے عذاب کو دعوت دے رہے ہیں۔ نیز یہ بھی معلوم ہوا کہ فرائض کی پابندی ہر مکلف پر ضروری ہے، اور مستحبات ونوافل میں استطاعت کے مطابق عمل کیا جائے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میں جن معاملات میں تمہیں چھوڑ دوں ان میں مجھے ویسے ہی رہنے دو کیونکہ تم سے پہلے کے لوگ بکثرت سوال کرنے اور اپنے انبیاء سے اختلاف کرنے کی وجہ سے ہلاکت کا شکار ہوئے تھے اور میں جس چیز سے منع کروں اس سے باز آ جاؤ جس چیز کا تمہیں حکم دوں اپنی استطاعت کے مطابق اس پر عمل کرو۔‘‘ ابن عجلان نامی راوی نے یہ الفاظ مزید نقل کیے ہیں: میں نے یہ روایت ابان بن صالح کو سنائی، تو وہ ان الفاظ پر حیران ہوئے ’’تم اپنی استطاعت کے مطابق ان پر عمل کرو۔‘‘\nتخریج: ايضا"}],[1157,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ جل شانہ کا قول مبارک ہے: میری رحمت میرے غضب پر سبقت لے گئی ہے۔ (1)","",{"k":"(1) صحیح البخاری (3194)، صحیح مسلم (2751)، سنن الکبری للنسائی (7750)، مسند احمد (242/2)، مسند ابی یعلی (6281)، الاسماء والصفات للبیہقی (ص 416)، شرح السنة للبغوی (4178)۔","f":"یہ حدیث قدسی ہے، اللہ تعالیٰ کی رحمت اس کے غضب سے پہلے ہوتی ہے، جیسا کہ اللہ تعالیٰ نے قرآن مجید میں متعدد مقامات پر ”اِنَّ اللہَ غَفُوْرٌ رَّحِیْمٌ“ کے الفاظ استعمال کیے ہیں اور اللہ تعالیٰ انسان پر رحمت ہی کرتا ہے۔ ﴿وَلَوْ یُعَجِّلُ اللہُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَہُمْ بِالْخَیْرِ لَقُضِیَ إِلَیْہِمْ أَجَلُہُمْ فَنَذَرُ الَّذِینَ لَا یَرْجُونَ لِقَاءَنَا فِی طُغْیَانِہِمْ یَعْمَہُونَ﴾ (10/11) ”اور اگر اللہ لوگوں پر جلدی سے نقصان واقع کر دیتا، جس طرح وہ فائدے کے لیے جلدی چاہتے ہیں، تو ان کا وعدہ کبھی کا پورا ہو چکا ہوتا، ہم ان لوگوں کو جن کو ہمارے پاس آنے کا یقین نہیں ہے، ان کے حال پر چھوڑے رکھتے ہیں کہ اپنی سرکشی میں بھٹکتے رہیں۔ اس آیت میں اللہ تعالیٰ کی رحمت کا واضح تذکرہ ہے کہ لوگ عذاب میں جلدی بھی کرتے ہیں لیکن اللہ کی رحمت اس کے غضب پر سابق ہوتی ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اللہ تعالیٰ نے یہ بات ارشاد فرمائی ہے میری رحمت میرے غضب پر سبقت لے گئی ہے۔‘‘\nتخریج: ايضا"}],[1158,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بُرا نام اللہ تعالیٰ کے نزدیک یہ ہے کہ کسی انسان کو ملک الاملاک کہا جائے، سفیان کہتے ہیں: اس کا معنی ہے ”شاہان شاہ“۔ (1)","",{"k":"(1) صحیح البخاری (6205)، صحیح مسلم (2143)، سنن ابی داود (4961)، سنن الترمذی (2837)، الادب المفرد للبخاری (817)، مسند احمد (244/2)، صحیح ابن حبان (5835)، مستدرک للحاکم (274/4)، سنن الکبری للبیہقی (307/9)۔","f":"اس حدیث میں اللہ تعالیٰ کی ایک صفت کا ذکر ہے اور وہ ”ملک الاملاک“ ہے، جسے اردو میں شہنشاہ کہتے ہیں، یعنی دنیا میں امیر سے امیر آدمی کو بھی شہنشاہ کہنا گناہ ہے، اور شہنشاہ صرف اللہ تعالیٰ ہے۔ نیز اللہ تعالیٰ کی صفات میں تاویل، تشبیہ، تکییف اور تعطیل کرنا درست نہیں ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اللہ تعالیٰ کے نزدیک ناپسندیدہ ترین شخص وہ ہے، جس کا نام ’’بادشاہوں کا بادشاہ‘‘ ہو۔‘‘ سفیان کہتے ہیں: اس سے مراد ’’شہنشاہ‘‘ ہے۔\nتخریج: ايضا"}],[1159,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کوئی مؤمن جب زنا کرتا ہے تو اس وقت مؤمن نہیں ہوتا اور جب چوری کرتا ہے تو اس وقت وہ مؤمن نہیں رہتا، جب شراب پیتا ہے تو پیتے وقت وہ مؤمن نہیں ہوتا اور جب وہ لوٹ مار کرتا ہے تو لوٹتے وقت وہ مؤمن نہیں ہوتا۔ (1)","",{"k":"(1) صحیح: مسند احمد (43/2)، مسند ابی یعلی (6299)، الایمان لابن مندہ (515)، من طریق ابی الزناد بہذا الاسناد، صحیح البخاری (2475)، صحیح مسلم (57)، سنن ابی داود (4689)، سنن الترمذی (2625)، سنن ابن ماجہ (3936)، من طریق آخر عن ابی ہریرة۔","f":"اس حدیث میں کچھ کبیرہ گناہوں کا تذکرہ ہے، اس حدیث سے ثابت ہوا کہ مؤمن شخص کبھی کبیرہ گناہ نہیں کرتا، یعنی ایمان کی حالت میں گناہ نہیں کیا جا سکتا، ایمان اور گناہ آپس میں متضاد ہیں، ایمان ہو گا تو گناہ نہیں ہو گا، گناہ ہو گا تو ایمان نہیں ہو گا۔ اس حدیث سے یہ بھی معلوم ہوا کہ جب مؤمن گناہ کرتا ہے تو اس سے اس کا ایمان نکل جاتا ہے، جیسا کہ صحیح البخاری میں ہے کہ حضرت عکرمہ نے سیدنا ابن عباس رضی اللہ عنہما سے پوچھا کہ ایمان کیسے نکالا جاتا ہے؟ تو انھوں نے جواباً فرمایا: اس طرح، اور اپنی انگلیوں کے درمیان گرہ لگائی پھر اس کو کھولا، پس اگر وہ توبہ کر لے تو اس کا ایمان لوٹ آتا ہے۔ ترمذی اور ابو داؤد میں ہے کہ جب زانی زنا کرتا ہے تو اس سے اس کا ایمان نکل جاتا ہے، سائے کی طرح اس کے سر پر رہتا ہے،، جب وہ اس کام سے فارغ ہو جاتا ہے تو اس کا ایمان واپس لوٹ آتا ہے، اسی طرح ہی دوسرے گناہوں کا معاملہ ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’مومن زنا کرتے وقت مومن نہیں رہتا۔ وہ چوری کرتے وقت مومن نہیں رہتا۔ شراب پیتے وقت مومن نہیں رہتا اور ڈاکہ ڈالتے وقت یا (کوئی چیز چھین کر لے جاتے وقت) مومن نہیں رہتا۔‘‘\nتخریج: ايضا"}],[1160,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہ دنیا کی آگ جہنم کی آگ کا ستر واں حصہ ہے، اس آگ کو دوبار پانی سے بجھایا گیا ہے، ورنہ اس سے کوئی بھی فائدہ نہ اٹھا سکتا۔ (1)","",{"k":"(1) صحیح البخاری (3265)، صحیح مسلم (2443)، مؤطا امام مالک (ص 600)، مسند احمد (244/2)، صحیح ابن حبان (7363)، البعث والنشور للبیہقی (500)، شرح السنة للبغوی (4398)، من طریق ابی الزناد بہذا الاسناد، سنن الترمذی (2589)، من طریق ہمام بن منبہ عن ابی ہریرة۔","f":"اس حدیث میں جہنم کی گرمی کا ذکر ہے کہ دنیا میں تو ہم اس معمولی سی آگ کو برداشت نہیں کر سکتے تو قیامت والے دن اس آگ سے انھتر گنا زیادہ تپش والی آگ میں ہم کیسے سکون حاصل کر سکیں گے؟","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’یہ آگ جہنم کی آگ کا سترھواں حصہ ہے۔ اسے دو مرتبہ پانی کے ذریعے ٹھنڈا کیا گیا ہے اگر ایسا نہ ہوتا، تو اس میں کسی کے لیے کوئی فائدہ نہ ہوتا۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1161,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ کے ناوے اسم مبارک ہیں، ایک کم سو ہیں، جو ان کو حفظ کرے گا وہ جنت میں داخل ہوگا، وہ طاق ہے اور طاق کو پسند کرتا ہے۔ (1)","",{"k":"(1) صحیح البخاری (6410)، صحیح مسلم (2677)، سنن الترمذی (3508)، سنن الکبری للنسائی (7659)، مسند احمد (258/2)، کتاب الدعاء للطبرانی (107)، الاسماء والصفات للبیہقی (ص 4)، مسند ابی یعلی (6277)۔","f":"اس حدیث میں اللہ تعالیٰ کے ناموں کا ذکر ہے، اور ان کو پڑھنے اور یاد رکھنے کی فضیلت کا بیان ہے، اس حدیث سے یہ بھی ثابت ہوا کہ اللہ اکیلا ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اللہ تعالیٰ کے ننانوے نام ہیں یعنی ایک کم سو، جو انہیں یاد کر لے گا وہ جنت میں داخل ہو جائے گا۔ اللہ تعالیٰ وتر ہے اور وتر کو پسند کرتا ہے۔‘‘\nتخریج: اخرجه مسلم في الذكر والدعاء"}],[1162,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنت میں ایک درخت ہے، اگر ایک سوار سو سال تک اس کے سائے میں چلتا ہے تو اس کو طے نہیں کر سکے گا، پڑھو اگر چاہو: ”وظل ممدود اور پھیلے ہوئے سائے۔“ (1)","",{"k":"(1) صحیح البخاری (4881)، صحیح مسلم (2826)، مسند احمد (257/2)، صحیح ابن حبان (8411)، البعث والنشور للبیہقی (268)، صفة الجنة لابی نعیم (403)، من طریق ابی الزناد بہذا الاسناد، سنن الترمذی (2523)، سنن الکبری للنسائی (11564)، من طریق ابی سعید المقبری عن ابی ہریرة۔","f":"اس حدیث میں جنت کے ایک درخت کا ذکر ہے کہ سو سال سوار چلتا رہے تو اس کا سایہ ختم نہیں ہوگا، یہ تو صرف ایک درخت ہے، اللہ نے تو جنت میں اس سے بھی بڑی بڑی نعمتیں تیار کر رکھی ہیں، دنیا کی نعمتوں کے بارے میں تو اللہ تعالیٰ نے فرمایا ہے کہ تم ان کو شمار نہیں کر سکتے، تو جنت کی نعمتوں کو انسان کیسے شمار کر سکتا ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جنت میں ایک درخت ہے، جس کے سائے میں ایک سوار ایک سو سال تک بھی چلتا رہے گا، تو بھی اسے پار نہیں کر سکے گا۔ اگر تم چاہو تو یہ آیت تلاوت کر لو۔ ’’اور پھیلے ہوئے سائے۔‘‘‘‘\nتخریج: اخرجه البخاري في بدء الخلق"}],[1163,"جناب ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم لوگوں میں سب سے زیادہ بدترین دو غلے شخص کو پاؤ گے۔ (1)","",{"k":"(1) صحیح مسلم (2526)، الادب المفرد للبخاری (1309)، سنن ابی داود (4872)، مسند احمد (245/2)، مؤطا امام مالک (ص 607)، الصمت لابن ابی الدنیا (276)، مسند ابی یعلی (6265)، صحیح ابن حبان (5755)، شرح السنة للبغوی (3566)، من طریق ابی الزناد بہذا الاسناد، صحیح البخاری (6058)، من طریق ابی صالح عن ابی ہریرة۔","f":"اس حدیث میں دوزخ والوں کی برائی بیان کی جا رہی ہے کہ دنیا میں تو لوگ کبھی اچھے کو بُرا اور بُرے کو اچھا کہہ دیتے ہیں لیکن یہ بُرے نہیں ہے، حقیقت میں بُرے وہ ہیں جن کو اللہ نے نعمتوں والی جنت کی بجائے صعوبتوں والی جہنم کا وارث بنا دیا۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’تم لوگوں میں سب سے زیادہ برا دو چہرے والے شخص کو پاؤ گے۔‘‘\nتخریج: اخرجه البخاري في المناقب"}],[1164,"ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے رب کا قول نقل کیا کہ اللہ تعالیٰ نے فرمایا: میں نے اپنے نیک بندوں کے لیے جو کچھ تیار کیا ہے اسی کو نہ تو کسی آنکھ نے دیکھا ہے نہ کسی کان نے سنا ہے اور نہ کسی انسان کے دل پر اس کا خیال گزرا ہے، تم پڑھو اگر چاہو ”پس کوئی نفس نہیں جانتا اس کو جو ہم نے ان کے لیے آنکھوں کی ٹھنڈک کا سامان تیار کر رکھا ہے، یہ اس کا اجر ہے جو وہ کرتے تھے۔“ (1)","",{"k":"(1) صحیح البخاری (3244)، صحیح مسلم (2824)، سنن الترمذی (3197)، مسند ابی یعلی (6276)، صحیح ابن حبان (369)، من طریق ابی الزناد بہذا الاسناد، سنن ابن ماجہ (4328)، سنن الدارمی (335/2)، مسند احمد (466/2)، من طریق ابی صالح عن ابی ہریرة۔","f":"یہ حدیث قدسی ہے، اس میں بھی اللہ تعالیٰ نے جنت کی نعمتوں کا تذکرہ کیا ہے کہ جنت میں ایسی نعمتیں ہوں گی کہ دنیا میں ان کا وہم وگمان بھی نہیں ہے، اس سے یہ بھی ثابت ہوا کہ اللہ تعالیٰ نے انسان کو بالکل کمزور پیدا کیا ہے، اس سے یہ بھی ثابت ہوا ہے کہ اللہ تعالیٰ کسی کے تقویٰ کو ضائع نہیں کرتے، اور اس کو اس کی محنت کا صلہ ضرور دیں گے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اللہ تعالیٰ نے ارشاد فرمایا ہے: میں نے اپنے نیک بندوں کے لیے وہ چیز تیار کی ہے جسے کسی آنکھ نے دیکھا نہیں ہے، کسی کان نے (اس کے بارے میں) سنا نہیں ہے اور کسی انسان کے دل میں اس کا خیال بھی نہیں آیا (سیدنا ابو ہریرہ رضی اللہ عنہ شاید نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا) اگر تم لوگ چاہو تو یہ آیت تلاوت کر لو۔ ’’کوئی شخص یہ نہیں جانتا کہ اس کی آنکھوں کی ٹھنڈک کے لیے کیا چیز تیار کی گئی ہے؟ یہ اس چیز کی جزا ہے جو وہ لوگ عمل کیا کرتے تھے۔‘‘‘‘\nتخریج: متفق عليه"}],[1165,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میرے ورثاء دینار تقسیم نہیں کریں گے، جو چیز میرے اہل و عیال کے نفقہ اور عامل کی اجرت سے بچ رہتا ہے وہ صدقہ ہے اور میرے ورثاء دینار تقسیم نہیں کریں گے۔ (1)","",{"k":"(1) صحیح البخاری (2776)، صحیح مسلم (1760)، سنن ابی داود (2974)، شمائل ترمذی (403)، مسند احمد (242/2)، مؤطا امام مالک (ص 608)، صحیح ابن خزیمة (2488)، صحیح ابن حبان (6610)، سنن الکبری للبیہقی (302/6)، شرح السنة للبغوی (3838)۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میرے ورثاء دینار تقسیم نہیں کریں گے میں اپنی بیویوں کے خرچ اور اپنے اہل کاروں کی تنخواہوں کے بعد جو چھوڑ کر جاؤں گا وہ صدقہ ہوگا، میرے ورثاء دینار تقسیم نہیں کریں گے۔‘‘\nتخریج: متفق عليه"}],[1166,"ابو ہریرہ رضی اللہ عنہ نے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کسی کے جوتے کا تسمہ ٹوٹے تو وہ ایک جوتا پہن کر نہ چلے اور ایک موزہ پہن کر بھی نہ چلے یہاں تک کہ دوسرے کو ٹھیک کر لے اور جب کوئی جوتا پہنے تو پہلے دائیں پاؤں میں پہنے اور جب جوتا اتارے تو پہلے بائیں پاؤں کا جوتا اتارے، دائیں پاؤں پہلے پہننے والا ہو اور آخر میں ننگا ہونے والا ہو۔ (1)","",{"k":"(1) صحیح البخاری (5855)، صحیح مسلم (2097)، سنن ابی داود (4136)، سنن الترمذی (1774)، شمائل ترمذی (81، 82)، مؤطا امام مالک (ص 563)، بذکر الشطر الاول، صحیح البخاری (5856)، سنن ابی داود (4129)، سنن الترمذی (1779)، شمائل ترمذی (84)، مسند احمد (465/2)، مؤطا امام مالک (ص 563)، بذکر الشطر الثانی۔","f":"اس حدیث میں ایک جوتا پہن کر چلنے سے منع کیا گیا ہے، اور موزہ اور جوتا پہنتے وقت دائیں طرف کا خیال رکھنا چاہیے، جیسا کہ اور احادیث میں بھی رسول اللہ صلی اللہ علیہ وسلم کے بارے میں آتا ہے کہ: ”يُعْجِبُهُ التَّيَمُّنُ فِي تَنَعُّلِهِ وَتَرَجُّلِهِ وَطَهُورِهِ وَفِي شَأْنِهِ كُلِّهِ“ اس سے یہ بھی ثابت ہوا کہ اللہ تعالیٰ نے بنی آدم کی بڑی عزت رکھی ہے، کہ ایک پاؤں کے ساتھ وہ نہ چلے، بلکہ دونوں پاؤں کے ساتھ چلے، اس سے یہ بھی ثابت ہوا کہ ہر اچھا کام دائیں طرف سے اور ہر بُرا کام بائیں طرف سے شروع کرنا چاہیے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب کسی شخص کا تسمہ ٹوٹ جائے، تو وہ ایک جوتا پہن کر نہ چلے اور ایک موزہ پہن کر نہ چلے جب تک وہ دوسرے کو ٹھیک نہیں کروا لیتا جب کوئی شخص جوتا پہننے لگے، تو پہلے دائیں پاؤں میں پہنے اور جب اتارنے لگے، تو پہلے بائیں سے اتارے دایاں پاؤں پہنتے ہوئے پہلے ہونا چاہیے اور اتارتے ہوئے بعد میں ہونا چاہیے۔‘‘\nتخریج: اخرجه البخاري في اللباس"}],[1167,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا تمھیں تعجب نہیں ہوتا کہ اللہ تبارک و تعالیٰ مجھ سے قریش والوں کی گالیاں اور لعن طعن کو کیسے پھیرتا ہے؟ وہ کسی مذمم کو گالی دیتے ہیں اور کسی مذمم پر لعنت کرتے ہیں اور میں محمد صلی اللہ علیہ وسلم ہوں۔ (1)","",{"k":"(1) صحیح البخاری (3533)، سنن النسائی (3468)، مسند احمد (244/2)، سنن الکبری للبیہقی (252/8)، دلائل النبوة للبیہقی (152/1)۔","f":"اس حدیث سے معلوم ہوا کہ جس کو گالی دی جائے، اس کو گالی سے کچھ فرق نہیں پڑتا، بلکہ گالی دینے والے کو گناہ ملتا ہے، اور گالی دینا مطلقاً حرام ہے، اور گالی شیطان اور کسی جانور کو بھی دینا منع ہے، افسوس کہ آج ہر بات کے ساتھ گالی دی جاتی ہے، لوگوں کو اس پر ڈانٹنا چاہیے، اور خود گالی پر کنٹرول رکھیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’کیا تم لوگ اس بات پر حیران نہیں ہوتے کہ اللہ تعالیٰ نے مجھ سے قریش کے برا کہنے اور ان کے برا کرنے کو کیسے پھیر دیا ہے؟ وہ لوگ برا کہتے ہوئے مذمت کرتے ہیں، لعنت کرتے ہوئے مذمت کرتے ہیں جبکہ میں محمد صلی اللہ علیہ وسلم ہوں (یعنی جس کی تعریف کی گئی ہے)‘‘۔\nتخریج: اخرجه البخاري في المناقب"}],[1168,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنت اور جہنم میں باہم جھگڑا ہوا، جہنم نے کہا: میرے اندر بڑے طاقت ور اور متکبر داخل ہوں گے اور جنت نے کہا: میرے اندر کمزور اور مساکین داخل ہوں گے، پس اللہ تعالیٰ نے فرمایا: (اے آگ!) تو میرا عذاب ہے تیرے ذریعے عذاب دوں گا جس کو چاہوں گا، اور جنت کو فرمایا: تو میری رحمت ہے میں تیرے ذریعے رحم کروں گا جس پر میں چاہوں گا، سفیان نے کہا: اس حدیث میں گمان ہے کہ یہ الفاظ بھی ہیں: اور جنت و جہنم تم ہر دو کو بھرنے کا سامان ہوگا۔ (1)","",{"k":"(1) صحیح البخاری (7449)، صحیح مسلم (2846)، سنن الکبری للنسائی (7693)، الادب المفرد للبخاری (554)، مسند ابی یعلی (6290)، صحیح ابن حبان (7477)، الشریعة للآجری (ص 391)، الاسماء والصفات للبیہقی (ص 158)، من طریق الاعرج عن ابی ہریرة، مسند احمد (276/2، 450)، سنن الترمذی (2561)، من طریق اخری عن ابی ہریرة۔","f":"اس حدیث سے ثابت ہوا کہ جنت و جہنم کا وجود ہے، اس حدیث میں منکرین آخرت کی تردید ہے، اس حدیث سے یہ بھی ثابت ہوا کہ اگر کسی نے جنت میں جانا ہے تو اللہ کی رحمت کے ساتھ جانا ہے، جہنم میں جانا ہے تو اللہ کے غضب کے ساتھ جانا ہے۔ اللہ ہمیں جہنم سے بچا کر جنت کا وارث بنائے، آمین۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جنت اور جہنم کے درمیان بحث ہو گئی، تو اس نے کہا مجھ میں سرکش اور متکبر لوگ داخل ہوں گے، تو دوسری نے (یعنی جنت نے) کہا مجھ میں کمزور اور غریب لوگ داخل ہوں گے، تو اللہ تعالیٰ نے اس سے فرمایا: تم میرا عذاب ہو تمہارے ذریعے میں جسے چاہوں گا عذاب دوں گا اور اس سے فرمایا: تم میری رحمت ہو تمہارے ذریعے میں جس پر چاہوں گا رحمت کروں گا۔‘‘ سفیان کہتے ہیں: میرے خیال میں روایت میں یہ الفاظ بھی ہیں ’’تم میں سے ہر ایک بھر جائے گی۔‘‘\nتخریج: متفق عليه"}],[1169,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی آدمی سائے میں ہو اور اس پر سے سایہ ڈھل جائے اور اس کا بعض جسم دھوپ میں اور بعض سائے میں ہو تو اس جگہ سے ہٹ جائے۔ (1)","",{"k":"(1) صحیح: سنن ابی داود (4821)، سنن الکبری للبیہقی (236/2، 237)، من طریق سفیان بہذا الاسناد، مسند احمد (382/2)، من طریق محمد بن المنکدر عن ابی ہریرة۔","f":"اس حدیث میں رسول اللہ صلی اللہ علیہ وسلم کا ایک حکم ہے کہ آدمی کا جسم سائے اور دھوپ دونوں جگہ میں نہیں ہونا چاہیے، بلکہ یا تو اس کا پورا جسم سائے میں ہو یا سارا جسم دھوپ میں ہو۔","u2":"حضور ابو القاسم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’جب کوئی شخص سائے میں ہو اور وہ سایہ اس سے کچھ کھسک جائے یہاں تک کہ اس شخص کا کچھ حصہ دھوپ میں آ جائے اور کچھ سائے میں ہو تو اسے وہاں سے ہٹ جانا چاہیے (یعنی مکمل دھوپ یا پھر مکمل سائے میں آنا چاہیے۔)‘‘\nتخریج: اخرجه ابوداؤد في الادب"}],[1170,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کسی کو جمائی آئے تو وہ منہ بند رکھے یا منہ پر ہاتھ رکھ لے۔ (1)","",{"k":"(1) الادب المفرد للبخاری (942)، صحیح مسلم (2994)، سنن الترمذی (370)، مسند احمد (242/2)، صحیح ابن خزیمة (920)، صحیح ابن حبان (2357)، مسند ابی یعلی (6456)، سنن الکبری للبیہقی (289/2)، من طریق العلاء عن ابیہ عن ابی ہریرة، صحیح البخاری (6226)، سنن ابی داود (5028)، من طریق سعید بن ابی سعید عن ابیہ عن ابی ہریرة۔","f":"اس حدیث سے معلوم ہوا کہ جب جمائی آئے تو اس کو روکنے کی بھر پور کوشش کرنی چاہیے، کیونکہ جمائی شیطان کی طرف سے ہوتی ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب کسی شخص کو جمائی آئے، تو وہ اسے روکنے کی کوشش کرے ورنہ اپنا ہاتھ اپنے منہ پر رکھ لے۔‘‘\nتخریج: متفق عليه"}],[1171,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ایک آدمی خار دار شاخ کے پاس سے گزرا تو اس نے وہ کانٹے دار شاخ راستے سے اٹھا کر پھینک دی تو اللہ تعالیٰ نے اس کے اس عمل کی قدر دانی فرما کر اس آدمی کو بخش دیا۔ (1)","",{"k":"(1) صحیح البخاری (2472)، الادب المفرد (229)، صحیح مسلم (1914/127)، سنن ابی داود (5245)، سنن الترمذی (1958)، سنن ابن ماجہ (3682)، مسند احمد (341/2)، صحیح ابن حبان (540)، شعب الایمان للبیہقی (11167)۔","f":"اس حدیث میں اللہ تعالیٰ کی صفت غفور الرحیم کی اصل شکل کی بیان کی گئی ہے، یعنی اللہ تعالیٰ اپنے بندے کو معاف کرنے کے مواقع فراہم کرتا ہے، اللہ چاہے تو کسی انسان کو چھوٹے سے چھوٹے عمل کی وجہ سے معاف فرما دے، اور جس کو چاہے چھوٹی سی غلطی کی وجہ سے پوری زندگی کے اعمال کو تباہ و برباد کر کے اس کو جہنم رسید کر دے۔ اس سے یہ بھی ثابت ہوا کہ اللہ تعالیٰ ایک ذرہ برابر بھی ظلم نہیں کرتے، اور یہ بھی معلوم ہوا کہ اللہ کسی کے اعمال کو ضائع نہیں کرتے، الا یہ کہ انسان خود اپنے اعمال کو ریا کاری، سنت کی مخالفت، نیت کی خرابی، عقیدہ کی خرابی اور حرام کمائی کی وجہ سے ضائع کر لے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم کے اس فرمان کا پتہ چلا ہے: ایک مرتبہ ایک شخص کانٹوں کی شاخ کے پاس سے گزرا اس نے اسے راستے سے ہٹا دیا، تو اس شخص کی مغفرت ہو گئی۔ سفیان نامی راوی نے بعض اوقات یہ الفاظ نقل کیے ہیں۔ ’’اللہ تعالیٰ نے اس کے اس عمل کو قبول کیا اور اس کی مغفرت کر دی۔‘‘\nتخریج: ايضا"}],[1172,"عکرمہ کہتے ہیں: کیا میں تمھیں وہ چھوٹی باتوں کی خبر نہ دوں جو میں نے ابو ہریرہ رضی اللہ عنہ سے سنی ہیں، ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مشکیزے کے منہ پر منہ رکھ کر پینے سے منع کیا ہے۔ (1)","",{"k":"(1) صحیح البخاری (5626)، سنن ابن ماجہ (3420)، مسند احمد (247/2)، سنن الدارمی (2124)، مستدرک للحاکم (140/4)، شرح معانی الآثار للطحاوی (276/4)، سنن الکبری للبیہقی (68/6)۔","f":"اس حدیث سے معلوم ہوا کہ کسی بڑے برتن مثلاً گھڑا، پتیلہ غرض کہ ہر بڑے برتن کے ساتھ منہ لگا کر پانی نہیں پینا چاہیے، اس سے یہ بھی ثابت ہوا کہ پانی اللہ کی بہت بڑی نعمت ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے اس بات سے منع کیا ہے کہ مشکیزہ کے منہ سے (منہ لگا کے) پانی پیا جائے۔\nتخریج: اخرجه البخاري في الاشربه"}],[1173,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: لوگ گمان کرتے ہیں کہ ابو ہریرہ کس طرح رسول اللہ صلی اللہ علیہ وسلم کی احادیث بکثرت بیان کرتے ہیں؟ اللہ تعالیٰ کی بارگاہ میں حاضر ہونا ہے، میں ایک مسکین آدمی تھا، اپنا پیٹ خالی رکھ کر رسول اللہ صلی اللہ علیہ وسلم کی صحبت میں رہتا تھا۔ انصار کو ان کے مال کی نگرانی کرنا پڑتی تھی اور مہاجرین کو بازاروں میں خرید و فروخت کا شغل مصروف رکھتا تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں رہتا تھا، اتفاقاً ایک دفعہ کلام فرما رہے تھے کہ آپ نے فرمایا: کون اپنی چادر بچھاتا ہے اس وقت تک کہ میں اپنی بات پوری کر لوں؟ پھر وہ چادر کو اپنی طرف ملا کر قبض کر لے تو وہ جو کچھ مجھ سے سنے گا کبھی نہیں بھولے گا، پس میں نے اپنی چادر بچھا دی جو میرے اوپر تھی، یہاں تک کہ جب نبی کریم صلی اللہ علیہ وسلم نے اپنی گفتگو ختم کی تو چادر کو میں نے اپنے ساتھ قبض کیا، پس قسم ہے اس ذات کی جس نے ان کو حق کے ساتھ مبعوث کیا کہ میں نے اس کے بعد جو کچھ بھی آپ سے سنا ہے اس کو کبھی نہیں بھولا ہوں۔ سفیان نے کہا: مسعودی کا قول ہے کہ پھر ایک شخص اٹھا اور اس نے چادر بچھائی تو نبی صلی اللہ علیہ وسلم نے فرمایا: بنو دوس کا یہ لڑکا تیرے اوپر سبقت لے گیا ہے۔ (1)","",{"k":"(1) صحیح البخاری (118)۔ صحیح مسلم (2492)۔ سنن ابن ماجہ (262)۔ سنن الکبری للنسائی: 5868۔ مسند احمد: 240/2۔ مسند ابی یعلیٰ: 6248۔ العلم لابی خیثمة: 96۔ جامع بیان العلم لابن عبد البر: 6/1۔","f":"اس سے معلوم ہوا کہ سیدنا ابو ہریرہ رضی اللہ عنہ احادیث سے بڑی محبت کرتے تھے، اور انھوں نے سب سے زیادہ احادیث روایت کی ہیں، ان کو نبی کریم صلی اللہ علیہ وسلم سے بڑی محبت تھی، اس لیے ہمیشہ نبی کریم صلی اللہ علیہ وسلم کے پاس رہتے اور احادیث سنتے تھے، اس سے یہ بھی معلوم ہوا کہ ایک طالب علم کو تعلیم کی تمام رکاوٹوں کو پس پشت ڈالنا چاہیے، اور ہمیشہ استاذ کے ساتھ چمٹے رہنا چاہیے، اس سے یہ بھی معلوم ہوا کہ مسکینی علم کے سامنے رکاوٹ نہیں ہے، اس سے یہ بھی معلوم ہوا کہ مال کو سنبھال کر اس کو اللہ کے سپرد کرنا چاہیے، اور اس کی نگرانی بھی کرنی چاہیے، اور یہ بھی ثابت ہوا کہ خرید و فروخت (تجارت) سنت ہے۔ اور یہ بھی ثابت ہوا کہ کاروبار کے ساتھ انسان علم حاصل کر سکتا ہے، اس سے یہ بھی معلوم ہوا کہ ایک استاذ کو شاگرد کے لیے کھلا وقت نکالنا چاہیے، اس سے یہ بھی معلوم ہوا کہ استاذ کو ہر وہ طریقہ اختیار کرنا چاہیے جس سے طلباء کو سمجھ آجائے، اور ہمیشہ طلباء کے لیے دعا کرتے رہنا چاہیے، اس سے یہ بھی معلوم ہوا کہ قسم صرف اللہ کی کھانی چاہیے، اگر رسول کی قسم کھانی جائز ہوتی تو سیدنا ابو ہریرہ رضی اللہ عنہ ضرور رسول اللہ صلی اللہ علیہ وسلم کی قسم کھاتے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں لوگ یہ کہتے ہیں: کہ ابو ہریرہ نبی اکرم صلی اللہ علیہ وسلم کے حوالے سے بکثرت احادیث نقل کرتا ہے اللہ تعالیٰ کی بارگاہ میں حاضر ہونا ہے۔ میں ایک غریب شخص تھا میں اپنے پیٹ میں (ضروری) خوراک ڈال کر نبی اکرم صلی اللہ علیہ وسلم کے ساتھ رہا کرتا تھا جبکہ انصار اپنی زمینوں کی دیکھ بھال کیا کرتے تھے مہاجرین بازار میں سودے اور لین دین کیا کرتے تھے ایک مرتبہ میں ایک محفل میں نبی اکرم صلی اللہ علیہ وسلم کے پاس موجود تھا، تو آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: کون شخص میری گفتگو ختم کرنے تک اپنی چادر کو بچھائے گا اور پھر اسے سمیٹ لے گا، تو وہ میری زبانی جو بھی بات سنے گا اسے کبھی نہیں بھولے گا۔ تو میں نے اپنے جسم پر موجود چادر کو بچھا دیا یہاں تک کہ جب نبی اکرم صلی اللہ علیہ وسلم نے اپنی بات مکمل کی، تو میں نے اسے سمیٹ لیا اس ذات کی قسم! جس نے نبی اکرم صلی اللہ علیہ وسلم کو حق کے ہمراہ مبعوث کیا ہے اس کے بعد میں نبی اکرم صلی اللہ علیہ وسلم کی زبانی سنی ہوئی کوئی بات کبھی نہیں بھولا۔ سفیان کہتے ہیں: مسعودی نامی راوی نے یہ بات نقل کی ہے پھر ایک اور صاحب کھڑے ہوئے انہوں نے بھی اپنی چادر کو بچھایا، تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’دوسی جوان تم پر سبقت لے گیا ہے۔‘‘\nتخریج: متفق عليه"}],[1174,"محمد بن سیرین بیان کرتے ہیں: لوگ آپس میں اس بات میں اختلاف کر رہے تھے کہ جنت میں مرد زیادہ جائیں گے یا عورتیں؟ پھر وہ ابو ہریرہ رضی اللہ عنہ کے پاس حاضر ہوئے، اور ان سے اس کے بارے میں پوچھا تو ابو ہریرہ رضی اللہ عنہ نے فرمایا: ابو القاسم صلی اللہ علیہ وسلم نے فرمایا: پہلی جماعت میری امت سے جو جنت میں داخل ہوگی ان کی صورت اور جمال چودھویں کے چاند کی مانند ہوگا، جو ان کے بعد داخل ہوں گے ان کی روشنی آسمان میں چمکتے ستارے کی مثل ہوگی، ان میں سے ہر ایک کی دو بیویاں ہوں گی، ان کی دو پنڈلیوں کا مغز گوشت کے اندر سے نظر آئے گا اور جنت میں کوئی مرد بیوی کے بغیر نہ ہوگا۔ (1)","",{"k":"(1) صحیح مسلم (2834)، مسند احمد (230/2)، سنن الدارمی (2835)، مصنف عبد الرزاق (20879)، صفة الجنة لابی نعیم (244)، تاریخ بغداد للخطیب (87/9)۔","f":"اس حدیث سے معلوم ہوا کہ جنت میں بھی درجے ہوں گے، زیادہ تقویٰ والے کو اچھا درجہ اور کم تقویٰ والے کو کم درجہ ملے گا، چونکہ جنت میں نوجوان لوگ جائیں گے تو اللہ تعالیٰ نے ان کے لیے بیویوں کا بندوبست فرمایا ہوا ہے، اس حدیث سے یہ بھی معلوم ہوا کہ جنت کا کم سے کم حسن اور نعمتیں دنیا کے زیادہ سے زیادہ حسن اور نعمتوں سے بڑھ کر ہوں گے۔ دنیا میں ہم زیادہ دیر تک سورج یا چاند کو نہیں دیکھ سکتے لیکن جنت میں کسی کا حسن سورج سے بڑھ کر اور کسی کا چاند سے بڑھ کر اور کسی کا ستاروں سے بڑھ کر ہوگا، اس حدیث سے معلوم ہوا کہ اللہ آنکھوں کو کبھی جنت میں اس سے کہیں زیادہ طاقت دے گا کہ وہ سورج، چاند و ستارے جیسے حسن کو تادیر دیکھتی رہیں۔","u2":"محمد بن سیرین بیان کرتے ہیں: کچھ لوگوں کے درمیان اس بارے میں بحث ہو گئی کہ جنت میں مرد زیادہ ہوں گے یا خواتین۔ وہ لوگ سیدنا ابو ہریرہ رضی اللہ عنہ کے پاس آئے اور ان سے اس بارے میں دریافت کیا، تو انہوں نے بتایا حضور ابو القاسم صلی اللہ علیہ وسلم نے یہ بات ارشاد فرمائی ہے: میری امت کا جو پہلا گروہ جنت میں داخل ہو گا وہ چودھویں رات کے چاند کی مانند ہوں گے پھر اس کے بعد والے لوگ اس طرح ہوں گے جیسے آسمان میں موجود سب سے زیادہ چمکدار ستارہ ہوتا ہے۔ یہاں سفیان نامی راوی نے ایک روایت کے ایک لفظ کو نقل کرنے میں شک کا اظہار کیا ہے۔ ان میں سے ہر ایک کی دو بیویاں ہوں گی، جن کی پنڈلیوں کے گوشت کے اندر سے ہڈی کا مغز بھی نظر آئے گا اور جنت میں مجرد زندگی نہیں ہوگی۔\nتخریج: ايضا"}],[1175,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میرے نام پر نام رکھو مگر میری کنیت پر کنیت نہ رکھو۔ (1)","",{"k":"(1) صحیح البخاری (6188)، صحیح مسلم (2134)، سنن ابی داود (4965)، سنن ابن ماجہ (3735)، مسند احمد (248/2)، سنن الدارمی (2696)، مصنف ابن ابی شیبة (671/8)، سنن الکبری للبیہقی (308/9)۔","f":"اس حدیث سے معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم کے نام پر نام یعنی محمد احمد یا اکیلا محمد یا اکیلا احمد نام رکھنا درست ہے، کیونکہ ان کے معنی تعریف کے ہیں، لیکن کوئی ابو القاسم کنیت نہیں رکھ سکتا، کیونکہ جب وہ یہ کنیت رکھے گا تو احتمال واقع ہو جائے گا کہ لیکن آپ صلی اللہ علیہ وسلم کی وفات کے بعد ابو القاسم کنیت رکھنا درست ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میرے نام کے مطابق نام رکھ لو لیکن میری کنیت کے مطابق کنیت اختیار نہ کرو۔‘‘\nتخریج: متفق عليه"}],[1176,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی شخص ایسا خواب دیکھے جو اس کو نا پسند ہو تو وہ دو رکعات پڑھے اور اپنا خواب کسی انسان سے بیان نہ کرے، تو وہ خواب اس کو کوئی ضرر نہیں دے گا۔ (1)","",{"k":"(1) صحیح البخاری (7017)، صحیح مسلم (2263)، سنن ابی داود (5019)، سنن الترمذی (2270)، سنن ابن ماجہ (3906)، سنن الکبری للنسائی (7654)، عمل الیوم واللیلة للنسائی (910)، مسند احمد (269/2)، سنن الدارمی (2149، 2153)، مصنف عبد الرزاق (20352)، مستدرک للحاکم (390/4)۔","f":"اس حدیث سے معلوم ہوا کہ نیک اور اچھے بندے کو بھی گندے سے گندے خواب آ جاتے ہیں، کیونکہ صحابہ کرام رضوان اللہ علیہم اجمعین کو یہ واقعہ ضرور پیش آیا ہو گا، تب آپ نے ایسے خوابوں کے بارے میں ارشادات جاری فرمائیں ہوں گے، اور صحابہ سے بڑھ کر کوئی نیک نہیں ہوسکتا، اس حدیث سے یہ بھی معلوم ہوا کہ اللہ کو یاد کرنے سے برائی جاتی رہتی ہے، اور اس سے یہ بھی معلوم ہوا کہ بُرا خواب تعبیر بتانے والے کے علاوہ کسی کو نہیں بتانا چاہیے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب کوئی شخص کوئی ایسا خواب دیکھے جو اسے اچھا نہ لگے، تو وہ دو رکعت ادا کر لے اور اس خواب کے بارے میں کسی کو نہ بتائے، تو وہ خواب اسے کوئی نقصان نہیں پہنچائے گا۔‘‘\nتخریج: ايضا"}],[1177,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کعبہ شریف کو (آخر زمانے میں) چھوٹی چھوٹی ٹانگوں والے حبشی منہدم کر دیں گے۔ (1)","",{"k":"(1) صحیح البخاری (1591)، صحیح مسلم (2909)، سنن النسائی (2907)، مسند احمد (310/2)، مصنف ابن ابی شیبة (47/15)، صحیح ابن حبان (6751)، سنن الکبری للبیہقی (340/4)، شرح السنة للبغوی (2008)۔","f":"قیامت کی نشانیاں دو طرح کی ہوتی ہیں، صغریٰ، کبریٰ، یعنی چھوٹی اور بڑی، چھوٹی نشانیاں تو بے شمار واقع ہو چکی ہیں، اور کچھ بڑی نشانیاں ہیں، جیسے حضرت عیسیٰ علیہ السلام کا نزول، خروج دجال وغیرہ، ان میں سے ایک یہ ہے کہ چھوٹی چھوٹی ٹانگیوں والا حبشی کعبہ اللہ کو منہدم کر دے گا۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’حبشہ سے تعلق رکھنے والا ’’ذو سویقتین‘‘ خانہ کعبہ کو ڈھا دے گا۔‘‘\nتخریج: ايضا"}],[1178,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عنقریب لوگ اپنی سواری لے کر دور دراز سے علم کی تلاش میں نکلیں گے تو ان کو مدینہ منورہ کے عالم سے زیادہ عالم والا کوئی نہیں ملے گا۔ (1)","",{"k":"(1) اسنادہ ضعیف: ابن جریج اور ابو الزبیر دونوں مدلس راوی ہیں اور تصریح بالسماع ثابت نہیں ہے، سنن الترمذی (2680)، مسند احمد (299/2)، سنن الکبری للنسائی (4291)، صحیح ابن حبان (3736)، سنن الکبری للبیہقی (386/1)، تاریخ بغداد (306/5، 307)، مستدرک للحاکم (90/1، 91)۔","f":"اس حدیث سے معلوم ہوا کہ علم قیامت تک چلتا رہے گا، اور علم کے طالب دور دراز کا سفر کرتے رہیں گے، اس حدیث سے یہ بھی ثابت ہوا کہ مدینہ منورہ علم کا سرچشمہ تھا، ہے اور رہے گا۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’عنقریب وہ وقت آئے گا جب لوگ علم کے حصول کے لیے اونٹوں کے جگر پچھلا دیں گے لیکن انہیں کوئی ایسا عالم نہیں ملے گا جو مدینہ کے عالم سے زیادہ علم رکھتا ہو۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1179,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: جب یہ آیت نازل ہوئی: ”جو بدی کرے گا اس کو اپنے کیے کی سزا ملے گی۔“ تو مسلمانوں پر یہ امر بڑا شاق گزرا، پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قریب رہو سیدھے رہو اور بشارت پر بھی نگاہ رکھو، مسلمان کو جو بھی مصیبت پہنچتی ہے وہ اس کے گناہ کا کفارہ ہوتی ہے، یہاں تک کہ وہ کانٹا جو اس کو چبھتا ہے اور وہ ٹھوکر جو اس کو لگتی ہے۔ (1)","",{"k":"(1) صحیح مسلم (2574)، سنن الترمذی (3041)، سنن الکبری للنسائی (11122)، مسند احمد (248/2)، مصنف ابن ابی شیبة (229/3، 230)، تاریخ الکبیر للبخاری (211/1)، سنن الکبری للبیہقی (373/3)۔","f":"اس حدیث سے یہ ثابت ہوا کہ جو کوئی گناہ کرتا ہے، اس کو اس کی سزا ضرور ملتی ہے، جیسا کہ اللہ تعالیٰ نے فرمایا: ﴿وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ اس حدیث سے یہ بھی معلوم ہوا کہ مومن کو اگر تکلیف ہو تو اللہ تعالیٰ اس کے درجات بلند فرماتے ہیں، اس سے یہ بھی معلوم ہوا کہ تکلیف کے وقت اللہ کے انعامات پر نظر رکھنی چاہیے، اس سے یہ بھی معلوم ہوا کہ اللہ مومن بندے کو ایک کانٹے کے برابر بھی تکلیف نہیں دینا چاہتے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: جب یہ آیت نازل ہوئی۔ ’’جو شخص برا عمل کرے گا اسے اس کا بدلہ مل جائے گا۔‘‘ تو یہ بات مسلمانوں کے لیے بڑی پریشانی کا باعث بنی۔ نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’تم لوگ تفریق سے بچو اور ٹھیک رہو اور خوشخبری حاصل کرو کہ بندہ مومن کو جو بھی پریشانی لاحق ہوتی ہے وہ اس کے لیے کفارہ بن جاتی ہے یہاں تک کہ اسے جو کانٹا چبھتا ہے یا جو مشکل درپیش ہوتی ہے، تو یہ بھی اس کے لیے گناہوں کا کفارہ بن جاتی ہے۔‘‘\nتخریج: اخرجه مسلم في البر والصلة"}],[1180,"ابو ہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے فرمایا: کبریائی اور بڑائی میری چادر ہے اور عزت میری ازار ہے تو جو شخص ان دو میں سے کسی ایک میں مجھ سے جھگڑا کرے گا اور میرا شریک بننے کی کوشش کرے گا تو میں اس کو آگ میں ڈال دوں گا۔ (1)","",{"k":"(1) صحیح مسلم (2620)، مختصراً، سنن ابی داود (4090)، سنن ابن ماجہ (4174)، مسند احمد (248/2)، مصنف ابن ابی شیبة (89/9)، الزہد لہناد (825)، مسند اسحاق بن راہویہ (285)، شرح السنة للبغوی (3593)، الادب المفرد للبخاری (552)، عند البخاری فی الادب ومسلم من طریق ابی سلمة عن ابی سعید الخدری رضی اللہ عنہ وابی ہریرة۔","f":"یہ حدیث قدسی ہے، کبریائی اور بڑائی اللہ تعالیٰ کی چادر ہے، جو تکبر کرتا ہے، گویا اس نے اللہ تعالیٰ کی چادر کو ہاتھ ڈالا ہے، انسان اللہ کے مقابلے میں بالکل حقیر ہے، انسان کے لیے جائز نہیں ہے کہ وہ تکبر کرے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کا یہ فرمان نقل کرتے ہیں: ’’اللہ تعالیٰ نے ارشاد فرمایا ہے: کبریائی میری چادر ہے، عزت میرا ’’ازار‘‘ ہے، جو شخص ان دونوں میں سے کسی ایک کے بارے میں میرے ساتھ مقابلہ کرنے کی کوشش کرے گا میں اسے جہنم میں ڈال دوں گا۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1181,"ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ انھوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! جب ہم آپ صلی اللہ علیہ وسلم کی مجلس میں ہوتے ہیں تو ہمارے دل ایک عمدہ حال میں ہوتے ہیں اور جب ہم آپ صلی اللہ علیہ وسلم کی مجلس سے چلے جاتے ہیں تو ہمارے دل کی کیفیت اس حالت کے برعکس ہوتی ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر تم میری مجلس سے چلے جانے کے بعد بھی اسی حالت پر رہو جیسا کہ میری مجلس میں تمھارے دل کی کیفیت ہوتی ہے تو تم سے فرشتے مصافحہ کریں گے، ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنت کی عمارتیں ایک اینٹ سونے اور ایک اینٹ چاندی سے بنائی گئی ہیں اور اگرا نہایت خوشبو دار کستوری کا لگایا گیا ہے اور اس کی کنکریٹ موتی زبرجد اور یاقوت کی ہیں، اور انھوں نے ایک طویل حدیث ذکر کی۔ (1)","",{"k":"(1) صحیح: سنن الترمذی (3598)، سنن ابن ماجہ (1752)، مسند احمد (305/2)، سنن الدارمی (2824)، صحیح ابن خزیمة (1901)۔","f":"اس حدیث سے ثابت ہوا کہ دلوں کی کیفیت بدلتی رہتی ہے، اور اس سے یہ بھی معلوم ہوا کہ ایمان کم یا زیادہ ہوتا رہتا ہے، ہمیشہ انسان کو اچھے ماحول میں رہنا چاہیے، تاکہ اس کا دل ایمان کی مٹھاس سے لبریز رہے، اور اس حدیث سے یہ بھی معلوم ہوا کہ جو ہمیشہ ایمان سے رہتا ہے، اچھی بات کرتا ہے، تو فرشتے بھی اس کو پسند کرتے ہیں، اور اس حدیث سے یہ بھی ثابت ہوا کہ سونا، چاندی اور کستوری بہت قیمتی چیزیں ہیں، اس حدیث سے یہ بھی معلوم ہوا کہ مجلس اکٹھی کر کے دینی باتیں سمجھانی چاہییں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: لوگوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم جب ہم آپ صلی اللہ علیہ وسلم کے پاس موجود ہوتے ہیں، تو ہمارے دلوں کی کیفیت مختلف ہوتی ہے لیکن جب ہم آپ صلی اللہ علیہ وسلم کے پاس سے اٹھ کر چلے جاتے ہیں، تو ہماری حالت تبدیل ہو جاتی ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: جب تم لوگ میرے پاس سے اٹھ کر چلے جاتے ہو اس وقت بھی اگر تمہاری حالت اسی کی مانند ہو جس طرح اس وقت ہوتی ہے جب تم میرے پاس موجود ہوتے ہو تو فرشتے تمہارے ساتھ مصافحہ کرنا شروع کر دیں۔ راوی بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے یہ بات ارشاد فرمائی ہے: جنت کی تعمیر یوں کی گئی ہے کہ ایک اینٹ سونے کی ہے اور ایک اینٹ چاندی کی ہے اور اس کا گارا مشک اذفر کا ہے اور اس کی کنکریاں لؤلؤ، زبرجد اور یاقوت کی ہیں۔ اس کے بعد راوی نے طویل حدیث ذکر کی ہے۔\nتخریج: ايضا"}],[1182,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب اللہ تعالیٰ کسی کام کا آسمان پر فیصلہ صادر کرتے ہیں تو فرشتے اللہ تعالیٰ کی بات کے خوف سے اپنے پر ہلاتے ہیں، گویا چٹان پر زنجیر پڑ رہی ہو، جب ان کے دل سے خوف چلا جاتا ہے تو وہ (بڑے فرشتوں سے) پوچھتے ہیں: تمھارے رب نے کیا فرمایا ہے؟ تو وہ کہتے ہیں: جو فرمایا وہی حق ہے اور وہ بلند ذات اور بڑائی والا ہے، فرشتوں کی ان باتوں کو جو چوری سننے والے سنتے ہیں، پھر چوری سننے والے بعض بعض کے اوپر چڑھے ہوتے ہیں، سفیان ان کے بعض پر بعض کے چڑھنے کی کیفیت بیان کرتے ہیں اور کہا کہ ان فرشتوں کے کلام سے کوئی کلمہ جب کوئی چوری چوری سننے والا سن لیتا ہے تو وہ اپنے سے نیچے والے کو سناتا ہے، پھر وہ اپنے نیچے والے کو، یہاں تک کہ وہ کسی جادوگر یا کاہن کی زبان پر جاری کرتا ہے، کبھی تو کلام چور کو شعلہ اس کے سنانے سے پہلے آپکڑتا ہے اور کبھی وہ ماخت کو سنا چکا ہوتا ہے تو ساحر وکاہن اس ایک بات میں سو جھوٹ ملا کر بیان کرتا ہے، پھر لوگ کہتے ہیں: فلاں دن اس نے یہ کہا تھا اور ایسا ہی ہوا اور یہ ہوا اور وہ ہوا، دراصل وہ ایک سچی ثابت ہونے والی بات تو وہی ہوتی ہے جو آسمان کے فرشتوں سے سنی گئی ہے اور اس کی وجہ سے ساحر وکاہن کی دوسری باتیں لوگوں کے درمیان تسلیم ہو جاتی ہیں۔ (1)","",{"k":"(1) صحیح البخاری (4800)۔ خلق افعال العباد: 60۔ سنن ابی داود (3989)۔ سنن الترمذی (3223)۔ سنن ابن ماجہ (194)۔ صحیح ابن حبان: 36۔ دلائل النبوة للبیہقی: 235/2، 236۔ التوحید لابن خزیمة، ص: 147۔ الایمان لابن مندہ: 700۔","f":"اس حدیث میں اللہ تعالیٰ کا کلام کرنا ثابت ہوتا ہے، اس پر ہمارا ایمان ہے، اس کی کیفیت کو ہم نہیں جانتے، نیز اس حدیث میں فرشتوں کا آپس میں بات کرنا بھی ثابت ہوتا ہے، نیز شیطانوں کی اسلام سے دشمنی کی انتہا ثابت ہوتی ہے، کہ ظالم اللہ تعالیٰ کی باتیں معلوم کرنے کی خاطر کتنی کوشش کرتے ہیں۔ نیز یہ بھی ثابت ہوا کہ کاہن و جادوگر شیطان کی پیروی کرتے ہیں، اور یہ شیطان کے آلہ کار بنے ہوئے ہیں، ان کی گمراہیاں امت مسلمہ پر بالکل واضح ہو چکی ہیں، افسوس کہ لوگ پھر بھی ان شیطانوں کے ساتھ غلط مقاصد کی غرض سے چمٹے ہوئے ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: جب اللہ تعالیٰ آسمان میں کوئی فیصلہ سناتا ہے، تو فرشتے اس کے حکم کے سامنے سر کو جھکاتے ہوئے اپنے پر مارتے ہیں یوں جیسے زنجیر پتھر پر ماری جاتی ہے جب ان کے دلوں سے خوف کم ہوتا ہے، تو وہ دریافت کرتے ہیں: تمہارے پروردگار نے کیا فرمایا ہے؟ تو دوسرے جواب دیتے ہیں: جو اس نے فرمایا ہے وہ حق ہے، بلند و برتر ہے، پھر چوری چھپے سننے والے اس میں سے کوئی بات سن لیتے ہیں اور چوری چھپے سننے والے اس طرح ہوتے ہیں جس طرح وہ ایک دوسرے کے اوپر نیچے سفیان نے کر کے دکھایا کہ وہ ایسے ایک دوسرے کے اوپر ہوتے ہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تو وہ شخص ان میں سے کوئی بات سن لیتا ہے، جسے وہ اپنے سے نیچے والے تک پہنچا دیتا ہے پھر وہ اپنے سے نیچے والے تک پہنچا دیتا ہے پھر وہ کسی جادوگر یا کاہن کی زبانی بات بیان کرتا ہے بعض اوقات شہاب ثاقب اس تک پہنچ جاتا ہے اس سے پہلے کہ وہ بات اپنے سے نیچے والے تک منتقل کرے اور بعض اوقات شہاب ثاقب اس تک پہنچنے سے پہلے ہی وہ بات اگلے شخص تک منتقل کر دیتا ہے وہ اس کے ساتھ سو جھوٹ بھی ملا دیتا ہے، تو یہ کہا جاتا ہے اس شخص نے فلاں دن جو ہم سے کہا تھا: کیا ایسا نہیں ہوا؟ اس نے فلاں فلاں بات کہی تھی یہ وہی بات ہوتی ہے جو اس نے آسمان سے سنی ہوتی ہے، تو تصدیق اس بات کی کی جاتی ہے جو آسمان سے کی گئی تھی۔\nتخریج: اخرجه البخاري في التفسير"}],[1183,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مجھے اس بستی کی طرف ہجرت کرنے کا حکم ملا ہے جو دوسری بستیوں کو کھا جائے گی، لوگ اس کو یثرب کہتے ہیں اور وہ مدینہ ہے، وہ لوگوں کو اس طرح صاف کر دیتی ہے اور ناپاک کو نکال دیتی ہے جیسا کہ بھٹی لوہے کی میل صاف کر دیتی ہے۔ (1)","",{"k":"(1) صحیح البخاری (1871)، صحیح مسلم (1832)، مسند احمد (247/2)، مؤطا امام مالک (ص 545)، سنن الکبری للنسائی (11399)، مصنف عبدالرزاق (1716)، شرح مشکل الآثار للطحاوی (332/2)، صحیح ابن حبان (3733)، مسند ابی یعلی (6374)۔","f":"اس حدیث سے مدینہ منورہ کی فضیلت ثابت ہوتی ہے، پہلے اس کا نام ”یثرب“ تھا، یاد رہے کہ مکہ مدینہ سے مجموعی فضائل کے اعتبار سے افضل ہے۔ بعض جھوٹی روایات میں مدینہ منورہ کہنے کی فضیلت آئی ہے، حالانکہ وہ سخت ترین ضعیف ہیں۔ اے اللہ! ارقم کو اور اس کے اہل خانہ کو مکہ یا مدینہ میں مستقل جگہ نصیب فرما، اور اپنے دین کی خدمت کا موقع میسر فرما، بے شک تو دعاؤں کو سننے والا اور قبول کرنے والا ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’مجھے ایک بستی کے بارے میں حکم دیا گیا کہ وہ باقی بستیوں کو کھا جائے گی لوگ یہ کہتے ہیں: یہ ’’یثرب‘‘ ہے، حالانکہ یہ ’’مدینہ‘‘ ہے، جو لوگوں کو باہر نکال دے گا، جس طرح بھٹی لوہے کے زنگ کو صاف کر دیتی ہے۔‘‘\nتخریج: متفق عليه"}],[1184,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لوگ ہمیشہ سوالات کرتے رہیں گے یہاں تک کہ کہیں گے: یہ تمام اشیاء اللہ تعالیٰ نے بنائی ہیں، تو اللہ کو کس نے پیدا کیا ہے؟ جب تم میں سے کسی آدمی کے خیالات اس حد تک چلے جائیں تو وہ کہے: میں اللہ پر ایمان لایا۔ (1)","",{"k":"(1) صحیح البخاری (3278)، صحیح مسلم (134)، سنن ابی داود (4721)، عمل الیوم واللیلة للنسائی (662)، مسند احمد (331/2)، صحیح ابی عوانة (82/1)، کتاب الدعاء للطبرانی (1267)، السنة لابن ابی عاصم (651)، الایمان لابن مندہ (352)، شرح السنة للبغوی (61)۔","f":"ایک دوسرے سے شرعی سوالات کرنا درست ہے، لیکن ایسے سوالات جو انسان کو کفر تک پہنچا دیں، ان کا کرنا درست نہیں ہے، اللہ رب العزت خالق ہیں، اور قرآن مجید اس کی صفت اور کلام ہے، باقی سب اس کی مخلوق ہیں۔ اللہ ہمیشہ سے ہے اور ہمیشہ رہے گا، نہ اس کی ابتداء ہے اور نہ ہی انتہاء ہے، شیطان غلط باتیں زبان سے نکلوا دیتا ہے، اگر کبھی ایسا اوقات شیطانی بات زبان سے نکل جائے تو فوراً کہنا چاہیے، اعوذ باللہ من الشیطن الرجیم اگر اللہ تعالیٰ کی ذات کے متعلق شیطان کوئی وسوسہ ڈال دے تو فوراً ”آمنا باللہ“ کہنا چاہیے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’لوگ ایک دوسرے سے مسلسل سوالات کرتے رہیں گے یہاں تک کہ وہ یہ کہیں گے اللہ تعالیٰ نے تو ہر چیز کو پیدا کیا ہے، تو اللہ تعالیٰ کو کس نے پیدا کیا ہے؟ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: جب یہ صورتحال درپیش ہو تو آدمی یہ کہے: میں اللہ پر ایمان رکھتا ہوں۔‘‘\nتخریج: ايضا"}],[1185,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قسم اس ذات کی جس کے قبضے میں میری جان ہے! جب کوئی مومن بندہ پاک کمائی سے صدقہ دیتا ہے، اور اللہ تعالیٰ صرف پاک کمائی کو ہی قبول کرتے ہیں، اور آسمان کی طرف بھی صرف پاک چیز ہی چڑھتی ہے، وہ حق کی جگہ پر رکھی جاتی ہے، گویا کہ وہ رحمن کے دائیں ہاتھ میں رکھی جاتی ہے، پھر اللہ تعالیٰ اس کو بڑھانا شروع کر دیتے ہیں جس طرح کوئی شخص اپنے جانور کے بچے کو پالتا ہے، یہاں تک کہ ایک لقمہ یا ایک کھجور قیامت کے دن بڑے پہاڑ کی مانند ہو گا، اور تلاوت کی: ”اللہ تعالیٰ اپنے بندے کی توبہ قبول کرتے ہیں اور صدقات قبول کرتے ہیں۔“ (1)","",{"k":"(1) صحیح البخاری (1014)، سنن الترمذی (661)، سنن النسائی (2526)، سنن ابن ماجہ (1842)، مسند احمد (418/2)، سنن الدارمی (1682)، صحیح ابن خزیمة (2425)، مسند الشافعی (220/1)، صحیح ابن حبان (3319)، شرح السنة للبغوی (1631)، من طریق سعید بن یسار عن ابی ہریرة، صحیح البخاری (1410)، من طریق ابی صالح عن ابی ہریرة۔","f":"اس حدیث سے پاک اور حلال چیز کی اہمیت ثابت ہوتی ہے، عبادات وغیرہ اس شخص کی قبول ہوتی ہیں جو حلال خود حلال چیزوں کو لازم پکڑے ہوئے ہو اور جو شخص حرام کھاتا ہے اس کی کوئی بھی عبادت اللہ تعالیٰ کے ہاں قبول نہیں ہوتی۔ نیز اس حدیث میں اللہ تعالیٰ کے ہاتھ کا ثبوت ہے، اس پر ہمارا ایمان ہے، لیکن ہم کیفیت وتشبیہ وغیرہ کے قائل نہیں ہیں، اور اس حدیث سے صدقہ وخیرات کی بہت زیادہ اہمیت ثابت ہوتی ہے، اللہ تعالیٰ ہر نیکی کو بہت زیادہ بڑھاتا ہے، کیونکہ اللہ تعالیٰ نیکیوں کو پسند فرماتے ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اس ذات کی قسم! جس کے دست قدرت میں میری جان ہے، جو بھی شخص پاکیزہ کمائی میں سے صدقہ کرتا ہے وہ یہ اللہ تعالیٰ صرف پاکیزہ چیز کو ہی قبول کرتا ہے، تو وہ چیز پاکیزہ ہونے کی حالت میں ہی آسمان کی طرف بلند ہوتی ہے اور وہ حق کی جگہ پر رکھی جاتی ہے اس کی حالت یہ ہوتی ہے کہ پروردگار اسے اپنے دائیں ہاتھ میں رکھ لیتا ہے پھر وہ اسے بڑھانا شروع کرتا ہے، جس طرح کوئی شخص اپنے جانور کے بچے کو پالتا پوسٹا ہے یہاں تک کہ ایک لقمہ یا ایک کھجور جب قیامت کے دن آئیں گے، تو وہ بڑے پہاڑ کی مانند ہوں گے نبی اکرم صلی اللہ علیہ وسلم نے (یا سیدنا ابو ہریرہ رضی اللہ عنہ نے یہ آیت تلاوت کی) ’’وہی وہ ذات ہے، جو اپنے بندوں سے توبہ قبول کرتا ہے اور صدقات وصول (یعنی قبول) کرتا ہے۔‘‘‘‘\nتخریج: ايضا"}],[1186,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مملوک غلام کا کھانا پینا اور اس کا لباس مالک کے ذمہ ہے اور اس کو صرف اس کام پر مامور کیا جائے جس کے کرنے کی وہ طاقت رکھتا ہو۔ (1)","",{"k":"(1) صحیح مسلم (1662)، الادب المفرد للبخاری (192)، مسند احمد (247/2)، مسند الشافعی (66/2)، مصنف عبدالرزاق (17967)، صحیح ابن حبان (4313)، سنن الکبری للبیہقی (6/8)، شرح السنة للبغوی (2403)۔","f":"اس حدیث میں غلام کے بعض احکام بیان ہوئے ہیں، مثلاً غلام کا کھانا اور لباس اس کے مالک کے ذمہ ہے، اور مالک غلام کی طاقت کے مطابق کام لے سکتا ہے، اس پر زیادتی کرنا حرام ہے، اس غلام سے مراد وہ انسان ہے جو جنگ وغیرہ میں کافروں سے مسلمانوں کے قبضے میں آ جائے۔ آج کل گھروں میں کام کرنے والے خادم اور نوکر شرعی غلام نہیں ہیں، ہاں ان کے ساتھ بھی اچھا سلوک کرنے کی تاکید کی گئی ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’غلام کو خوراک اور لباس فراہم کیا جائے گا، اور اسے ایسے کام کا پابند نہیں کیا جائے گا، جس کی وہ طاقت نہ رکھتا ہو۔‘‘\nتخریج: اخرجه مسلم في الايمان"}],[1187,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہم نے ان سے صلح نہیں کی جب سے ہم نے ان سے جنگ کی ہے اور جو شخص ان کو خوف کی وجہ سے نہ مارے تو وہ ہم میں سے نہیں ہے، آپ صلی اللہ علیہ وسلم کی مراد سانپ ہیں۔ (1)","",{"k":"(1) حسن صحیح، سنن ابی داود (5248)۔ مسند احمد: 247/2، 432۔ صحیح ابن حبان: 5644۔","f":"اس حدیث میں سانپ کے مارنے کا حکم دیا گیا ہے، کہ جہاں اس کو دیکھو، اس کو مار دو، خواہ وہ حرم میں بھی کیوں نہ ہو، مدینہ منورہ میں بعض سانپ موجود تھے، تو ان کے مارنے سے آپ صلی اللہ علیہ وسلم نے منع فرمایا تھا، لیکن بعد میں عام حکم دیا کہ جہاں کوئی سانپ ہے اس کو مار دو، اب یہی حکم ہے، نہ مارنے والا حکم منسوخ ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’ہم نے ان سے لڑائی شروع کی ہے ہم نے ان کے ساتھ صلح نہیں کی ہے اور جو شخص ان سے ڈرتے ہوئے ان میں سے کسی ایک شخص کو چھوڑ دے اس کا ہم سے کوئی تعلق نہیں۔‘‘ نبی اکرم صلی اللہ علیہ وسلم کی مراد سانپ تھے۔\nتخریج: اخرجه ابن حبان في صحيحه"}],[1188,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کو جب چھینک آتی تو منہ کو کپڑے وغیرہ سے ڈھانپ لیتے اور چھینک کی آواز پست رکھتے تھے۔ (1)","",{"k":"(1) حسن صحیح، سنن ابی داود (5029)۔ سنن الترمذی (2745)۔ مسند احمد: 439/2۔ سنن الکبری للبیہقی: 90/2۔ شرح السنة للبغوی: 3346۔ مسند ابی یعلی: 6663۔","f":"اس حدیث میں چھینک کے متعلق ایک مسئلہ بیان ہوا ہے کہ چھینکتے وقت کپڑے سے اپنے منہ کو ڈھانپنا چاہیے، اور چھینک کی آواز پست رکھنی چاہیے، نہ کہ لوگوں کو ڈرا دینا چاہیے۔ اس حدیث سے معلوم ہوا کہ اسلام کس قدر مکمل دین ہے، والحمد للہ، افسوس کہ مسلمان دین کو سمجھنے کی کوشش ہی نہیں کرتے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم جب چھینکتے تھے، تو اپنے چہرے کو ڈھانپ لیتے تھے اور چھینکنے کی آواز کو پست کرتے تھے۔\nتخریج: خرجه البيهقي في المعرفة"}],[1189,"ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: نہیں کوئی قوم جو کسی مجلس میں بیٹھے اور اللہ تعالیٰ کی یاد نہ کرے، تو وہ مجلس اس قوم پر تاوان و نقصان ہو گی۔ (1)","",{"k":"(1) حسن صحیح، سنن ابی داود (4856)۔ عمل الیوم واللیلة للنسائی: 404۔ عمل الیوم واللیلة لابن السنی: 747۔ کتاب الدعاء للطبرانی: 1922۔ مستدرک للحاکم: 492/1۔ من طریق سعید المقبری عن ابی ہریرة۔ مسند احمد: 432/1، 446۔ من طریق سعید عن اسحاق عن ابی ہریرة۔","f":"اس حدیث میں اس مجلس کی مذمت کی گئی ہے جس میں اللہ تعالیٰ کا ذکر نہ ہو، اس سے معلوم ہوا کہ کوئی بھی مجلس ایسی نہیں ہونی چاہیے جس میں اللہ تعالیٰ کا ذکر نہ کیا جائے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کا یہ فرمان نقل کرتے ہیں: ’’جب کچھ لوگ کسی محفل میں بیٹھے ہوئے ہوں اور وہاں اللہ کا ذکر نہ کریں، تو یہ چیز ان کے لیے (قیامت کے دن) حسرت کا باعث ہوگی۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1190,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اپنے آپ کو فحش باتوں سے بچاؤ، اللہ تعالیٰ ناپسند کرتے ہیں فحش گوئی کرنے والے کو اور فحش گوئی سننے والے کو اور ظلم کرنے سے اپنی جان کو بچاؤ، کیونکہ ظلم قیامت کے دن تاریکیاں بن کر چھا جائے گا، اور تم اپنی جان کو بخل سے بچاؤ، پس تحقیق یہ بخل ہی تھا جس نے تم سے پہلے لوگوں کو خون بہانے، قطع رحمی کرنے اور باہمی احترام ترک کرنے کی دعوت دی۔ (1)","",{"k":"(1) الادب المفرد للبخاری (487)، مسند احمد (431/2)، الآداب للبیہقی (97)، صحیح ابن حبان (5177)، مستدرک للحاکم (12/1)۔","f":"اس حدیث میں بے حیائی والی باتوں اور ظلم سے پرہیز کرنے کی تاکید کی گئی ہے، نیز بخل کی حرمت بھی ثابت ہوتی ہے۔ ہر انسان کو اپنے اندر اچھی صفات پیدا کرنی چاہییں، کیونکہ ان سے انسان میں انسانیت پیدا ہوتی ہے، جس کا ہر کسی کو فائدہ ہو گا، اور ہر انسان اپنے آپ کو بری صفات سے بچا کر رکھے، کیونکہ ان میں نقصان ہی نقصان ہے، اپنا بھی اور دوسروں کا بھی۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’فحش باتیں کرنے سے بچو! کیونکہ اللہ تعالیٰ فحاشی کرنے والے اور فحش گفتگو کرنے والے کو ناپسند کرتا ہے اور ظلم کرنے سے بچو کیونکہ ظلم قیامت کے دن تاریکیوں کی شکل میں ہوگا، اور بخل سے بچو! کیونکہ اسی بخل نے تم سے پہلے لوگوں کو خون بہانے، قطع رحمی کرنے اور حرام چیزوں کو حلال کرنے کی ترغیب دی تھی۔‘‘\nتخریج: ايضا"}],[1191,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کوئی شخص اپنے بھائی کو کہتا ہے: اللہ تعالیٰ تجھے جزائے خیر دے تو اس نے اپنے بھائی کی مدح کرنے میں مبالغہ کیا ہے۔ (1)","",{"k":"(1) صحیح لغیرہ، مسند عبد بن حمید: 1418۔ معجم الصغیر للطبرانی: 149/2۔ مصنف ابن ابی شیبة: 70/9۔ مصنف عبدالرزاق: 3118۔ مسند البزار، الکشف: 1944۔ لہ شاہد عن اسامة بن زید رضی اللہ عنہ عند الترمذی (2026)۔","f":"اس حدیث میں ”جزاک اللہ“ کہنے کی فضیلت بیان ہوئی ہے، زندگی میں ہر انسان کسی دوسرے کا محتاج ہے، تو جب بھی کوئی نیکی کرے تو جواب میں ”جزاک اللہ“ کہنا چاہیے، اس سے اس کی حوصلہ افزائی ہو جاتی ہے اور اس سے گلے سے کسی کے سامنے نیکی کے امور پر مدح کرنا بھی ثابت ہوتا ہے۔ ہاں وہ تعریف جس میں مبالغہ ہو، مطلقاً حرام ہے، خواہ جس کی تعریف کی جا رہی ہے، وہ موجود ہو یا نہ موجود ہو۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب کوئی شخص اپنے بھائی سے یہ کہے: اللہ تعالیٰ تمہیں جزائے خیر دے، تو اس نے تعریف میں مبالغہ کر دیا۔‘‘\nتخریج: اخرجه الترمذي في البر والصلة"}],[1192,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: چھینک اللہ کی جانب سے ہے، اور جمائی لینا شیطان کی طرف سے ہے، جب کوئی تم میں سے جمائی لے تو اپنے منہ پر ہاتھ رکھ لے اور جمائی لینے والا جب ہاہ ہاہ کرتا ہے تو یہ شیطان کی طرف سے ہے، جو اس کے پیٹ میں ہنستا ہے۔ (1)","",{"k":"(1) صحیح: سنن الترمذی (2646)، مسند احمد (265/2)، عمل الیوم واللیلة للنسائی (217)، صحیح ابن خزیمة (921)، صحیح ابن حبان (2358)، مستدرک للحاکم (263/4)، من طریق ابن عجلان بھذا الاسناد، صحیح البخاری (6223)، سنن ابی داود (5028)، سنن الترمذی (2727)، الادب المفرد للبخاری (928)، من طریق سعید بن ابی سعید المقبری عن ابیہ عن ابی ہریرة۔","f":"اس حدیث میں چھینک کے اللہ تعالیٰ کی طرف سے ہونے کا بیان ہے، کیونکہ چھینک بطور رحمت ہوتی ہے، جس سے انسان کی طبیعت کھل جاتی ہے۔ جمائی سستی اور غفلت کی علامت ہے، اور یہ شیطان کی طرف سے ہوتی ہے، نیز اس حدیث میں جمائی کے آداب کا بھی ذکر ہے کہ جمائی کے وقت منہ پر ہاتھ رکھنا چاہیے، اور منہ پر ہاتھ رکھنے کا مقصد یہ ہے کہ جب انسان جمائی لیتا ہے تو اس وقت اس کا منہ کھل جاتا ہے، اور اندر سے واضح نظر آتا ہے، ایک تو ہاتھ رکھنے سے منہ کا اندرونی حصہ نظر نہیں آئے گا اور دوسرا جمائی کے وقت منہ سے جو آواز نکلتی ہے، اس پر کنٹرول ہو جاتا ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’چھینک اللہ تعالیٰ کی طرف سے ہوتی ہے اور جمائی شیطان کی طرف سے ہوتی ہے جب کسی شخص کو جمائی آئے، تو وہ اپنا ہاتھ اپنے منہ پر رکھ لے جب وہ ہا، ہا کہتا ہے، تو یہ شیطان کی طرف سے ہوتا ہے، جو اس کے پیٹ میں ہنس رہا ہوتا ہے۔‘‘\nتخریج: متفق عليه"}],[1193,"ابو ہریرہ رضی اللہ عنہ مرفوعاً بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کا ارشاد ہے کہ جب تم کسی قوم تک پہنچے جو بیٹھے ہوں، تو ان کو (السلام علیکم) تم پر سلامتی ہو اور جب تو اس مجلس سے اٹھے تب بھی سلام کہہ کر اٹھو، اول بار آتے ہوئے سلام کہنا آخر بار جاتے ہوئے سلام کہنے سے زیادہ اہم نہیں ہے۔ (1)","",{"k":"(1) حسن صحیح، الادب المفرد للبخاری: 1007۔ سنن ابی داود (5208)۔ سنن الترمذی (2706)۔ عمل الیوم واللیلة للنسائی: 317۔ مسند احمد: 230/2۔ مسند ابی یعلی: 6567۔ صحیح ابن حبان: 494۔ شعب الایمان للبیہقی: 8846۔ شرح السنة: 3328۔","f":"اس حدیث سے ”السلام علیکم“ کہنے کی اہمیت واضح ہوتی ہے کہ جب آپ ایک مجلس میں جائیں تو بھی السلام علیکم کہیں اور جب واپس اٹھیں پھر بھی السلام علیکم کہیں۔ جس طرح مجلس میں جاتے وقت سلام کہنا ثواب ہے، اسی طرح مجلس سے اٹھتے وقت بھی سلام کہنے کا ثواب ہے، ان دونوں وقتوں میں سلام کہنے سے سستی نہیں کرنی چاہیے، بعض لوگ جب مجلس میں جاتے ہیں تو سلام کہتے ہیں لیکن جب واپس آتے ہیں تو سلام نہیں کہتے جو کہ درست نہیں ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: انہیں نبی اکرم صلی اللہ علیہ وسلم کے اس فرمان کا پتہ چلا ہے: جب تم کچھ بیٹھے ہوئے افراد کے پاس جاؤ، تو انہیں سلام کرو جب تم اٹھو تو پھر انہیں سلام کرو کیونکہ پہلے والا دوسرے والے کے مقابلے میں زیادہ حق نہیں رکھتا۔\nتخریج: اخرجه ابن حبان في صحيحه"}],[1194,"ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: چار دریا جنت سے ہیں: فرات، سیحان، جیحان اور نیل۔ (1)","",{"k":"(1) صحیح: مسند احمد (261/2)، مسند ابی یعلی (5921)، تاریخ بغداد (54/1)، من طریق ابی سلمة عن ابی ہریرة، صحیح مسلم (2839)، مسند احمد (289/2)، تاریخ بغداد (54/1، 55)، من طریق حفص بن عاصم عن ابی ہریرة۔","f":"اس حدیث میں جنت کی چار نہروں کا ذکر ہے، اور یہ دنیا والی نہریں مراد نہیں ہیں، بلکہ یہ نہریں جنت میں ہوں گی، بطور فائدہ عرض ہے کہ ماوراء النہر جہاں سے اللہ تعالیٰ نے بہت زیادہ محمد شین پیدا کیے ہیں، یہ علاقے دریائے جیحوں سیحوں سے آگے ہیں، اور واراء النہر سے مراد یہی دریا ہے، اور یہ دریا افغانستان کے ساتھ ہے۔ سمرقند (بخارا) وغیرہ واراء النہر کے علاقے میں ہی آتے ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کا یہ فرمان نقل کرتے ہیں: ’’چار نہروں کا تعلق جنت سے ہے فرات، سیہان، جیحان، نیل۔‘‘\nتخریج: اخرجه مسلم في الجنه"}],[1195,"وہب بن کیسان بیان کرتے ہیں کہ میں نے ابو ہریرہ کو دیکھا، انھوں نے شام کی نماز مدینہ منورہ اس دن پڑھائی جبکہ حاجیوں کی پہلی جماعت حج سے لوٹ کر آئی اور بعد نماز ابو ہریرہ نے فرمایا: تمام خوبیوں اور بھلائیوں میں سبقت تو ابوالقاسم صلی اللہ علیہ وسلم ہی نے حاصل کی ہیں، ذکوان مولی مروان حجاج سے پہلے آچکا ہے اور اس نے لوگوں کی خیریت و سلامتی کی خبر پہنچائی ہے، تو ذکوان نے کہا: وہ میں ہی ہوں جو رات کا سفر برداشت کر کے اہل منیٰ سے چل کر اہل یثرب تک پہنچا ہوں۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ، وہب بن کیسان نے ابو ہریرہ رضی اللہ عنہ کو دیکھا ہے لیکن ان سے کچھ سنا نہیں ہے۔","u2":"وہب بن کیسان بیان کرتے ہیں: میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو مدینہ منورہ میں اس شام کو نماز ادا کرتے ہوئے دیکھا جب پہلے دن لوگ روانہ ہوتے ہیں پھر انہوں نے بتایا: حضور ابو القاسم صلی اللہ علیہ وسلم بھلائی کے معاملے میں سبقت لے جاتے تھے لیکن مروان کا غلام ذکوان حاجیوں سے آگے نکل گیا اس نے لوگوں کے بارے میں سلامتی کی اطلاع دی۔ سفیان کہتے ہیں: ذکوان نے یہ شعر کہا تھا: ’’میں وہ شخص ہوں جس نے اس (شواری کو) اہلِ منیٰ کی طرف سے اہلِ یثرب کی طرف تیزی سے جانے کا پابند کیا۔‘‘"}],[1196,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بنی اسرائیل کے واقعات نقل کرو، اس میں کوئی حرج نہیں اور میری احادیث بھی لوگوں سے بیان کرو اور میرے اوپر جھوٹ نہ بولو۔ (1)","",{"k":"(1) صحیح: سنن ابی داود (3662)، مسند احمد (474/2)، مصنف ابن ابی شیبہ (62/9)، شرح مشکل الآثار للطحاوی (135)۔","f":"اس حدیث میں بنو اسرائیل کے واقعات کو بیان کرنے کے جواز کا ذکر ہے، یاد رہے بنو اسرائیل کی روایات تین طرح کی ہیں: (1) ایسی روایات جو قرآن وحدیث کے موافق ہوں۔ (2) ایسی روایات جن کے بارے میں ہماری شریعت خاموش ہے۔ ان دونوں قسموں کی روایات کو بیان کرنا درست ہے، کوئی حرج نہیں ہے۔ (3) تیسری قسم کی وہ روایات ہیں جو قرآن وحدیث کے مخالف ہیں، یا قرآن وحدیث نے اُن کی نفی کر دی ہے یا اُن کو منسوخ کر دیا ہے، ان کو بیان کرنا درست نہیں ہے۔ نیز اس حدیث میں رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ بولنا حرام قرار دیا گیا ہے، اس حدیث سے اُن علماء کی زبردست مذمت ثابت ہوتی ہے جو لوگوں میں جھوٹی اور من گھڑت روایات بیان کرتے ہیں، دین قرآن مجید اور صحیح احادیث کا نام ہے، جھوٹی اور ضعیف روایات کا دین سے کوئی تعلق نہیں ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’تم لوگ بنی اسرائیل کے حوالے سے روایات نقل کر دو! اس میں کوئی حرج نہیں ہے اور تم لوگ میرے حوالے سے بھی باتیں بیان کرو، تاہم میری طرف جھوٹی بات منسوب نہ کرنا۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1197,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے میرے اوپر جان بوجھ کر جھوٹ بولا تو اس نے اپنا ٹھکانا جہنم میں بنالیا۔ (1)","",{"k":"(1) صحیح البخاری (110)۔ صحیح مسلم (3)۔ سنن ابن ماجہ (24)۔ مسند احمد: 413/2، 501۔ سنن الدارمی (599)۔ صحیح ابن حبان: 28۔ من عدة طرق عن ابی ہریرہ۔","f":"اس حدیث میں رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ بولنے کی مذمت وارد ہوئی ہے، نیز دیکھیے ماقبل حدیث کی شرح۔ امام ابن حبان نے اس حدیث سے استدلال کیا ہے کہ ”باب وجوب دخول النار من نسب شيئًا إلى المصطفى وهو لا يعرف صحته (اس شخص کے جہنم میں داخل ہونے کے وجوب کا بیان جس نے نبی کریم صلی اللہ علیہ وسلم کی طرف کوئی بات منسوب کی اور وہ اس کی صحت کو بھی نہیں پہچانتا)۔ (صحیح ابن حبان) یہاں سے معلوم ہوا کہ حدیث کو بیان کرنے سے پہلے اس کی تحقیق کرنا فرض ہے، افسوس موجودہ دور میں اکثر مبلغین و مدرسین اور مصنفین علم جرح و تعدیل، علم علوم حدیث اور فن تخریج و تحقیق سے ناواقف ہیں، جو آدمی ان فنون سے ناواقف ہے، اس کے پاس کسی حدیث کی تحقیق کرنے کا فن ہی نہیں ہے، تو وہ کیونکر منبر و محراب کا وارث بنا ہوا ہے، اسے تو جہنم سے ڈرنا چاہیے، اور علوم دینیہ میں زبردست مہارت حاصل کرنی چاہیے، کہ کہیں وہ جھوٹی روایات کو نبی کریم صلی اللہ علیہ وسلم کی طرف منسوب نہ کر بیٹھے کیونکہ یہ کبیرہ گناہ ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کا یہ فرمان نقل کرتے ہیں: ’’جو شخص جان بوجھ کر میری طرف جھوٹی بات منسوب کرے گا وہ جہنم میں اپنی مخصوص جگہ پر پہنچنے کے لیے تیار ہو جائے۔‘‘\nتخریج: اخرجه البخاري في العلم"}],[1198,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو بھی جابر سرکش اہل مدینہ کے ساتھ بدی کا ارادہ کرے گا، اس کو اللہ تعالیٰ جہنم کی آگ میں اس طرح پگھلائے گا جیسے کہ پانی میں نمک پگھلتا ہے اور نہیں صبر کرے گا کوئی شخص اس کی ہلاکتوں اور سختیوں پر مگر میں اس کے لیے قیامت کے دن گواہ اور شفاعت کرنے والا ہوں گا۔ (1)","",{"k":"(1) صحیح مسلم (1386)، سنن الکبری للنسائی (4268)، مسند احمد (279/2)، مصنف عبدالرزاق (17155)، تاریخ کبیر للبخاری (236/1، 237)، حلیة الاولیاء (42/9)، صحیح ابن حبان (3737)، من طریق ابی عبداللہ القراظ عن ابی ہریرہ، سنن ابن ماجہ (3114)، مسند ابی یعلی (5991)، من طریق ابی سلمة عن ابی ہریرہ۔","f":"اس حدیث میں مدینہ کی فضیلت بیان کی گئی ہے کہ جو شخص مدینہ کے ساتھ برائی کا ارادہ رکھے گا اور اس کے ساتھ فتنہ و فساد کرنے کی کوشش کرے گا، اللہ تعالیٰ اس کو تباہ و برباد فرما دے گا، نیز اس حدیث میں مدینہ میں رہنے والوں کے لیے نبی کریم صلی اللہ علیہ وسلم کی قیامت والے دن سفارش کا ثبوت بھی ملتا ہے، مدینہ میں رہنے والوں کو اگر کسی مشکل کا سامنا بھی ہو تب بھی وہ مدینہ نہ چھوڑیں، کیونکہ جب وہ مدینہ چھوڑ جائیں گے تو قیامت کے دن نبی کریم صلی اللہ علیہ وسلم کی سفارش سے محروم ہو جائیں گے، اے اللہ! ہمیں بھی مکہ یا مدینہ میں مستقل رہنے کا شرف عطا فرما، بے شک تو ہر چیز پر قادر ہے، آمین۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جو بھی ظالم شخص اہل مدینہ کے ساتھ برائی کا ارادہ کرے گا اللہ تعالیٰ اسے جہنم میں یوں گھول دے گا، جس طرح نمک پانی میں گھل جاتا ہے اور جو شخص یہاں کی سختی اور شدت پر صبر سے کام لے گا، میں قیامت کے دن اس کے لیے گواہ ہوں گا (راوی کو شک ہے شاید یہ الفاظ ہیں) اس کی شفاعت کروں گا۔‘‘\nتخریج: اخرجه مسلم في الحج"}],[1199,"ابو ہریرہ رضی اللہ عنہ نے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عورت پسلی سے پیدا کی گئی ہے جو تیرے لیے کسی طریقہ پر بھی سیدھی نہیں ہوگی، پس اگر تو اس سے فائدہ لینا چاہے تو اس کی کجی کے ساتھ فائدہ اٹھاتا رہ، اگر تو اس کو سیدھا کرنا چاہے گا تو ٹیڑھی پسلی کو توڑ دے گا، اور اس کا توڑنا طلاق دینا ہے۔ (1)","",{"k":"(1) صحیح البخاری (5184)، صحیح مسلم (1468)، مسند احمد (449/2)، سنن الدارمی (2228)، صحیح ابن حبان (3179)، سنن الکبری للبیہقی (295/7)، شرح السنة للبغوی (2333)۔","f":"اس حدیث میں عورت کی حقیقت بیان کی گئی ہے کہ عورت فطری طور پر کج روی اور ٹیڑھے پن کو پسند کرتی ہے، اور اکثر معاملات میں یہ الٹ جاتی ہے، اس فطری کمزوری کے باوجود عورت کو ہی دنیا کی سب سے بہترین چیز کہا گیا ہے، جب وہ نیک ہو اور عورت کو ہی شیطان کی رسیاں کہا گیا ہے، جب عورت نیکی اور تقویٰ سے دور ہو۔ انسان کو عورت بہت زیادہ فائدہ پہنچاتی ہے، مثلاً تسکین کا باعث ہے، ایمان کی حفاظت کا باعث ہے، اللہ تعالیٰ اس سے اولاد پیدا فرماتا ہے، امور خانہ کی حکمران ہے، وغیرہ۔ جب اس قدر زیادہ فوائد عورت سے حاصل ہوتے ہیں تو اس کے چھوٹے موٹے ٹیڑھے پن کو بھی برداشت کرنا چاہیے، یہ بھی یاد رہے کہ اس حدیث کا ہرگز یہ مطلب نہیں ہے کہ مرد ٹیڑھے نہیں ہوتے، موجودہ دور میں کس قدر زیادہ مرد عورتوں سے بھی بدتر نظر آتے ہیں، صحیح تعلیم و تربیت کے فقدان کی وجہ سے، اللہ تعالیٰ ہمارے مسلمانوں کو قرآن و حدیث کا شعور عطا فرمائے، آمین۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’عورت کو پسلی سے پیدا کیا گیا ہے وہ کسی بھی صورت میں تمہارے لیے سیدھی نہیں ہو سکتی، اگر تم اس سے نفع حاصل کرنا چاہتے ہو تو اس کے ٹیڑھے پن سمیت اس سے نفع حاصل کرو اگر تم اسے سیدھا کرنے کی کوشش کرو گے، تو اسے توڑ دو گے اور اسے توڑنے سے مراد اسے طلاق دینا ہے۔‘‘\nتخریج: متفق عليه"}],[1200,"ابو ہریرہ نے فرمایا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یہود بنو قینقاع کے ساتھ ان کی درسگاہ تک گیا، وہاں رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا، جو زعفران والی خوشبو میں لت پت تھا تو میں نے کہا: تو بیاہتا ہوگا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کو لے جا کر دھو پھر خشک کر، پھر دھو، پھر خشک کر اور پھر دھو کر خشک کر دے۔ (1)","",{"k":"(1) اسنادہ ضعیف: عمران بن ظبیان ضعیف اور اس کا شیخ مجہول راوی ہے، سنن النسائی (5123)۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ بنو قینقاع کے یہودیوں کی طرف گیا جو انہیں درس دیا کرتے تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا جس نے اچھی طرح خوشبو لگائی ہوئی تھی میں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! شاید اس کی نئی نئی شادی ہوئی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم جاؤ اور اسے دھولو اور اچھی طرح دھولو پھر اسے دھوؤ اور اچھی طرح دھولو اور اچھی طرح دھولو۔\nتخریج: اخرجه النسائي في الزينه"}],[1201,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بدترین کھانا دعوت ولیمہ ہے جس پر آنے والا روک دیا جائے اور دعوت اس کو دی جائے جو آنا نہیں چاہتا، اور جس نے دعوت قبول نہ کی اس نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کی۔ (1)","",{"k":"(1) صحیح مسلم (1432)، سنن الکبری للبیہقی (262/7)، سنن سعید بن منصور (526)، شرح معانی الآثار للطحاوی (143/4)۔","f":"اس حدیث میں دعوت سے روک دیا جائے سے مراد غریب لوگ ہیں، کیونکہ وہ شادی کے موقع کے انتظار میں ہوتے ہیں کہ کب شادی آئے اور ہم پیٹ بھر کر کھانا کھائیں، شادی بیاہ کے موقع پر محلہ کے غریبوں کو بھی دعوت دینی چاہیے، اور اس حدیث میں جو دعوت پر نہیں آنا چاہتے، سے مراد امیر لوگ ہیں، کیونکہ امیر لوگ اپنے گھروں میں کئی قسموں کے پُر تکلف کھانے کھاتے رہتے ہیں، ان کو ولیمہ وغیرہ کی دعوت کا خاص شوق نہیں ہوتا، نیز اس حدیث سے ثابت ہوا کہ دعوت کو قبول کرنا واجب ہے، خواہ ایک لقمہ ہی کھائیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کا یہ فرمان نقل کرتے ہیں: ’’سب سے برا کھانا ولیمے کا وہ کھانا ہے، جس میں شریک ہونے والے کو روک دیا جائے اور اس کی دعوت اسے دی جائے، جو اس کا انکار کرے، جو شخص دعوت قبول نہیں کرتا وہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کرتا ہے۔‘‘\nتخریج: متفق عليه"}],[1202,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: بدترین کھانا دعوت ولیمہ ہے جس میں اغنیاء کو دعوت دی جائے اور غرباء کو روکا جائے اور جو دعوت قبول نہ کرے اس نے اللہ تعالیٰ اور اس کے رسول کی نافرمانی کی۔ (1)","",{"k":"(1) صحیح البخاری (5177)، صحیح مسلم (1432)، سنن ابی داود (3742)، سنن ابن ماجہ (1908)، سنن الکبری للنسائی (6567)، مسند احمد (240/2، 241)، سنن الدارمی (2072)، مؤطا امام مالک (ص 343)، سنن الکبری للبیہقی (262/7)۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: سب سے برا کھانا اس ولیمے کا کھانا ہے، جس میں امیروں کو بلایا جاتا ہے اور غریبوں کو روک دیا جاتا ہے، جو شخص دعوت قبول نہیں کرتا وہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کرتا ہے۔\nتخریج: ايضا"}],[1203,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: ایک آدمی نے انصار میں سے ایک عورت سے نکاح کرنے کا ارادہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس عورت کو ایک نگاہ دیکھ لو، انصار کی خواتین کی آنکھوں میں چھوٹا پن ہوتا ہے۔ (1)","",{"k":"(1) صحیح مسلم (1424)، سنن النسائی (3236)، مسند احمد (286/2)، سنن سعید بن منصور (523)، شرح معانی الآثار للطحاوی (84/7)، صحیح ابن حبان (4041)، سنن الدارقطنی (253/3)، سنن الکبری للبیہقی (14/3)۔","f":"اس حدیث سے ثابت ہوا کہ جب کسی عورت سے منگنی کا عزم ہو، گھر والے اس رشتے پر راضی ہوں، تو لڑکا منگنی سے پہلے ایک دفعہ اس لڑکی کو دیکھ سکتا ہے، افسوس کی بات ہے کہ بے غیرتی کی انتہا ہوگئی ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: ایک شخص نے کسی انصاری خاتون کے ساتھ شادی کرنے کا ارادہ کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم اسے دیکھ لو کیونکہ انصاری خواتین کی آنکھوں میں کچھ ہوتا ہے۔ امام حمیدی رحمہ اللہ کہتے ہیں: یعنی وہ کچھ چھوٹی ہوتی ہیں۔\nتخریج: اخرجه مسلم في النكاح"}],[1204,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تحقیق اللہ تبارک و تعالیٰ نے میری امت کو وسوسہ معاف کر دیا ہے، جب تک اس پر عمل نہ کرے، یا زبان سے نہ بولے۔ (1)","",{"k":"(1) صحیح البخاری (2528)، صحیح مسلم (127)، سنن ابی داود (2209)، سنن الترمذی (1183)، سنن النسائی (3464)، سنن ابن ماجہ (2040)، مسند احمد (255/2)، صحیح ابن خزیمة (898)، صحیح ابن حبان (3435)، مسند ابی یعلی (6390)، سنن الکبری للبیہقی (209/7، 298)۔","f":"اس حدیث سے ثابت ہوا کہ دل کے بُرے وسوسے قابل گرفت نہیں ہیں، جبکہ نیکی کا معاملہ اس کے برعکس ہے کہ جو شخص کسی اچھے کام کی نیت کر لے، اس کو نیت کرنے سے ثواب مل جائے گا، اسلام نیکی کی دعوت دیتا ہے، اور امت مسلمہ کو نیکی کے کاموں اور نیکی کے ارادوں کی رغبت دلاتا ہے، مومن کا سینہ نیکی اور تقویٰ سے سرشار ہوتا ہے، گناہ کا کوئی بھی خیال آجائے تو جلد ہی دفع ہو جاتا ہے، لیکن گناہگار کا سینہ فسق و فجور سے بھرا ہوتا ہے، جو اسے نیکی کا کام کرنے کی فرصت نہیں دیتا، اللہ رب العالمین دل کو دیکھتے ہیں، تو ہمیں بھی اپنے دل کو پاک و صاف رکھنا چاہیے، لوگوں نے اپنے چہرے اور کپڑوں کو تو صاف رکھا لیکن دل صاف نہ کر سکے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’بے شک اللہ تعالیٰ نے میری امت کے ان وسوسوں سے درگزر کیا ہے جو ان کے ذہن میں پیدا ہوتے ہیں، جب تک وہ اس پر عمل نہیں کرتے یا اس کے بارے میں بات چیت نہیں کرتے۔‘‘\nتخریج: متفق عليه"}],[1205,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے بیان کیا کہ سلیمان بن داؤد علیہ السلام نے کہا: میں آج رات کو ستر بیویوں کے قریب جاؤں گا، ہر ایک ان میں سے ایک لڑکا جنے گی، جو اللہ عزوجل کی راہ میں جہاد کرے گا، تو ان کے رفیق نے کہا یا فرشتے نے کہا: ان شاء اللہ کہیں، لیکن وہ کہنا بھول گئے، وہ ستر ازواج کے پاس تو گئے پس نہ جنا ان میں سے کسی نے بھی، مگر ایک عورت نے نصف جسم والا لڑکا جنا، اس بیان کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر وہ ان شاء اللہ کہتے تو اپنی بات میں حانث نہ ہوتے اور اپنی حاجت بھی پاتے۔ (1)","",{"k":"(1) صحیح البخاری (6270)، صحیح مسلم (1654)، سنن النسائی (3862)، طبقات ابن سعد (146/8)، صحیح ابن حبان (4338)، سنن الکبری للبیہقی (44/10)۔","f":"اس حدیث سے ہر کام کے ساتھ ان شاء اللہ کہنے کی فرضیت ثابت ہوتی ہے، اگر کوئی نبی کسی کام کا ارادہ کرتا ہے اور اس ارادے کو عملی جامہ بھی پہناتا ہے لیکن ان شاء اللہ نہیں کہتا تو اس نبی کا کام بھی نہیں ہوتا، چہ جائیکہ کوئی عام انسان کسی کام کا ارادہ کرے اور اس کے ساتھ ان شاء اللہ نہ کہے، نیز اس حدیث سے یہ بھی ثابت ہوتا ہے کہ نیت اور کام کتنے ہی اچھے کیوں نہ ہوں، اس کے ساتھ ان شاء اللہ ضرور کہنا چاہیے، اگر کوئی آدمی ان شاء اللہ کہنا بھول جائے تو دوسرے کو اُسے یاد کرا دینا چاہیے، اس حدیث سے یہ بھی ثابت ہوا کہ انبیاء کرام علیہم السلام مشکل کشا نہیں ہوتے، مشکل کشا صرف اللہ تعالیٰ کی ذات ہے، انبیاء علیہم السلام میں عام انسانوں سے چالیس گنا زیادہ طاقت ہوتی ہے۔ انسان کے اپنی اولاد کے بارے میں اچھے جذبات ہونے چاہئیں کہ اگر اللہ تعالیٰ مجھے اولاد دے گا تو وہ مجاہد بنے گی، یا محدث، محقق، امام کعبہ، پوری دنیا پر اسلام کو غالب کرے گی، اے اللہ! ہماری اولاد کو ایسا ہی کرنا، آمین۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’حضرت سلیمان علیہ السلام نے قسم اٹھاتے ہوئے یہ کہا: آج رات میں اپنی ۷۰ بیویوں کے ساتھ صحبت کروں گا اور وہ سب لڑکوں کو جنم دیں گی جو اللہ کی راہ میں جہاد کریں گے ان کے ساتھی نے (راوی کو شک ہے شاید یہ الفاظ ہیں) فرشتے نے ان سے کہا: آپ انشاء اللہ کہہ دیجئے! لیکن انہیں خیال نہیں رہا اور انہوں نے اپنی ۷۰ بیویوں کے ساتھ صحبت کی، تو ان میں سے صرف ایک کے ہاں بچہ پیدا ہوا، جو نامکمل تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اگر وہ انشاء اللہ کہہ دیتے، تو ان کی قسم نہ ٹوٹتی اور وہ اپنا مقصد بھی حاصل کر لیتے۔‘‘\nتخریج: ايضا"}],[1206,"ہم سے حمیدی نے بیان کیا۔ وہ سفیان سے، وہ ہشام بن حجیر تیمی سے، وہ طاؤس سے، وہ ابو ہریرہ سے، وہ نبی کریم صلی اللہ علیہ وسلم سے مثل اس کے روایت کرتے ہیں۔ (1)","",{"k":"(1) صحیح البخاری (6720)، صحیح مسلم (1654)، سنن النسائی (3887)، مسند احمد (275/2)، صحیح ابن حبان (4338)۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: یہی روایت ایک اور سند کے ہمراہ بھی منقول ہے۔\nتخریج: ايضا"}],[1207,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ایک شخص آیا اور اس نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس ایک دینار ہے، آپ نے فرمایا: اپنے اوپر خرچ کر، اس نے کہا: میرے پاس ایک دوسرا دینار بھی ہے، آپ نے فرمایا: اپنے بچے پر خرچ کر، اس نے کہا: میرے پاس ایک تیسرا دینار بھی ہے، آپ نے فرمایا: اس کو اپنے گھر والوں پر خرچ کر، اس نے کہا: میرے پاس ایک چوتھا دینار بھی ہے، آپ نے فرمایا: اس کو اپنے خدمتگار پر صرف کر، اس نے کہا: میرے پاس ایک مزید بھی ہے، اے اللہ کے رسول صلی اللہ علیہ وسلم! آپ نے فرمایا: پھر تو جانے۔ راوی سعید نے کہا: ابو ہریرہ جب یہ حدیث بیان کرتے تو پھر کہتے: تیرا بیٹا کہتا ہے: میرے اوپر خرچ کر تو مجھے کس پر چھوڑے گا؟ تیری بیوی کہتی ہے: مجھ پر خرچ کر، ورنہ طلاق دے دے اور تیرا غلام کہتا ہے: میرے اوپر خرچ کر، ورنہ مجھے فروخت کر دے۔ (1)","",{"k":"(1) حسن، الادب المفرد للبخاری: 197۔ سنن ابی داود (1691)۔ سنن النسائی (2537)۔ مسند احمد: 151/2۔ مسند الشافعی: 63/2، 64۔ صحیح ابن حبان: 3337۔ مستدرک للحاکم: 415/:۔ سنن الکبری للبیہقی: 466/7۔ وقول ابی ہریرہ رضی اللہ عنہ فی صحیح البخاری (5355)۔","f":"اس حدیث سے ثابت ہوا کہ کس پر خرچ کیا جائے، شریعت نے اس کے بھی مرتبے مقرر کیے ہیں، پہلے اپنے نفس پر، پھر اپنی اولاد پر، پھر اپنے گھر والوں پر، پھر اپنے خادم پر، اگر پھر بھی گنجائش ہو تو پھر جس کو مستحق سمجھے اس کو دے دے، وہ لوگ غلطی پر ہیں جو اپنوں کو بھوکا چھوڑ دیتے ہیں اور دوسروں پر خرچ کرتے ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، اس نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس ایک دینار موجود ہے (میں اس کا کیا کروں؟) نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم اسے اپنے اوپر خرچ کرؤ اس نے عرض کی: میرے پاس ایک اور بھی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے تم اپنی اولاد پر خرچ کرو! اس نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس ایک اور بھی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اسے تم اپنے بیوی پر خرچ کرو! اس نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس ایک اور بھی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے تم اپنے خادم پر خرچ کرو! اس نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس اور بھی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم زیادہ بہتر جانتے ہو گے (کہ اسے کس پر خرچ کیا جائے؟)۔ سعید نامی راوی کہتے ہیں: سیدنا ابو ہریرہ رضی اللہ عنہ یہ حدیث بیان کر لیتے تھے، تو یہ فرمایا کرتے تھے: تمہارا بچہ کہے گا: مجھ پر خرچ کرو مجھے کس کے سپرد کر رہے ہو؟ تمہاری بیوی کہے گی: مجھ پر خرچ کرو ورنہ مجھے طلاق دے دو! تمہارا خادم کہے گا: مجھ پر خرچ کرو یا پھر مجھے فروخت کر دو۔\nتخریج: اخرجه البخاري في النفقات"}],[1208,"عمران بن ظبیان کہتے ہیں: میں نے بنو حنیفہ کے ایک شخص کو بیان کرتے سنا کہ ابو ہریرہ نے فرمایا: کیا تو فلاں فلاں مردوں کو جانتا ہے؟ تو میں نے کہا: ہاں، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ اس فلاں کا پچھلا دانت جہنم میں اتنا ہوگا جتنا احد پہاڑ ہے، وہ شخص مسلمان ہوا تھا پھر مرتد ہوگیا اور یہ کہتا وہ مسیلمہ کذاب سے جا ملا: دو مینڈھے آپس میں ٹکرانے لگے ہیں، میں اپنے مینڈھے کے غالب ہونے کو زیادہ پسند کرتا ہوں۔ (1)","",{"k":"(1) اسنادہ ضعیف، عمران بن ظبیان ضعیف اور اس کا شیخ مجہول ہے۔ نیز دیکھیں: الاصابة: 315/3، 316۔ تمام مرفوع حدیث ان الفاظ کے ساتھ ہے: ”ضرس الکافر فی النار مثل احد“، صحیح مسلم (2851)۔ سنن الترمذی (2579)۔ نیز دیکھیں: الصحیحة للشیخ الالبانی: 1105۔","f":"اس حدیث میں ذکر ہے کہ جہنم کے اندر جہنمی کا دانت احد پہاڑ جتنا ہوگا، جبکہ منہ میں (32) بتیس دانت ہوتے ہیں، گویا کہ جہنمی کے منہ کے اندر (32) بتیس احد پہاڑ ہوں گے، اس حدیث سے ثابت ہوا کہ مرتد کا گناہ کافر سے زیادہ ہے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: کیا تم رجال (بن عنفوہ) کو جانتے ہو؟ میں نے جواب دیا: جی ہاں، تو سیدنا ابو ہریرہ رضی اللہ عنہ نے بتایا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا ہے: جہنم میں اس کی داڑھ احد پہاڑ سے بڑی ہوگی۔ (راوی کہتے ہیں:) یہ شخص پہلے مسلمان ہوا تھا پھر مرتد ہو گیا اور مسیلمہ سے جا کر مل گیا اس نے یہ کہا تھا: دو مینڈھے سینگ لڑا رہے ہیں اور ان میں سے میرے نزدیک پسندیدہ یہ ہے، میرا والا مینڈھا غالب آ جائے۔\nتخریج: اخرجه مسلم في الجنه"}],[1209,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: لوگوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! کیا ہم اللہ تعالیٰ کو قیامت کے دن دیکھیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: جب دوپہر کے وقت سورج بادلوں میں نہ ہو تو اس کے دیکھنے میں تمھیں کوئی مشکل پیش آتی ہے؟ تو لوگوں نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: کیا چودھویں کا چاند جب بادلوں میں نہ ہو تو اس کے دیکھنے میں تمھیں کچھ دقت و ضرر پہنچتا ہے؟ لوگوں نے عرض کی: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! تمھیں کوئی ضرر نہیں ہوگا اپنے رب کو دیکھنے میں مگر اسی طرح جیسا تمھیں ان دو میں سے کسی ایک کو دیکھنے میں دقت پیش نہیں آتی ہے، پس وہ بندے سے ملاقات کرے گا اور فرمائے گا: اے فلاں! کیا میں نے تجھے عزت نہیں دی، تجھے سردار نہیں بنایا، تیرا نکاح نہیں کرایا، تیرے ماتحت گھوڑے اور اونٹ نہیں کیے اور تجھے اس شان سے بڑھایا کہ صاحب ریاست بنا اور چوتھائی غنیمت وصول کرتا رہا؟ تو بندہ کہے گا: ہاں، اے میرے رب! اللہ تعالیٰ فرمائیں گے: کیا تیرا گمان تھا کہ تو میری ملاقات کرے گا؟ بندہ کہے گا: نہیں، اے میرے رب! تو اللہ تعالیٰ فرمائیں گے: میں اسی طرح تجھے بھول جاؤں گا جیسا کہ تو نے مجھے بھلا دیا تھا۔ پھر اسی طرح دوسرے بندے سے ملاقات کریں گے اور فرمائیں گے: اے فلاں! کیا میں نے تجھے عزت نہیں دی تھی، تجھے سردار نہیں بنایا تھا، تیرا نکاح نہیں کرایا تھا، تیرے تابع گھوڑے اور اونٹ نہیں کیے تھے اور تجھے اس طرح نہیں اگایا کہ تو سرداری تک پہنچے اور چوتھائی وصول کرے؟ تو بندہ کہے گا: ہاں، اے میرے رب! تو اللہ تعالیٰ فرمائیں گے: کیا تیرا گمان تھا کہ تو میرے ساتھ ملاقات کرے گا؟ پس وہ بندہ کہے گا: نہیں، اللہ تعالیٰ فرمائیں گے: میں تجھے اسی طرح بھول جاتا ہوں جیسا تو نے مجھے بھلا دیا تھا۔ پھر اللہ تعالیٰ تیسرے بندے سے ملاقات کریں گے، تو وہ بندہ کہے گا: میں تیرے اوپر ایمان لایا، تیری کتاب اور تیرے رسول پر ایمان لایا، نماز پڑھی اور روزے رکھے اور صدقہ زکاة دیے اور اپنی نیکیاں شمار کرے گا جو اس کو طاقت ہوگی، فرمایا جائے گا: یہاں ہی ٹھہر جا، پھر اللہ تعالیٰ فرمائیں گے: کیا ہم اپنا گواہ تیرے اوپر حاضر نہ کریں؟ تو بندہ دل میں خیال کرے گا کہ کون میرے خلاف گواہی دے گا؟ پھر اس کی زبان پر مہر لگا دی جائے گی اور اس کی ران کو حکم ہوگا تو بول! تو اس کی ران بولے گی، اس کا گوشت اور اس کی ہڈیاں بولیں گی اور اس کے اعمال جو بھی ہوں گے سب بیان کریں گی اور یہ عدالت عالیہ کی جانب سے فیصلہ برحق ہونے کا عذر اور دلیل ہوگی، یہ وہ منافق ہوگا جس کو اللہ تعالیٰ ناپسند کرتے ہیں اور اس پر غضبناک ہوتے ہیں، پھر منادی کرنے والا منادی کرے گا: خبردار! ہر امت اپنے اپنے اس معبود کے پیچھے جائے جس کی وہ عبادت کرتی تھی اللہ تعالیٰ کے سوا، پس شیطانوں کے اور صلیب کے پوجنے والے ان کے پیچھے جہنم کی طرف چل پڑیں گے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے ایمان والو! صرف ہم باقی رہ جائیں گے، تو ہمارا رب آئے گا، ہمارا تو صرف وہی رب ہے، وہی ہمیں ثابت قدم رکھے گا، پس اللہ تعالیٰ فرمائیں گے: یہ لوگ کس دین پر تھے؟ تو اہل ایمان کہیں گے: ہم تو اللہ تعالیٰ کے ایماندار بندے ہیں، ہم اللہ تعالیٰ پر ایمان لائے ہیں، ہم اس کے ساتھ کسی کو شریک نہیں ٹھہراتے اور ہم یہاں ہی ٹھہرے رہیں گے یہاں تک کہ ہمارا رب ہمارے اوپر جلوہ گر ہو، ہمارا ایک ہی رب ہے اور وہی ہمارا قائم رکھنے والا ہے، پھر اللہ تعالیٰ انھیں جہنم کے پل پر لے جائیں گے اور وہاں آگ کی سلاخیں ہوں گی جو لوگوں کو پکڑ کر اٹھائیں گی، تو اس وقت شفاعت کی اجازت ہوگی کہ یہ کہہ سکیں: اللھم سلم، اے اللہ! سلامت رکھ، اللھم سلم، اے اللہ! سلامت رکھ، جب یہ لوگ پل پر سے گزر جائیں گے تو جس نے اپنے مال سے دو چیزیں فی سبیل اللہ خرچ کی ہوں گی اس کو جنت کے دربان آواز دیں گے: اللہ کے بندے! اے مسلمان! یہ بہتر جگہ ہے، ادھر آؤ، راوی نے کہا: ابو بکر صدیق رضی اللہ عنہ نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! اس بندے کو تو کوئی پابندی نہیں کہ ایک دروازہ چھوڑ کر دوسرے سے چلا جائے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے جناب ابوبکر صدیق پر اپنا ہاتھ رکھا اور فرمایا: مجھے قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! مجھے امید ہے تو ان لوگوں میں سے ہے۔ (1)","",{"k":"(1) صحیح مسلم (2968)۔ سنن ابی داود (4730)۔ سنن ابن ماجہ (178)۔ سنن الترمذی (2554)۔ مسند احمد: 389/2، 492۔ التوحید لابن خزیمة: 369/1، 371۔ صحیح ابن حبان: 4642۔ الایمان لابن مندہ: 809۔ من طریق ابی صالح عن ابی ہریرہ۔ صحیح البخاری (6573)۔ صحیح مسلم (182)۔ من طریق آخر عن ابی ہریرہ۔","f":"اس حدیث سے ثابت ہوا کہ اللہ تعالیٰ قیامت والے دن لوگوں کو اپنا دیدار کروائیں گے، اس حدیث سے منکرین وجود باری تعالیٰ کا رد ہوتا ہے، بات کی پختگی کے لیے قسم کھانا جائز ہے، اللہ تعالیٰ کلام بھی کرتے ہیں۔ دنیا کی جتنی چیزیں انسان کے تابع ہیں خود انسان ان پر ذرہ برابر بھی طاقت نہیں رکھتا، اللہ تعالیٰ نے اُن کو مسخر کیا ہے، اللہ تعالیٰ قیامت والے دن جسم کے تمام اعضاء کو قوت گویائی عطا فرمائے گا، اس حدیث سے سیدنا ابو بکر رضی اللہ عنہ کی فضیلت ثابت ہوتی ہے۔ ہم قیامت اور روز قیامت ہونے والے تمام غیبی معاملات پر ایمان رکھتے ہیں، جنت برحق ہے، جہنم برحق ہے، جنت کی نعمتیں برحق ہیں اور جہنم کی سزائیں برحق ہیں، پل صراط برحق ہے، جنت کے دروازے برحق ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: لوگوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! کیا قیامت کے دن ہم اپنے پروردگار کا دیدار کریں گے؟ نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: دوپہر کے وقت جب بادل موجود نہ ہوں، تو کیا تمہیں سورج کو دیکھنے میں کچھ مشکل محسوس ہوتی ہے؟ لوگوں نے عرض کی: جی نہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: چودھویں رات میں جب بادل موجود نہ ہوں، تو کیا تمہیں چاند کو دیکھنے میں مشکل ہوتی ہے؟ لوگوں نے عرض کی: جی نہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اس ذات کی قسم! جس کے دست قدرت میں میری جان ہے، تمہیں اپنے پروردگار کا دیدار کرنے میں کوئی رکاوٹ اسی طرح نہیں ہوگی، جس طرح تمہیں ان دونوں میں سے کسی ایک کو دیکھنے میں رکاوٹ نہیں ہوتی۔ اللہ تعالیٰ اپنے بندے سے ملاقات کرے گا اور ارشاد فرمائے گا: ’’اے فلاں! کیا میں نے تمہیں عزت عطا نہیں کی؟ تمہاری شادی نہیں کی؟ تمہارے لیے گھوڑوں اور اونٹوں کو مسخر نہیں کیا اور تمہیں ہر طرح کا موقع فراہم نہیں کیا۔‘‘ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: وہ بندہ عرض کرے گا: جی ہاں! اے میرے پروردگار۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں۔ اللہ تعالیٰ فرمائے گا، کیا تمہیں یہ گمان تھا کہ تم میری بارگاہ میں حاضر ہو گے؟ تو بندہ عرض کرے گا: جی نہیں، تو اللہ تعالیٰ فرمائے گا، پھر میں بھی تمہیں اسی طرح بھول جاتا ہوں، جس طرح تم مجھے بھول گئے تھے۔ پھر اللہ تعالیٰ دوسرے بندے سے ملاقات کرے گا اور فرمائے گا: اے فلاں! کیا میں نے تمہیں عزت عطا نہیں کی میں نے تمہاری شادی نہیں کی میں نے تمہارے لیے گھوڑوں اور اونٹوں کو مسخر نہیں کیا اور میں نے تمہیں ہر طرح کا موقع فراہم نہیں کیا۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: وہ بندہ عرض کرے گا: جی ہاں! اے میرے پروردگار! نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: اللہ تعالیٰ فرمائے گا: کیا تمہیں یہ گمان تھا کہ تم میری بارگاہ میں حاضر ہو گے؟ تو وہ بندہ عرض کرے گا: جی نہیں، تو اللہ تعالیٰ فرمائے گا: میں تمہیں اسی طرح بھول رہا ہوں، جس طرح تم مجھے بھول گئے تھے۔ پھر اللہ تعالیٰ تیسرے بندے سے ملاقات کرے گا، تو وہ عرض کرے گا: میں تجھ پر، تیری کتابوں پر، تیرے رسول صلی اللہ علیہ وسلم پر ایمان لایا، میں نے نماز ادا کی، میں نے روزہ رکھا، میں نے صدقہ کیا اور جہاں تک میری استطاعت تھی میں نے نیکی کی۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں اللہ تعالیٰ فرمائے گا: یہ تو ہے، پھر اللہ تعالیٰ فرمائے گا: کیا ہم تمہارے خلاف گواہ کو نہ لے کر آئیں، تو وہ بندہ اپنے ذہن میں سوچے گا، میرے خلاف کون گواہی دے سکتا ہے؟ تو اس شخص کے منہ پر مہر لگا دی جائے گی اور اس کے زانوں سے کہا جائے گا: تم بولو! تو اس کا زانو بولے گا: اس کا گوشت اس کی ہڈیاں بولیں گے اس کے ان اعمال کے بارے میں، جو وہ کرتا رہا تھا ایسا اس وجہ سے ہو گا تاکہ وہ اپنی طرف سے کوئی عذر پیش نہ کر سکے اور یہ منافق شخص ہو گا اور یہ وہ شخص ہو گا، جس پر اللہ تعالیٰ ناراضگی ظاہر کرے گا۔ پھر ایک اعلان کرنے والا یہ اعلان کرے گا: خبردار! ہر گروہ اس کے پیچھے چلا جائے، جس کی وہ اللہ تعالیٰ کو چھوڑ کر عبادت کیا کرتے تھے، تو شیاطین اور صلیب کی پیروی کرنے والے ان کے پیچھے جہنم کی طرف جائیں گے۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: اے اہل ایمان! پھر ہم لوگ باقی رہ جائیں گے ہمارا پروردگار ہمارے پاس تشریف لائے گا وہ ہمارا پروردگار ہو گا وہ ہمیں ثواب عطا کرے گا وہ فرمائے گا: یہ لوگ کون سے مذہب پر ہیں، تو وہ کہیں گے، ہم اللہ تعالیٰ کے بندے ہیں، ہم مومن ہیں، ہم اللہ تعالیٰ پر ایمان رکھتے ہیں، ہم کسی کو اس کا شریک نہیں ٹھہراتے، ہم یہیں ٹھہرے رہیں گے، جب تک ہمارا پروردگار نہیں آ جاتا، جو ہمارا پروردگار ہے اور وہ ہمیں ثواب عطا کرے گا۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں پھر بندہ چلتا ہوا پل صراط تک آئے گا، جس پر آگ سے بنے ہوئے آنکڑے لگے ہوئے ہوں گے جو لوگوں کو اچک رہے ہوں گے اس وقت شفاعت حلال ہوگی (اور بندہ دعا کرے گا) اے اللہ تو سلامتی عطا کر۔ اے اللہ تو سلامتی عطا کر۔ جب لوگ پل صراط سے گزر جائیں گے، تو ہر وہ شخص جس نے اپنے مال میں سے اللہ کی راہ میں کسی بھی چیز کا جوڑا دیا ہوگا، تو جنت کا ہر دربان اسے بلائے گا: اے اللہ کے بندے! اے مسلمان یہ زیادہ بہتر ہے تم ادھر آؤ۔ راوی کہتے ہیں: سیدنا ابو بکر رضی اللہ عنہ نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! ایسے بندے کو تو کوئی خسارہ نہیں ہو گا کہ وہ ایک دروازے کو چھوڑ کر دوسرے سے اندر چلا جائے؟ راوی کہتے ہیں: تو نبی اکرم صلی اللہ علیہ وسلم نے اپنا ہاتھ ان پر مارا اور فرمایا: اس ذات کی قسم! جس کے دست قدرت میں محمد صلی اللہ علیہ وسلم کی جان ہے، مجھے یہ امید ہے، تم ان افراد میں سے ایک ہو گے (جنھے جنت کے تمام دروازوں کے دربان بلائیں گے)\nتخریج: متفق عليه"}],[1210,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب قیامت قائم ہوگی تو اس وقت دو اشخاص ایک دوسرے سے کپڑا خرید رہے ہوں گے، نہ بیچ مکمل کر سکیں گے اور نہ کپڑا لپیٹ سکیں گے۔ (1)","",{"k":"(1) صحیح مسلم (2954)۔ مسند ابی یعلی: 6271۔ وانظر الحدیث المتقدم برقم: 1131۔","f":"اس حدیث سے ثابت ہوا کہ قیامت اچانک آئے گی، اور لوگوں کے تصور میں بھی نہیں ہو گا حتی کہ لوگ اپنے اپنے کاموں میں مصروف ہوں گے، اس حدیث سے ایک بہت بڑی حقیقت واضح ہوتی ہے جس سے انسان غافل ہے، انسان کو ہمیشہ موت اور قیامت کو یاد رکھنا چاہیے، اپنے کاروبار میں مصروف ہو کر اللہ تعالیٰ سے غافل نہیں ہونا چاہیے، یہ مال و دولت جس کی خاطر انسان اپنی آخرت تباہ کر بیٹھتا ہے، جب موت یا قیامت آئے گی یہ مال یہاں کا یہاں ہی رہ جائے گا، اللہ تعالیٰ ہمیں ایمان کی حالت میں موت عطا فرمائے (آمین) اور قیامت کی ہولناکیوں سے بچائے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب قیامت قائم ہو گی اس وقت دو افراد کسی کپڑے کا سودا کر رہے ہوں گے، نہ تو وہ سودا مکمل کر سکیں گے اور نہ ہی اسے لپیٹ سکیں گے۔‘‘"}],[1211,"ابو ہریرہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنت میں ایک درخت ہے جس کے سائے میں سو سال تک سوار چلتا رہے تو سایہ طے نہیں کر سکے گا، ہم چاہو تو پڑھو: اور سائے طویل، اور فرمایا: صبح کی نماز میں رات کے فرشتے اور دن کے فرشتے حاضر ہوتے ہیں، پڑھو اگر چاہو: اور صبح کے وقت قرآن پڑھنا، تحقیق فجر کی تلاوت قرآن حاضر کی گئی ہے۔ (1)","",{"k":"(1) صحیح، مسند ابی یعلی: 5853۔ العلل للدارقطنی: 305/7۔ وتقدم برقم: 1131۔","f":"اس حدیث سے ثابت ہوا کہ جنت میں لمبے لمبے درخت ہوں گے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جنت میں ایک درخت ہے، جس کے سائے میں کوئی سوار ایک سو سال تک چلتا رہے، تو پھر بھی وہ اسے پار نہیں کر سکتا اگر تم چاہو تو یہ آیت تلاوت کر سکتے ہو۔ ’’اور پھیلے ہوئے سائے۔‘‘ اور فجر کی نماز میں رات کے فرشتے اور دن کے فرشتے شریک ہوتے ہیں اگر تم چاہو تو یہ آیت تلاوت کر سکتے ہو۔ ’’اور فجر کی تلاوت، بے شک فجر کی تلاوت میں حاضری ہوتی ہے۔‘‘‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1212,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب عشاء کا کھانا اور نماز عشاء کی اقامت ہو تو کھانا پہلے کھالو۔ سفیان کہتے ہیں: ”جب کھانا آجائے“ یہ الفاظ صرف زہری نے نقل کیے ہیں۔ (1)","",{"k":"(1) صحیح البخاری (6721)، صحیح مسلم (557)، سنن الترمذی (353)، سنن النسائی (852)، سنن ابن ماجہ (933)، مسند احمد (110/3)، صحیح ابن خزیمة (934)، سنن الدارمی (1285)، مسند ابی یعلی (3546)، سنن الکبری للبیہقی (72/3)، صحیح ابن حبان (2066)۔","f":"جب انسان کو بھوک ہو اور کھانا بھی سامنے ہو تو کھانا کھانا چاہیے، خواہ نماز کی جماعت نکل جائے، اگر انسان کو بھوک ہے اور کھانا بھی موجود ہے تو اس وقت نماز پڑھنا درست نہیں ہے، اس سے انسان کی توجہ کھانے کی طرف رہے گی، یاد رہے کہ امام اس سے مستثنیٰ ہے، یعنی اگر امام کو بھوک لگی ہو اور کھانا اس کے پاس موجود ہے، اور جماعت کا ٹائم ہو گیا ہے تو وہ کھانا چھوڑ کر جماعت کرائے گا۔ (صحیح البخاری: 675) نیز اگر انسان کو بھوک نہیں ہے اور کھانا آگیا ہے، اُدھر سے جماعت کا وقت ہو گیا ہے، تو پہلے اُسے جماعت کے ساتھ نماز پڑھنی چاہیے، بعض مدارس میں نماز پر اتنی سختی کی جاتی ہے کہ جو بچہ تکبیر اولیٰ سے رہ جائے، اس کا عذر سنے بغیر اس کو سخت سزا دی جاتی ہے، خواہ وہ کسی شرعی عذر کی وجہ سے لیٹ ہوا ہو، یہ رویہ درست نہیں ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جب کھانا آ جائے اور نماز کے لیے اقامت کہی جا چکی ہو تو تم پہلے کھانا کھا لو۔‘‘ سفیان کہتے ہیں: میں نے کسی بھی راوی کو یہ الفاظ استعمال کرتے ہوئے نہیں سنا۔ ’’جب کھانا آ جائے‘‘ یہ الفاظ صرف زہری نے نقل کیے ہیں۔\nتخریج: متفق عليه"}],[1213,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب مدینہ منورہ تشریف لائے تو میں دس سال کی عمر کا تھا اور جب آپ فوت ہوئے تو میں بیس سال کا تھا اور میری مائیں مجھے آپ کی خدمت کی ترغیب دیتی تھیں، آپ ہمارے گھر تشریف لائے تو ہم نے گھر پر رہنے والی بکری کا دودھ نکالا اور گھر کے کنویں کے پانی سے ٹھنڈا کیا، رسول اللہ صلی اللہ علیہ وسلم نے پیا اور آپ کے بائیں طرف ابو بکر صدیق تھے اور ایک اعرابی دائیں طرف تھا اور عمر ایک طرف کو تھے، تو عمر نے کہا: یا رسول اللہ! ابو بکر کو پکڑائیں، رسول اللہ صلی اللہ علیہ وسلم نے اعرابی کو دے دیا اور فرمایا: دائیں طرف والا، پھر دائیں طرف والا حق دار ہے۔ (1)","",{"k":"(1) صحیح البخاری (5619)، صحیح مسلم (2029)، سنن ابی داود (3726)، سنن الترمذی (1893)، سنن الکبری للنسائی (6861)، مسند احمد (110/3)، سنن الدارمی (2126)، مؤطا امام مالک (ص 568)، طبقات ابن سعد (20/7)، مسند الطیالسی (2094)، مسند ابی یعلی (3561)، صحیح ابن حبان (5336)۔","f":"اس حدیث سے ثابت ہوا کہ دائیں طرف والے کو بائیں طرف والے پر ترجیح دینی چاہیے، جب انسان بیٹھے تو ہر جگہ دائیں طرف بیٹھنے کی کوشش کرنی چاہیے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: جب نبی اکرم صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے میں اس وقت دس سال کا لڑکا تھا، جب نبی اکرم صلی اللہ علیہ وسلم کا وصال ہوا اس وقت میں ۲۰ سال کا لڑکا تھا میری امی اور خالہ کہیں مجھے نبی اکرم صلی اللہ علیہ وسلم کی خدمت کی ترغیب دیا کرتی تھیں پھر ایک مرتبہ آپ صلی اللہ علیہ وسلم ہمارے ہاں گھر تشریف لائے ہم نے آپ صلی اللہ علیہ وسلم کے لیے اپنی پالتو بکری کا دودھ دودھ لیا اور اس میں گھر میں موجود کنویں کا پانی ملا دیا تو نبی اکرم صلی اللہ علیہ وسلم نے اسے پی لیا۔ آپ صلی اللہ علیہ وسلم کے بائیں طرف سیدنا ابو بکر رضی اللہ عنہ موجود تھے اور آپ صلی اللہ علیہ وسلم کے دائیں طرف ایک دیہاتی تھا، جبکہ سیدنا عمر رضی اللہ عنہ ایک کونے میں تھے۔ سیدنا عمر رضی اللہ عنہ نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! (دے ہاتی سے پہلے) آپ سیدنا ابو بکر رضی اللہ عنہ کو (اپنا بچا ہوا دودھ دیں) تو نبی اکرم صلی اللہ علیہ وسلم نے وہ دیہاتی کو دیتے ہوئے ارشاد فرمایا: پہلے دائیں طرف والوں کا حق ہوتا ہے۔\nتخریج: متفق عليه"}],[1214,"انس بن مالک نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قطع تعلقی نہ کرو، غیبت نہ کرو، بغض نہ رکھو اور باہم حسد نہ رکھو اور اللہ کے بندو آپس میں بھائی بھائی بن جاؤ، اور کسی مسلمان کے لیے جائز نہیں ہے کہ وہ اپنے بھائی کو تین دن سے زیادہ چھوڑے، سفیان سے پوچھا گیا: کیا اس حدیث میں کلمہ ”تناجشوا“ بھی ہے؟ تو انھوں نے کہا: نہیں۔ (1)","",{"k":"(1) صحیح البخاری (6076)، صحیح مسلم (2559)، سنن ابی داود (4910)، سنن الترمذی (1935)، الادب المفرد للبخاری (398)، مسند احمد (110/3)، مؤطا امام مالک (ص 558)، مسند الطیالسی (2091)، مسند ابی یعلی (3549)، سنن الکبری للبیہقی (303/7)۔","f":"اس حدیث میں بعض چیزوں سے منع کیا گیا ہے، اور ان کا تعلق حقوق العباد سے ہے، حسد کی تعریف یہ ہے کہ کسی کی نعمت دیکھ کر یہ کہنا یا سوچنا کہ اس سے نعمت چھن جائے، اور مجھے مل جائے، اور یہ حرام ہے، اور جس روایت میں آتا ہے کہ حسد نیکیوں کو کھا جاتا ہے، وہ روایت سخت ضعیف ہے۔ (سنن ابن ماجہ: 4210۔ اس کی سند میں عیسیٰ بن ابی عیسیٰ متروک ہے۔ نیز دیکھیے الضعیفہ: 1901) نیز اس حدیث میں تین دن سے زیادہ کسی کو نہ بلانے کی مذمت بیان کی گئی ہے، یہاں پر ایک اہم نکتہ یاد رہے کہ اس سے مراد یہ ہے کہ جو دو لوگ آپس میں لڑ پڑیں، ان کی آپس میں ملاقات ہو جائے اور وہ ایک دوسرے کو نہ بلائیں، اس کا مطلب ہرگز نہیں ہے کہ جو دو لوگ آپس میں لڑ پڑیں اور ان کی ملاقات ہی نہ ہوئی ہو، یہ مراد نہیں ہے، اس طرح خواہ دس دن گزر جائیں نیز یہ بھی یاد رہے کہ اللہ کی رضا کی خاطر کسی سے ناراض ہو جانا اور وہ ناراضگی پوری زندگی رکھ لینا جب تک دوسرا دین کی طرف نہ آئے یہ درست ہے، کیونکہ یہ ناراضگی اللہ کے لیے ہے، اور دوسرے انسان کی بھلائی کی خاطر ہے، بلکہ یہ ناراضگی باعث اجر ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’آپس میں قطع رحمی نہ کرو آپس میں ایک دوسرے سے پیٹھ نہ پھیرو ایک دوسرے سے بغض نہ رکھو ایک دوسرے سے حسد نہ کرو اللہ کے بندے اور بھائی بھائی بن کر رہو، کسی مسلمان کے لیے یہ بات جائز نہیں ہے، وہ اپنے بھائی سے تین دن سے زیادہ لا تعلق رہے۔‘‘ سفیان نامی راوی سے دریافت کیا گیا: اس روایت میں یہ الفاظ بھی ہیں ’’آپس میں مصنوعی بولی نہ لگاؤ‘‘ تو انہوں نے جواب دیا: جی نہیں۔\nتخریج: ايضا"}],[1215,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ام المومنین صفیہ رضی اللہ عنہا سے نکاح کے وقت ستو اور کھجور ہی دعوت ولیمہ میں کھلائے تھے۔ سفیان کہتے ہیں: میں نے زہری کو یہ حدیث بیان کرتے ہوئے سنا لیکن میں اس کو یاد نہ رکھ سکا، بکر بن وائل بھی ہمارے ساتھ زہری کی مجلس میں بیٹھے ہوئے تھے۔ (1)","",{"k":"(1) صحیح: سنن ابی داود (3744)، سنن الترمذی (1081)، شمائل ترمذی (177)، سنن ابن ماجہ (1909)، سنن الکبری للنسائی (6566)، مسند احمد (110/3)، مسند ابی یعلی (3580)، صحیح ابن حبان (4061)، سنن الکبری للبیہقی (260/7)۔","f":"دیگر احادیث سے معلوم ہوتا ہے کہ ولیمہ کرنا فرض ہے، اور ولیمہ رخصتی کے بعد ہوتا ہے، نہ کہ پہلے، بعض بے علم حضرات نے یہ شوشہ چھوڑا ہوا ہے کہ ولیمے کے لیے شرط ہے کہ بیوی سے صحبت کی جائے، اور پردہ بکارت پھٹے، یہ فضول بات ہے، اس کی قرآن و حدیث میں کوئی اصل نہیں ہے، کیونکہ رخصتی کے وقت عورت حیض کی حالت میں بھی ہو سکتی ہے، اور سب کو معلوم ہے کہ حالت حیض میں صحبت کرنا حرام ہے، اس سے یہ بھی ثابت ہوا کہ ولیمے میں سادہ سی چیزیں بھی پکانا درست ہیں، مثلاً آلو روٹی، پالک کا سالن، اور روٹی وغیرہ۔ افسوس کہ لوگوں نے شادیوں کو مہنگا اور زنا کو سستا کر دیا ہے، ہمیں شادی کو سستا کر دینا چاہیے تاکہ زنا ختم ہو جائے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے سیدہ صفیہ رضی اللہ عنہا کے ولیمے میں ستو اور کھجوروں کے ذریعے (مہمانوں کی تواضع کی تھی) سفیان کہتے ہیں: میں نے زہری کو یہ حدیث بیان کرتے ہوئے سنا: لیکن میں اس کو یاد نہیں رکھ سکا (میں نے بکر نامی جس راوی سے روایت نقل کی ہے) بکر بن وائل ہمارے ساتھ زہری کی محفل میں شریک ہوتے رہے ہیں۔\nتخریج: اخرجه ابن حبان في صحيحه"}],[1216,"انس بن مالک رضی اللہ عنہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کدو اور قلعی کیے ہوئے برتن میں نبیذ نہ تیار کیا کرو۔ (1)","",{"k":"(1) صحیح البخاری (5587)، صحیح مسلم (1992)، سنن النسائی (5632)، مسند احمد (110/3)، سنن الدارمی (2116)، مسند الشافعی (94/2)، صحیح ابی عوانة (310/5)، سنن الکبری للبیہقی (109/8)۔","f":"یہ حدیث منسوخ ہے، اس کی ناسخ حدیث صحیح مسلم میں ہے، اب جس مرضی برتن میں نبیذ بنائی جا سکتی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’دباء (کدو) اور مزفت میں نبیذ تیار نہ کرو۔‘‘\nتخریج: متفق عليه"}],[1217,"میت کے ساتھ قبر تک تین اشیاء جاتی ہیں: اس کا اہل اس کا مال اور اس کا عمل۔ دو تو واپس چلے جاتے ہیں اور ایک اس کے ساتھ رہتا ہے، مال اور اہل واپس چلے جاتے ہیں اور عمل ساتھ رہتا ہے۔ (1)","",{"k":"(1) صحیح البخاری (6514)، صحیح مسلم (2960)، سنن الترمذی (2379)، سنن النسائی (1939)، مسند احمد (110/3)، الزہد لابن المبارک (636)، صحیح ابن حبان (3107)، مستدرک للحاکم (74/1)، شعب الایمان (3339)۔","f":"اس حدیث میں میت کو فائدہ دینے والے اس کے اعمال کا ذکر ہے، میت کا اہل اور مال میت کے ساتھ نہیں رہتے، جن کی خاطر انسان دنیا میں دین سے غافل رہا، اللہ تعالیٰ ہمیں نیک اعمال کی توفیق دے، آمین۔ اے رب العالمین! کتابیں لکھنا ایک نیک عمل ہے، راقم دینی کتب لکھنے کو ایک عبادت سمجھتا ہے، یا رب العالمین! میرے قلم میں برکت عطا فرما، اور میرا سینہ کھول دے، آمین۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میت کے ساتھ تین چیزیں اس کی قبر تک جاتی ہیں اس کے اہل خانہ، اس کا مال اور اس کا عمل، دو واپس آ جاتے ہیں اور ایک ساتھ رہ جاتا ہے اس کے اہل خانہ اور اس کا مال واپس آ جاتے ہیں اور اس کا عمل باقی رہ جاتا ہے۔‘‘\nتخریج: ايضا"}],[1218,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم بنو نجار کے ویرانے میں رفع حاجت کرنے گئے، پس خوف زدہ واپس آئے یا کہا گھبرائے ہوئے لوٹے اور فرما رہے تھے: اگر تم مردوں کو دفنانا ترک نہ کر دیتے تو میں اللہ تعالیٰ سے سوال کرتا کہ اہل قبور کا عذاب جو مجھے سنایا ہے تمھیں بھی سنا دے۔ (1)","",{"k":"(1) مسند احمد (111/3)، مسند ابی یعلی (3693)، اثبات عذاب القبر للبیہقی (93)، من طریق سفیان بھذا الاسناد، صحیح مسلم (2868)، سنن النسائی (2060)، مسند احمد (103/3، 176)، مسند عبد بن حمید (176/3)، صحیح ابن حبان (3126)، شرح السنة للبغوی (1526)، من طریق اخری عن ابی ہریرة۔","f":"اس حدیث سے ثابت ہوا کہ عذاب قبر برحق ہے، ایک دوسری حدیث میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”نَعَمْ، عَذَابُ الْقَبْرِ حَقٌّ“ ہاں، عذاب قبر حق ہے۔ (صحیح البخاری: 1306) عذاب قبر قرآن و حدیث کی بے شمار نصوص سے ثابت ہے، بعض لوگوں کا اس سے انکار کرنا واضح گمراہی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم بنو نجار کے کسی کھنڈر میں قضائے حاجت کے لیے تشریف لے گئے، تو آپ صلی اللہ علیہ وسلم گھبرائے ہوئے واپس تشریف لائے آپ صلی اللہ علیہ وسلم یہ فرما رہے تھے۔ ’’اگر اس بات کا اندیشہ نہ ہوتا کہ تم لوگ (مردوں کو) دفن کرنا ہی چھوڑ دو گے، تو میں اللہ تعالیٰ سے یہ دعا کرتا کہ قبروں کے عذاب سے متعلق وہ چیز تمہیں سنائے، جو اس نے مجھے سنائی ہے۔‘‘\nتخریج: اخرجه مسلم في صفة الجنة"}],[1219,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے آخری نگاہ رسول اللہ صلی اللہ علیہ وسلم کو اس وقت دیکھا جب سوموار کے دن آپ نے پردہ اٹھا کر لوگوں کو ابو بکر کے پیچھے صف بستہ نماز پڑھتے دیکھا تھا، جب لوگوں نے آپ کو دیکھا تو مجمع حرکت میں آگیا، رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ سے (اشارہ کیا کہ ثابت قدم رہو، اس وقت میں نے آپ کے چہرہ اقدس کو دیکھا گویا مصحف کا ورق ہے، پھر آپ نے پردہ لٹکا دیا اور اسی دن بعد میں وفات پائی۔ (1)","",{"k":"(1) صحیح البخاری (680)، صحیح مسلم (419)، سنن النسائی (1832)، سنن ابن ماجہ (1624)، شمائل ترمذی (385)، مسند احمد (110/3)، صحیح ابن خزیمة (1650)، مسند ابی یعلی (3548)، صحیح ابی عوانة (118/2)، صحیح ابن حبان (6620)۔","f":"اس حدیث میں سیدنا ابو بکر رضی اللہ عنہ کی زبردست فضیلت ثابت ہوتی ہے، اور یہ بھی ثابت ہوتا ہے کہ خلیفہ اول بلا فصل نبی کریم صلی اللہ علیہ وسلم سیدنا ابو بکر رضی اللہ عنہ کو بنانا چاہتے تھے، اس لیے بذات خود آپ صلی اللہ علیہ وسلم نے اپنی زندگی میں ہی اپنے مصلے پر نماز پڑھانے کا حکم دیا۔ نیز اس پر مسند ابی بکر میں مفصل بحث گزر چکی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم کی آخری زیارت میں نے اس وقت کی تھی جب آپ صلی اللہ علیہ وسلم نے پیر کے دن پردہ ہٹایا تھا لوگ سیدنا ابو بکر رضی اللہ عنہ کے پیچھے صفیں بنا کر نماز ادا کر رہے تھے ان لوگوں نے آپ صلی اللہ علیہ وسلم کو دیکھا تو وہ حرکت کرنے لگے، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ تم لوگ اپنی جگہ پر رہو۔ میں نے نبی اکرم صلی اللہ علیہ وسلم کے چہرہ مبارک کی طرف دیکھا، تو وہ یوں تھا جیسے وہ قرآن مجید کا کوئی ورق ہوتا ہے پھر آپ صلی اللہ علیہ وسلم نے پردہ گرا دیا اور اسی دن کے آخری حصے میں آپ صلی اللہ علیہ وسلم کا وصال ہو گیا۔\nتخریج: متفق عليه"}],[1220,"انس بن مالک رضی اللہ عنہ نے فرمایا: نبی کریم صلی اللہ علیہ وسلم گھوڑے سے گرے اور آپ صلی اللہ علیہ وسلم کے دائیں پہلو پر خراش آگئی، ہم نے حاضر خدمت ہو کر بیمار پرسی کی، (اسی دوران) نماز کا وقت ہو گیا، تو آپ صلی اللہ علیہ وسلم نے بیٹھ کر نماز پڑھائی، اور ہم لوگوں نے بھی بیٹھ کر نماز پڑھی، جب آپ صلی اللہ علیہ وسلم نے نماز مکمل کی تو فرمایا: امام اس لیے بنایا جاتا ہے کہ اس کی پیروی کی جائے، جب وہ تکبیر کہے تو تم بھی تکبیر کہو، جب وہ رکوع کرے تو تم بھی رکوع کرو، جب وہ سر اٹھائے تو تم بھی سر اٹھاؤ، اور جب وہ کہے: سمع اللہ لمن حمدہ تو تم کہو: ربنا ولک الحمد اور جب سجدہ کرے تو تم بھی سجدہ کرو اور جب وہ بیٹھ کر نماز پڑھے تو تم سب بھی بیٹھ کر نماز پڑھا کرو۔ (1)","",{"k":"(1) صحیح البخاری (805)، صحیح مسلم (411)، سنن ابی داود (601)، سنن النسائی (795)، سنن ابن ماجہ (1238)، مسند احمد (110/3)، مؤطا امام مالک (ص 105)، سنن الدارمی (1259)، صحیح ابن خزیمة (977)، صحیح ابن حبان (2103)، مسند ابی یعلی (3558)، مسند الطیالسی (2090)۔","f":"اس حدیث سے ثابت ہوا کہ آپ صلی اللہ علیہ وسلم انسان تھے، آپ صلی اللہ علیہ وسلم کو زندگی میں چوٹیں بھی آئیں، نیز یہ بھی ثابت ہوا کہ آپ صلی اللہ علیہ وسلم مشکل کشا نہیں تھے۔ پہلے یہ حکم تھا کہ جب امام بیٹھ کر نماز پڑھائے تو مقتدی کو بھی بیٹھ کر پڑھنی چاہیے، اور امام کی اقتدا میں ہی پوری نماز مکمل کرنی چاہیے۔ البتہ یہ حکم آپ صلی اللہ علیہ وسلم کے آخری عمل سے منسوخ ہو چکا ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم گھوڑے سے گر گئے آپ صلی اللہ علیہ وسلم کا دایاں پہلو زخمی ہوا ہم آپ صلی اللہ علیہ وسلم کی عیادت کے لیے آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے نماز کا وقت ہو گیا تو نبی اکرم صلی اللہ علیہ وسلم نے بیٹھ کر ہمیں نماز پڑھائی۔ ہم نے بھی آپ صلی اللہ علیہ وسلم کے پیچھے بیٹھ کر نماز ادا کی۔ نبی اکرم صلی اللہ علیہ وسلم نے نماز مکمل کر لی تو آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’بے شک امام کو اس لیے مقرر کیا گیا ہے، تاکہ اس کی پیروی کی جائے، جب وہ تکبیر کہے، تو تم بھی تکبیر کہو جب وہ رکوع میں جائے، تو تم بھی رکوع میں جاؤ جب وہ (رکوع سے) اٹھے، تو تم بھی اٹھ جاؤ جب وہ سمع اللہ لمن حمدہ پڑھے، تو تم ربنا لک والحمد پڑھو وہ سجدے میں جائے، تو تم بھی سجدے میں جاؤ جب وہ بیٹھ کر نماز ادا کرے تو تم بھی بیٹھ کر نماز ادا کرو۔‘‘\nتخریج: متفق عليه"}],[1221,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ایک آدمی حاضر ہوا اور اس نے قیامت کے متعلق سوال کیا تو آپ نے فرمایا: تو نے اس کے لیے کیا تیاری کی ہے؟ تو اس نے کوئی زیادہ اعمال تو ذکر نہ کیے مگر اس نے کہا: میں اللہ اور اس کے رسول سے محبت کرتا ہوں، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: تو انھی کے ساتھ ہوگا جن سے تو محبت کرتا ہے۔ ابو علی کہتے ہیں: میں نے حمیدی سے سنا، انھوں نے کہا: ابن عیینہ نے چھیاسی (86) تابعین کی زیارت کی ہے، اور وہ کہتے تھے کہ میں نے ایوب جیسا کوئی شخص نہیں دیکھا، حمیدی کہتے ہیں: سفیان نے کہا: جب زہری ہمیں سیدنا انس یا سہل سے روایت بیان کرتے تو کہتے: میں نے سنا، میں نے سنا۔ (1)","",{"k":"(1) صحیح مسلم (2639)، مسند احمد (110/3)، الزہد لابن المبارک (1018)، مسند ابی یعلی (3556)، صحیح ابن حبان (563)، من طریق الزہری بہ، صحیح البخاری (3688)، الادب المفرد (352)، سنن الترمذی (2385)، من طریق آخر عن ابی ہریرة۔","f":"نبی کریم صلی اللہ علیہ وسلم سے سچی محبت قرآن و حدیث کی اطاعت میں ہی ہے، سچی محبت نبی صلی اللہ علیہ وسلم مومن ہوتا ہے، اور وہ جو قرآن و حدیث کے قریب نہ آئے اور زبانی دعویٰ کرے کہ میں محب نبی صلی اللہ علیہ وسلم ہوں، اس کا یہ دعویٰ بے کار ہے۔ نیز یہ بھی معلوم ہوا کہ لوگوں کو قیامت کی تیاری کا درس دیتے رہنا چاہیے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اس نے آپ صلی اللہ علیہ وسلم سے قیامت کے بارے میں دریافت کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے دریافت کیا: تم نے اس کے لیے کیا تیاری کی ہے؟ تو اس نے بہت زیادہ چیزوں کا تذکرہ نہیں کیا صرف اس نے یہ کہا: میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت رکھتا ہوں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم جس سے محبت رکھتے ہو اس کے ساتھ ہو گے۔ ابو علی نامی راوی کہتے ہیں: امام حمیدی رحمہ اللہ یہ فرماتے ہیں ابن عیینہ نے ۸۶ تابعین کی زیارت کی ہے، وہ یہ فرماتے ہیں: میں نے ایوب جیسا کوئی شخص نہیں دیکھا۔ امام حمیدی رحمہ اللہ کہتے ہیں: سفیان نامی راوی نے یہ بات بیان کی ہے، جب زہری ہمیں سیدنا انس رضی اللہ عنہ یا سہل کے حوالے سے روایات بیان کرتے تھے، تو یہ کہتے تھے: میں نے یہ روایت سنی ہے، میں نے یہ روایت سنی ہے۔\nتخریج: ايضا"}],[1222,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ مدینہ میں نماز ظہر چار رکعات اور آپ کے ساتھ نماز عصر ذوالحلیفہ میں دو رکعات پڑھی۔ (1)","",{"k":"(1) صحیح: مسند احمد (237/3)، سنن الدارمی (1515)، شرح معانی الآثار للطحاوی (418/1)، صحیح ابن حبان (2746)، مسند ابی یعلی (3634)، من طریق ابن المنکدر عن انس، صحیح البخاری (1089)، صحیح مسلم (690)، سنن ابی داود (1202)، سنن الترمذی (546)، سنن النسائی (470)، مسند احمد (110/3)، مصنف عبدالرزاق (4317)، مسند ابی یعلی (3633)، من طریق سفیان عن محمد بن المنکدر وابراہیم بن میسرة عن ابی ہریرة۔","f":"سفر شروع کرنے سے ہی نماز قصر ہو جاتی ہے، خواہ آدمی شہر سے یا محلے سے باہر ہی نکلا ہو، کیونکہ ذوالحلیفہ مدینہ سے 6 میل دور ہے۔ (اکمال المعلم: 9/3) رہا یہ مسئلہ کہ قصر نماز کتنی مسافت سفر کرنے سے شروع ہوتی ہے، اس میں راجح بات یہ ہے کہ عرف جس کو سفر کہتا ہے، وہ سفر ہے، ”مَا يُطْلَقُ عَلَيْهِ اسْمُ السَّفَرِ فَهُوَ السَّفَرُ“ جس سفر کے نام کا اطلاق کیا جاتا ہو، پس وہ سفر ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے مدینہ منورہ میں نبی اکرم صلی اللہ علیہ وسلم کی اقتداء میں ظہر کی نماز میں ۴ رکعات ادا کیں اور میں نے آپ صلی اللہ علیہ وسلم کی اقتداء میں ’’ذوالحلیفہ‘‘ میں عصر کی نماز میں دو رکعات ادا کیں۔\nتخریج: ايضا"}],[1223,"ہم سے بیان کیا حمیدی نے، انھوں نے کہا: ہم سے بیان کیا سفیان نے، انھوں نے کہا: بیان کیا ہم سے ایوب سختیانی نے، وہ ابی قلابہ سے، وہ انس بن مالک سے، وہ نبی کریم صلی اللہ علیہ وسلم سے مثل اس کے روایت کرتے ہیں۔ (1)","",{"k":"(1) صحیح البخاری (1714)، صحیح مسلم (690)، سنن النسائی (478)، مسند احمد (111/3)، مسند ابی یعلی (2794)، صحیح ابن حبان (2743)۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: یہ روایت ایک اور سند کے ہمراہ بھی منقول ہے۔\nتخریج: ايضا"}],[1224,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں نماز ظہر چار رکعات پڑھی اور آپ کے ساتھ ذوالحلیفہ میں نماز عصر دو رکعات پڑھی۔ (1)","",{"k":"(1) صحیح، انظر الحدیث المتقدم: 1222۔ مصنف ابن ابی شیبة: 443/2۔ مسند ابی یعلی: 3665۔ من طریق ابراہیم بہذا الاسناد۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے مدینہ منورہ میں نبی اکرم صلی اللہ علیہ وسلم کی اقتداء میں ظہر کی نماز میں ۴ رکعات ادا کیں اور ذوالحلیفہ میں عصر کی نماز میں دو رکعات ادا کیں۔\nتخریج: ايضا"}],[1225,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے اور ایک یتیم نے ہمارے گھر میں نبی کریم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی اور میری ماں ام سلیم ہمارے پیچھے کھڑی ہوئیں۔ (1)","",{"k":"(1) صحیح البخاری (727)، سنن النسائی (870)، مسند احمد (110/3)، صحیح ابن خزیمة (1539)، مسند الشافعی (106/1)، صحیح ابی عوانة (75/2)، سنن الکبری للبیہقی (106/3)، شرح السنة (829)۔","f":"اس حدیث سے ثابت ہوا کہ گھر میں نفل نماز کی جماعت کروانا درست ہے، اور بچہ امام کے پیچھے پہلی صف میں کھڑا ہو سکتا ہے، جب پہلی صف نامکمل ہو، اور عورت صف میں اکیلی بھی کھڑی ہو سکتی ہے، یہ بات یاد رہے کہ اگر بچہ شوق سے جلدی مسجد میں آ جاتا ہے اور پہلی صف میں امام کے پیچھے کے علاوہ کسی اور جگہ پر کھڑا ہو جائے تو اُس کو پہلی صف سے اٹھا کر پچھلی صفوں میں کر دینا درست نہیں ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں اور یتیم لڑکا ہمارے گھر میں نبی اکرم صلی اللہ علیہ وسلم کے پیچھے کھڑے ہوئے، جبکہ میری والدہ سیدہ ام سلیم رضی اللہ عنہا ہمارے پیچھے کھڑی ہوئیں۔\nتخریج: ايضا"}],[1226,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے انصار کو بلایا تاکہ ان کو بحرین کا علاقہ عطا کر دیں، تو انصار نے کہا: ہمارے مہاجرین بھائیوں کو بھی اس کی مثل عطا فرما دیں تو ہم تب ہی لیں گے، پس نبی کریم صلی اللہ علیہ وسلم نے فرمایا: تم میرے بعد اپنے اوپر ترجیح دیکھو گے تو صبر کرنا، یہاں تک کہ مجھ سے ملاقات کرو۔ (1)","",{"k":"(1) صحیح البخاری (3794)، مسند احمد (111/3)، مسند ابی یعلی (3649)، صحیح ابن حبان (7276)، سنن الکبری للبیہقی (143/6، 144)، شرح السنة للبغوی (2192)۔","f":"اس حدیث میں ﴿وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾ (اور وہ اپنے آپ پر ترجیح دیتے ہیں، خواہ انھیں سخت حاجت بھی ہو) (الحشر: 9) کی عملی تفسیر ہے، سبحان اللہ۔ نیز اس حدیث مبارکہ میں یہ بھی ہے کہ حق والے پر دوسرے کو ترجیح دینا غلط ہے، تاریخ بھری پڑی ہے کہ لوگ کس قدر ناانصافیوں سے کام لیتے ہیں، موجودہ دور بھی فتنوں سے لبریز ہے، اور ہر کوئی نااہل کو اہل پر ترجیح دیتا ہے (الا من رحم ربی) کیونکہ قرآن وحدیث کے مطابق فیصلے نہیں کیے جاتے، بلکہ اپنے مفاد کو پیش نظر رکھا جاتا ہے۔ ایسی ہر صورت حال میں صبر کا دامن نہیں چھوڑنا چاہیے، بس اللہ تعالیٰ امت مسلمہ کی اصلاح فرمائے، آمین۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے کچھ انصاریوں کو بلایا، تاکہ انہیں بحرین میں کچھ قطعہ اراضی عطا کریں، تو انہوں نے عرض کی: ہم یہ اس وقت تک نہیں لیں گے، جب تک ہمارے مہاجر بھائیوں کو بھی اس کی مانند قطعہ اراضی عطا نہیں کریں گے، تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: میرے بعد تم لوگ ترجیحی سلوک دیکھو گے، تو تم صبر سے کام لینا یہاں تک تم مجھ سے آملو۔\nتخریج: اخرجه البخاري في المساقاة"}],[1227,"انس بن مالک رضی اللہ عنہ نے فرمایا: ایک دیہاتی نے مسجد میں پیشاب کیا تو لوگوں نے اس کو گھور کر دیکھنا شروع کر دیا، پس نبی کریم صلی اللہ علیہ وسلم نے ان کو منع کیا اور فرمایا: اور اس پر ایک ڈول پانی بہا دو۔ (1)","",{"k":"(1) صحیح البخاری (219)، صحیح مسلم (284)، سنن الترمذی (148)، سنن النسائی (54)، مسند احمد (110/3)، مسند الشافعی (25/1)، صحیح ابی عوانة (214/1)، سنن الدارمی (746)، مصنف عبدالرزاق (1660)، مصنف ابن ابی شیبة (193/1)۔","f":"اس حدیث سے معلوم ہوا کہ اگر کوئی کم علم انسان غیر مناسب جگہ پر پیشاب کرنے لگے تو اس کو فوراً وہاں سے اٹھانا درست نہیں ہے، بلکہ اس کو پیشاب کرنے دیا جائے، جب وہ فارغ ہو جائے تو اس کو شفقت سے سمجھا دینا چاہیے، اور جس جگہ پیشاب کیا تھا اس پر ایک ڈول پانی بہا دینا چاہیے، اس سے وہ جگہ پاک ہو جاتی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: ایک دیہاتی نے مسجد میں پیشاب کر دیا۔ لوگ اس کی طرف (گھور کر) دیکھنے لگے، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں روکا اور ارشاد فرمایا: اس پر پانی کا ایک ڈول بہا دو۔\nتخریج: متفق عليه"}],[1228,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: انصار میں سے بہترین خاندان بنو نجار ہیں، پھر بنو عبد الاشہل، پھر بنو حارث بن خزرج ہیں، پھر بنو ساعدہ ہیں اور فرمایا: انصار کے ہر خاندان میں نیکی اور بھلائی ہے۔ (1)","",{"k":"(1) صحیح البخاری (5300)، صحیح مسلم (2511)، سنن الترمذی (3910)، سنن الکبری للنسائی (8336)، مسند احمد (56/1، 202/3)، مسند عبد بن حمید (1400)، حلیة الاولیاء (354/6)۔","f":"اس حدیث سے ثابت ہوا کہ جس خاندان کی مجموعی صفت اچھی ہو اس کو بیان کرنے میں کوئی حرج نہیں ہے، نیز اس میں انصار کے تمام لوگوں کی عمومی فضیلت ثابت ہوتی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’انصار کے خاندانوں میں سب سے بہتر بنو نجار کا خاندان ہے، پھر بنو عبد الاشہل کا خاندان، پھر بنو حارث بن خزرج کا خاندان ہے، پھر بنو ساعدہ کا خاندان ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ویسے انصار کا ہر خاندان بہتر ہے۔‘‘\nتخریج: ايضا"}],[1229,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جمعرات کی صبح خیبر میں پہنچے جبکہ اہل خیبر نے قلعہ کے دروازے سے کھیتی کے ہتھیار لے کر نکلنا شروع کیا تھا، جب انھوں نے آپ کو دیکھا تو لوٹ کر قلعہ میں داخل ہو گئے اور انھوں نے کہا: محمد صلی اللہ علیہ وسلم فوج سمیت آ چکے ہیں، پس رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ اٹھا کر کہا: اللہ اکبر، اللہ اکبر، خیبر والے خراب ہوئے، ہم جب کسی قوم کے ڈالان میں اترتے ہیں تو ڈرائے گئے لوگوں کی صبح بری ہوتی ہے۔ (1)","",{"k":"(1) صحیح البخاری (2991)، سنن النسائی (4345)، مسند احمد (111/3)، تفسیر عبدالرزاق (159/2)، من طریق ایوب بہذا الاسناد، صحیح مسلم (1365/87)، سنن الترمذی (1550)، مؤطا امام مالک (ص 398)، من طریق اخری عن انس بن مالک رضی اللہ عنہ۔","f":"اس حدیث میں خیبر کی فتح کا ذکر ہے، اس حدیث سے یہ بھی ثابت ہوا کہ کفار بزدل ہوتے ہیں، مسلمانوں کے پاس سب سے قیمتی دولت ایمان ہوتی ہے، بزدلی ایمان کا مقابلہ کیسے کر سکتی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم جمعرات کی صبح ’’خیبر‘‘ پہنچے، جب نبی اکرم صلی اللہ علیہ وسلم وہاں پہنچے اس وقت وہاں کے لوگوں نے قلعے کا دروازہ کھول دیا تھا اور اپنے بیلچے وغیرہ لے کر اس میں سے باہر نکل رہے تھے، جب ان لوگوں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا تو دوڑتے ہوئے اپنے قلعے کی طرف واپس گئے اور بولے: محمد صلی اللہ علیہ وسلم اور ان کا لشکر آ گئے ہیں، محمد صلی اللہ علیہ وسلم اور ان کا لشکر آ گئے ہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اللہ اکبر! اللہ اکبر! آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ بلند کیے اور فرمایا: خیبر برباد ہو گیا، جب ہم کسی قوم کے میدان جنگ میں اترتے ہیں، تو ان لوگوں کی صبح بہت بری ہوتی ہے جنہیں ڈرایا گیا۔\nتخریج: ايضا"}],[1230,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم، ابوبکر، عمر اور عثمان الحمد للہ رب العالمین سے قراءت شروع کرتے تھے۔ (1)","",{"k":"(1) صحیح البخاری (743)، صحیح مسلم (399)، جزء القراءة خلف الامام للبخاری (127)، سنن ابی داود (782)، سنن الترمذی (246)، سنن النسائی (903)، سنن ابن ماجہ (813)، مسند احمد (111/3)، سنن الدارمی (1243)، صحیح ابن خزیمة (492)، مسند الشافعی (78/1)، سنن الکبری للبیہقی (51/2)۔","f":"اس حدیث سے ثابت ہوا کہ نماز کی جہری قراءت الحمد للہ سے شروع کرنی چاہیے۔ یاد رہے کہ جہری قراءت بسم اللہ سے شروع کرنا بھی درست ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم، سیدنا ابو بکر رضی اللہ عنہ، سیدنا عمر رضی اللہ عنہ اور سیدنا عثمان رضی اللہ عنہ (بلند آواز میں) قرآت کا آغاز سورہ فاتحہ کے ذریعے کرتے تھے۔\nتخریج: ايضا"}],[1231,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے جب خیبر فتح کیا تو بستی سے باہر ہمیں گدھے ملے اور ہم نے وہ ذبح کر کے گوشت پکانا شروع کر دیا اور اتنے میں رسول اللہ صلی اللہ علیہ وسلم کے منادی کرنے والے نے منادی کر دی: خبردار! اللہ اور اس کا رسول (صلی اللہ علیہ وسلم) گدھا کھانے سے تمھیں منع کرتے ہیں، یہ ناپاک شیطانی اعمال میں سے ہے، پس ہنڈیاں الٹی ہوئی گوشت سمیت الٹا دی گئیں۔ (1)","",{"k":"(1) صحیح البخاری (4198)، صحیح مسلم (1940)، سنن النسائی (69)، سنن ابن ماجہ (3196)، مسند احمد (164/3)، مصنف عبدالرزاق (8719)، صحیح ابن حبان (5274)، سنن الکبری للبیہقی (331/9)۔","f":"اس حدیث میں گھریلو گدھے کی حرمت کا ذکر ہے، نیز صحابہ کرام رضوان اللہ علیہم اجمعین کس قدر قرآن وحدیث کی اتباع کرنے میں حریص تھے، کاش امت مسلمہ بھی اپنے اوپر قرآن وحدیث کی اطاعت کو صحابہ کرام رضوان اللہ علیہم اجمعین کی طرح واجب کر لے، اور اپنی زندگی کا اوڑھنا بچھونا قرآن وحدیث کی تعلیمات کو بنا لے، دونوں جہانوں کی کامیابی اسی میں ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: جب نبی اکرم صلی اللہ علیہ وسلم نے خیبر فتح کر لیا تو ہمیں بستی سے باہر کچھ گدھے ملے، ہم نے انہیں ذبح کر کے پکانا شروع کیا۔ نبی اکرم صلی اللہ علیہ وسلم کی طرف سے اعلان کرنے والے نے یہ اعلان کیا: خبردار! بے شک اللہ اور اس کا رسول صلی اللہ علیہ وسلم تمہیں ان سے منع کر رہے ہیں کیونکہ یہ ناپاک ہیں اور شیطان کے عمل سے تعلق رکھتے ہیں۔ (راوی کہتے ہیں) تو ہنڈیاؤں میں جو کچھ موجود تھا اس سب سمیت انہیں الٹ دیا گیا حالانکہ وہ ابل رہی تھیں۔\nتخریج: متفق عليه"}],[1232,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر تمام لوگ ایک وسیع وادی میں چل رہے ہوں اور انصار ایک گھاٹی میں چل رہے ہوں تو میں انصار کی گھاٹی میں چلوں گا، اگر ہجرت نہ ہوتی تو میں انصار میں سے ایک مرد ہوتا، انصار میری تھیلی بھی ہیں اور اندرونی لباس بھی ہیں، لوگو! تم ان میں سے احسان والے کا احسان سے بدلہ دو اور ان کی بدی کو معاف کر دو، ابن جدعان کی روایت میں مزید یہ ہے: مگر حدوں میں معافی نہیں ہے۔ (1)","",{"k":"(1) صحیح: علی بن زید بن جدعان ضعیف راوی ہے، تاہم حدیث صحیح ہے، مسند احمد (187/3، 205)، فضائل الصحابة للنسائی (223، 221)، سنن الکبریٰ (8328)، مسند ابی یعلی (3770)، صحیح ابن حبان (7266)، طبقات ابن سعد (252/2)، سنن سعید بن منصور (2900)، شرح السنة للبغوی من طریق حمید عن انس، صحیح البخاری (3778، 3779، 3799)، صحیح مسلم (2510)، من طریق آخر عن انس مقطعاً۔","f":"اس حدیث میں انصار کی فضیلت کا بیان ہے، اور محسن کے احسان کو یاد رکھنا چاہیے، انصار صحابہ رضی اللہ عنہم کی قربانیاں اسلام کی خاطر کس قدر زیادہ ہیں، اگر ان کا احاطہ کیا جائے تو ایک مستقل تاریخ مرتب ہو سکتی ہے، نیز اس حدیث میں صحابہ کرام رضی اللہ عنہم کو بُرا بھلا کہنے سے روکا گیا ہے، اور اُن کے ساتھ حسن سلوک کی تلقین کی گئی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’اگر لوگ ایک وادی میں چلیں اور انصار ایک کھائی میں چلیں، تو میں انصار کی کھائی میں چلوں گا اگر ہجرت نہ ہوتی، تو میں انصار کا ایک فرد ہوتا، انصار میرے دست و بازو ہیں تو ان میں سے جو شخص اچھا ہو اس کے ساتھ تم اچھائی کرو اور جو شخص برا ہو اس سے تم درگزر کرو۔‘‘ ابن جدعان نامی راوی نے یہ بات بیان کی ہے۔ حسن نامی راوی نے یہ الفاظ مزید نقل کیے ہیں۔ ’’البتہ حد کا حکم مختلف ہے‘‘ (وہ برے شخص پر جاری کی جائے گی)‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1233,"انس بن مالک رضی اللہ عنہ نے فرمایا: ابو طلحہ اپنا ترکش نبی کریم صلی اللہ علیہ وسلم کے آگے رکھ دیتے تھے اور اپنے گھٹنوں کے بل جھک جاتے تھے اور کہتے تھے: میرا چہرہ آپ کے چہرے کے لیے بچاؤ ہے اور میری جان آپ کی ذات گرامی پر فدا ہے، راوی نے کہا: نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ہماری فوج میں ابو طلحہ کا بولنا اور اس کی آواز ایک جماعت سے زیادہ بہتر ہے، انس نے کہا: مسلمانوں کا جھنڈا بعض جنگوں میں میں نے ابن مکتوم کے ہاتھ میں دیکھا ہے۔ (1)","",{"k":"(1) حسن: الادب المفرد للبخاری (802)، مسند احمد (111/3، 261)، مسند ابی یعلی (3993)، مستدرک للحاکم (352/3)، سنن سعید بن منصور (2898)، حلیة الاولیاء (309/7)۔","f":"اس حدیث میں سیدنا ابو طلحہ رضی اللہ عنہ کی جرأت و دلیری کا ذکر ہے کہ وہ کس طرح اپنی جان کی نبی کریم صلی اللہ علیہ وسلم کی خاطر پروا نہیں کرتے، یہ بھی معلوم ہوا کہ صحابہ کرام رضوان اللہ علیہم اجمعین کا ایک جھنڈا بھی تھا۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: سیدنا ابو طلحہ رضی اللہ عنہ نے اپنے ترکش کے تمام تیر نکال کر نبی اکرم صلی اللہ علیہ وسلم کے سامنے رکھے اور وہ اپنے گھٹنوں کے بل جھک گئے اور یہ کہنے لگے: میرا وجود آپ صلی اللہ علیہ وسلم کی حفاظت کے لیے ہے اور میری جان آپ صلی اللہ علیہ وسلم پر قربان ہو۔ راوی بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: لشکر میں ابو طلحہ کی آواز ایک جماعت سے زیادہ بہتر ہے۔ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں: میں نے سیدنا ابن ام مکتوم رضی اللہ عنہ کو دیکھا ہے ایک جنگ میں مسلمانوں کا جھنڈا ان کے پاس تھا۔\nتخریج: اخرجه ابو يعلي في مسند الموصلي"}],[1234,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ انھوں نے فرمایا: اکیدر دومہ نے رسول اللہ صلی اللہ علیہ وسلم کے لیے ایک چغا ارسال کیا، اس کی خوبصورتی پر لوگوں کو تعجب ہوا، پس نبی کریم صلی اللہ علیہ وسلم نے فرمایا: سعد بن معاذ کا رومال جنت میں اس سے زیادہ بہتر ہے۔ (1)","",{"k":"(1) صحیح: مسند احمد (111/3)، حلیة الاولیاء (309/7، 310)، من طریق سفیان بہذا الاسناد، معجم الکبیر للطبرانی (5347)، مسند الشامیین (1693)، من طریق الزہری عن انس، صحیح البخاری (2615)، صحیح مسلم (2469)، من طریق قتادة عن انس۔","f":"اس حدیث میں سیدنا سعد بن معاذ رضی اللہ عنہ کے جنتی رومال کا ذکر ہے، اس سے معلوم ہوا کہ بعض جنتیوں کو رومال بھی دیے جائیں گے، سبحان اللہ۔ ہدیہ قبول کر لینا چاہیے، خواہ دینے والا مسلمان ہو یا غیر مسلم۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: ’’دومہ‘‘ کے حکمران ’’اکیدر‘‘ نے نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں ایک جبہ تحفے کے طور پر بھیجا تو لوگوں کو وہ بہت پسند آیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جنت میں سیدنا سعد بن معاذ رضی اللہ عنہ کے رومال اس سے زیادہ بہتر ہیں۔\nتخریج: متفق عليه"}],[1235,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں شفاعت کا تذکرہ ہوا تو آپ نے فرمایا: میں جنت کے دروازے کا حلقہ پکڑ کر ہلاؤں گا۔ (1)","",{"k":"(1) صحیح: مسند ابی یعلی (3989)، سنن الترمذی (3148)، فی ضمن ابی سعید، سنن الدارمی (51)، من طریق سفیان بہذا الاسناد، صحیح مسلم (196)، بلفظ ”انا اول من یقرع باب الجنة“۔","f":"اس حدیث سے جنت کے دروازے کا حلقہ ثابت ہوتا ہے، اس حدیث سے نبی کریم صلی اللہ علیہ وسلم کا روز قیامت سفارش کرنا بھی ثابت ہوتا ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں، نبی اکرم صلی اللہ علیہ وسلم کے سامنے شفاعت کا تذکرہ کیا گیا تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: میں جنت کی کنڈی پکڑ کر اسے کھٹکھٹاؤں گا۔\nتخریج: اخرجه مسلم في الايمان"}],[1236,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمارے گھر میں مہاجرین اور انصار کے درمیان عہد مواخات کرا دیا، تو ان سے کہا گیا: کیا رسول اللہ صلی اللہ علیہ وسلم نے یہ نہیں فرمایا تھا: اسلام میں حلیف بنانا جائز نہیں ہے؟ تو انس نے پھر وہی فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمارے گھر میں مہاجرین و انصار کے درمیان عہد مواخات کرایا، سفیان نے کہا: علماء اس کی یہ تفسیر کرتے ہیں کہ عہد مواخات صرف بھائی بھائی بنانا تھا، حلیف یا حمایتی بنانا نہیں تھا۔ (1)","",{"k":"(1) صحیح البخاری (6083)، صحیح مسلم (2529)، سنن ابی داود (2926)، مسند احمد (111/3، 281)، الادب المفرد (569)، مسند ابی یعلی (4022)، صحیح ابن حبان (4520)، سنن الکبری للبیہقی (262/6)۔","f":"زمانہ جاہلیت میں کسی کو بھی حلیف بنا لیا جاتا تھا، ہماری شریعت نے اس سے منع فرما دیا ہے، کیونکہ جب کوئی کسی کا حلیف بن جاتا ہے تو وہ وراثت کا بھی حق دار بن جاتا ہے، جبکہ مواخاة میں ایسی چیز نہیں ہوتی، اس کے علاوہ حدیث میں وضاحت ہے کہ زمانہ جاہلیت کے حلف کا اسلام کی حالت میں بھی اعتبار کیا جائے گا، اگر کسی نے زمانہ جاہلیت میں کسی کو اپنی وراثت کا حق دار بنایا تھا، پھر وہ دونوں مسلمان ہو گئے، تو ان کے زمانہ جاہلیت کے حلف کا اعتبار کرتے ہوئے اس کو دی ہوئی وراثت اس کے پاس رہے گی۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے ہمارے گھر میں مہاجرین اور انصار کے درمیان بھائی چارہ قائم کیا تھا۔ سیدنا انس رضی اللہ عنہ سے دریافت کیا گیا: نبی اکرم صلی اللہ علیہ وسلم نے یہ بات ارشاد نہیں فرمائی ہے: ’’اسلام میں حلف کی کوئی حیثیت نہیں ہے۔‘‘ تو سیدنا انس رضی اللہ عنہ نے یہ روایت دوبارہ بیان کی اور بولے: نبی اکرم صلی اللہ علیہ وسلم نے ہمارے گھر میں مہاجرین اور انصار کے درمیان حلف (ایک دوسرے کا حلیف ہونا) قائم کیا تھا۔ سفیان کہتے ہیں: علماء نے اس کی وضاحت یہ کی ہے بھائی چارہ قائم کیا تھا۔\nتخریج: متفق عليه"}],[1237,"شعبہ بن توام کہتے ہیں: قیس بن عاصم نے رسول اللہ صلی اللہ علیہ وسلم سے حلف کے متعلق سوال کیا تو آپ نے فرمایا: اسلام میں حلف نہیں ہے مگر جو حلف جاہلیت میں تھا اس کی رعایت رکھو۔ (1)","",{"k":"(1) صحیح لغیرہ، مسند احمد: 61/5۔ مسند الطیالسی: 1084۔ الآحاد والمثانی: 1166۔ مسند البزار: الکشف: 1915۔ شرح مشکل الآثار للطحاوی: 1616۔ صحیح ابن حبان: 4396۔ معجم الکبیر للطبرانی: 337/18۔","u2":"شعبہ بن توام کہتے ہیں: قیس بن عاصم نے نبی اکرم صلی اللہ علیہ وسلم سے حلف کے بارے میں دریافت کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’اسلام میں حلف کی کوئی حیثیت نہیں تاہم تم زمانہ جاہلیت کے حلف کو مضبوطی سے پکڑ کر رکھو۔‘‘\nتخریج: اخرجه ابن حبان في صحيحه"}],[1238,"انس بن مالک رضی اللہ عنہ نے فرمایا: نبی کریم صلی اللہ علیہ وسلم کو کسی غزوہ یا سریہ پر اتنا غم نہیں لگا جتنا بئر معونہ کے شہداء پر غم پہنچا، وہ سب قتل کر دیے گئے تھے اور وہ سب قاری تھے۔ (1)","",{"k":"(1) صحیح البخاری (1300)، صحیح مسلم (677)، مسند احمد (111/3)، طبقات ابن سعد (54/2)، مصنف عبدالرزاق (9742)، صحیح ابی عوانة (285/2)، سنن الکبری للبیہقی (199/2)، شرح السنة للبغوی (635)۔","f":"اس حدیث سے ثابت ہوا کہ رسول اللہ صلی اللہ علیہ وسلم انسان اور بشر تھے، آپ صلی اللہ علیہ وسلم غمگین بھی ہوتے تھے اور خوشی کے موقع پر راضی بھی ہوتے تھے، بئر معونہ والا واقعہ صفر 4ھ میں پیش آیا، کافروں کا سردار عامر بن مالک خدمت نبوی صلی اللہ علیہ وسلم میں آیا اور کہا کہ میرا ملک اسلام کے لیے آمادہ ہے، کچھ واعظ ساتھ بھیج دیجیے، نبی کریم صلی اللہ علیہ وسلم نے 70 (ستر) عالم ساتھ کر دیے، جب وہ اُن کے علاقے میں پہنچے تو قبائل رعل وذکوان وبنو سلمہ وغیرہ نے حملہ کیا، صرف سیدنا عمرو بن امیہ ضمری رضی اللہ عنہ بچ کر آئے، باقی انہتر (69) قاریوں کو شہید کر دیا گیا۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے کبھی نبی اکرم صلی اللہ علیہ وسلم کو کسی بھی جنگی مہم کے حوالے سے اتنا زیادہ مغموم نہیں دیکھا، جتنا آپ صلی اللہ علیہ وسلم بئر معونہ کے افراد کے شہید ہونے پر مغموم ہوئے تھے۔ ان حضرات کو ’’قاری صاحبان‘‘ کہا جاتا ہے۔\nتخریج: متفق عليه"}],[1239,"انس بن مالک رضی اللہ عنہ نے فرمایا: دو آدمیوں کو رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں چھینک آئی، تو آپ نے ایک کی چھینک کا جواب دیا (یرحمک اللہ فرمایا) اور دوسرے کو جواب نہیں دیا، اس نے کہا: یا رسول اللہ! آپ نے اس کو تو جواب دیا اور مجھے جواب نہیں دیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس نے اللہ تعالیٰ کی حمد و ثنا کی اور تو نے اس ذات حق کی حمد نہیں کی۔ (1)","",{"k":"(1) صحیح البخاری (6221، 6225)، صحیح مسلم (2991)، سنن ابی داود (5039)، سنن الترمذی (2742)، سنن ابن ماجہ (3713)، عمل الیوم واللیلة للنسائی (222)، مسند احمد (100/3)، سنن الدارمی (2663)، مسند الطیالسی (2065)، مسند ابی یعلی (4060)، صحیح ابن حبان (600)۔","f":"اس حدیث سے معلوم ہوا کہ جس کو چھینک آئے اور وہ حمد و ثنا نہ کرے تو اس کو دعا (یرحمک اللہ) نہیں دینی چاہیے، اور صحابہ کرام رضوان اللہ علیہم اجمعین کو نبی کریم صلی اللہ علیہ وسلم کی دعا کی بڑی فکر ہوتی تھی۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم کی موجودگی میں دو آدمیوں کو چھینک آئی تو آپ صلی اللہ علیہ وسلم نے ایک کو جواب دیا اور دوسرے کو جواب نہیں دیا اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! آپ صلی اللہ علیہ وسلم نے اسے جواب دیا ہے مجھے جواب نہیں دیا تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: اس نے اللہ تعالیٰ کی حمد بیان کی تھی جبکہ تم نے حمد بیان نہیں کی۔\nتخریج: ايضا"}],[1240,"انس بن مالک رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اپنے خادم انجشہ کو فرمایا: آپ گنیوں کو نرمی کے ساتھ چلاؤ، یعنی خواتین کو۔ (1)","",{"k":"(1) صحیح البخاری (6209، 6211)، صحیح مسلم (2323)، مسند احمد (111/3)، طبقات ابن سعد (430/8)، مسند ابی یعلی (4064)، صحیح ابن حبان (5800)۔","f":"اس حدیث سے ثابت ہوا کہ عورتوں کے ساتھ نرمی سے پیش آنا چاہیے، اس کے متعلق شرح تفصیل سے گزر چکی ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ نے یہ بات بیان کی ہے نبی اکرم صلی اللہ علیہ وسلم نے اپنے خادم سے فرمایا: اے انجشہ! آرام سے چلو! تم کانچ کو لے کر جا رہے ہو۔ نبی اکرم صلی اللہ علیہ وسلم کی مراد خواتین تھیں۔\nتخریج: ايضا"}],[1241,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں اپنے انصاری چچا کی خدمت پر متعین تھا، ان کو فضیخ نامی شراب پلا رہا تھا، اتنے میں نبی کریم صلی اللہ علیہ وسلم کی طرف سے ایک آدمی دوڑتا ہوا آیا، تو ہم نے کہا: تیرے پس پشت خبر کیا ہے؟ تو اس نے کہا: شراب حرام کر دی گئی ہے، پس میرے چچا نے فرمایا: اے انس! اس کو گرا دے، تو میں نے شراب گرا دی، نضر بن انس نے فرمایا: ان کی شراب ان ایام میں یہی تھی۔ (1)","",{"k":"(1) صحیح البخاری (5583)، صحیح مسلم (1980)، سنن النسائی (5543)، مسند احمد (183/3، 189)، کتاب الاشربة (180)، صحیح ابن حبان (5352)، سنن الکبری للبیہقی (290/8)، من طریق سلیمان التمیمی عن انس، سنن ابی داود (3673)، من طریق ثابت عن انس۔","f":"اس حدیث سے ثابت ہوا کہ کسی دوسرے کی خدمت حاصل کر سکتے ہیں، اور صحابہ کرام رضوان اللہ علیہم اجمعین کو جب نبی کریم صلی اللہ علیہ وسلم کا حکم مل جاتا تھا تو وہ اسی وقت اس پر عمل کرتے تھے، یہی لوگ ما آتاکم الرسول فخذوہ وما نھاکم عنہ فانتھوا کے مصداق تھے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں اپنے ایک انصاری چچا کے ہاں کھڑا ہوا انہیں شراب پلا رہا تھا اسی دوران نبی اکرم صلی اللہ علیہ وسلم کی طرف سے ایک شخص گھبرائے ہوئے انداز میں ہمارے پاس آیا ہم نے دریافت کیا: تمہارے پیچھے کیا ہوا ہے؟ اس نے جواب دیا: شراب کو حرام قرار دے دیا گیا ہے تو ان حضرات نے مجھ سے فرمایا: اے انس! تم اسے بہا دو۔ سیدنا انس رضی اللہ عنہ کہتے ہیں: تو میں نے اسے بہا دیا۔ نضر بن انس کہتے ہیں: ان دنوں ان لوگوں کی شراب یہی ہوتی تھی۔\nتخریج: ايضا"}],[1242,"انس بن مالک رضی اللہ عنہ نے فرمایا: ہم لوگ منیٰ سے علی الصباح عرفہ گئے، ہم میں سے کوئی تو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تکبیر کہتا تھا، اور کوئی تلبیہ کہتا تھا اور کوئی فریق دوسرے فریق کو عیب نہیں لگاتا تھا۔ (1)","",{"k":"(1) صحیح البخاری (1659)، صحیح مسلم (1285)، سنن النسائی (3041)، سنن ابن ماجہ (3008)، مسند احمد (110/3)، مؤطا امام مالک (ص 229)، سنن الدارمی (1884)، مسند الشافعی (352/1)، صحیح ابن حبان (3847)، سنن الکبری للبیہقی (313/3)۔","f":"اس حدیث سے معلوم ہوا کہ منیٰ سے عرفہ کی طرف صبح کے وقت جانا چاہیے، اور منیٰ سے عرفہ جاتے وقت تکبیر اور تلبیہ دونوں میں سے کوئی بھی چیز پڑھ سکتا ہے، اور جو کوئی اچھا کام کرے اس پر عیب نہیں لگانا چاہیے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: آج کے دن ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ منیٰ سے عرفہ کی طرف روانہ ہوئے تھے، ہم میں سے کچھ لوگ تکبیر کہہ رہے تھے اور کچھ لوگ تلبیہ پڑھ رہے تھے اور ان میں سے کوئی ایک دوسرے کو غلط نہیں سمجھ رہا تھا۔\nتخریج: ايضا"}],[1243,"انس بن مالک رضی اللہ عنہ نے فرمایا: مکہ فتح کے سال رسول اللہ صلی اللہ علیہ وسلم جب مکہ میں داخل ہوئے تو آپ کے سر مبارک پر خود تھا۔ (1)","",{"k":"(1) صحیح البخاری (5808)، صحیح مسلم (1357)، سنن ابی داود (2685)، سنن الترمذی (1693)، شمائل ترمذی (112)، سنن النسائی (2870)، سنن ابن ماجہ (2805)، مسند احمد (109/3، 164)، سنن الدارمی (1944)، مؤطا امام مالک (ص 280)، صحیح ابن خزیمة (3063)، صحیح ابن حبان (3719)، مسند ابی یعلیٰ (3540)، طبقات ابن سعد (139/2)، سنن الکبری للبیہقی (59/7)۔","f":"اس حدیث سے ثابت ہوا کہ اپنی حفاظت کے لیے وسائل استعمال کرنا درست ہے۔ یہ توکل کے خلاف نہیں ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: فتح مکہ کے موقع پر جب نبی اکرم صلی اللہ علیہ وسلم مکہ میں داخل ہوئے، تو آپ صلی اللہ علیہ وسلم کے سر پر ’’خود‘‘ (فولادی ٹوپی) موجود تھا۔\nتخریج: ايضا"}],[1244,"انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو پیالے میں کدو کی طرف ہاتھ پھیلاتے دیکھا ہے، یہ وجہ ہے کہ میں ہمیشہ کدو کو پسند کرتا ہوں۔ (1)","",{"k":"(1) صحیح البخاری (2092)، صحیح مسلم (2041)، سنن ابی داود (3782)، سنن الترمذی (1850)، شمائل ترمذی (162)، سنن الکبری للنسائی (6628)، مسند احمد (150/3)، مؤطا امام مالک (ص 343)، سنن الدارمی (2056)، صحیح ابی عوانة (389/5، 390)، صحیح ابن حبان (4539)۔","f":"اس حدیث سے معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم کو کدو پسند تھا، اور جو چیز نبی کریم صلی اللہ علیہ وسلم کو پسند ہوتی تھی وہ صحابہ کرام رضوان اللہ علیہم اجمعین کو بھی پسند ہوتی تھی، جب صحابہ کرام رضوان اللہ علیہم اجمعین کو دنیاوی معاملات میں رسول اللہ صلی اللہ علیہ وسلم کی پسند کردہ چیزیں پسند ہوتی تھیں تو دینی معاملات میں کیوں پسند نہ ہوں؟","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم پیالے میں کدو تلاش کر رہے تھے تو اس کے بعد میں بھی ہمیشہ اس سے محبت رکھتا ہوں۔\nتخریج: ايضا"}],[1245,"قتادہ نے انس بن مالک رضی اللہ عنہ سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انگوٹھی تیار کرائی تھی؟ تو انھوں نے فرمایا: ہاں، گویا میں اس کی چمک چاندنی رات میں نبی کریم صلی اللہ علیہ وسلم کے ہاتھ میں دیکھ رہا ہوں۔ (1)","",{"k":"(1) صحیح البخاری (5869)، صحیح مسلم (640)، سنن النسائی (540)، سنن ابن ماجہ (692)، مسند احمد (182/3)، مسند ابی یعلی (3800)، شرح معانی الآثار (157/1، 158)، سنن الکبری للبیھقی (374/1)، وفیہ قال حمید: سئل انس۔","f":"اس حدیث سے معلوم ہوا کہ انگوٹھی پہننا سنت ہے اور انگوٹھی دائیں ہاتھ میں پہننی چاہیے، بعض لوگوں کا پانچوں انگلیوں میں انگوٹھیاں پہننا درست نہیں ہے، نیز مردوں پر سونے کی انگوٹھی پہننا حرام ہے، افسوس کہ شادی بیاہ کے موقع پر دولہا بڑے فخر سے سونے کی انگوٹھی پہنتے ہیں، جو لوگ دنیا میں سونا پہنتے ہیں، ان کو قیامت کے دن سونا نہیں پہنایا جائے گا۔","u2":"حمید طویل بیان کرتے ہیں: قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے دریافت کیا: کیا نبی اکرم صلی اللہ علیہ وسلم نے انگوٹھی استعمال کی ہے؟ انہوں نے جواب دیا: جی ہاں! نبی اکرم صلی اللہ علیہ وسلم کے دست مبارک میں چاندنی رات میں اس (انگوٹھی کی) چمک کا منظر آج بھی میری نگاہ میں ہے۔\nتخریج: ايضا"}],[1246,"حمید کہتے ہیں: میں نے انس بن مالک رضی اللہ عنہ کو کہتے سنا، انھوں نے فرمایا: میں ابو طلحہ کے پیچھے سوار تھا کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو اس طرح فرماتے سنا: میں حج اور عمرہ یکجا ادا کرنے کے لیے حاضر ہوں۔ (1)","",{"k":"(1) صحیح: سنن الترمذی (821)، سنن ابن ماجہ (2969)، مسند احمد (111/3)، سنن الدارمی (1930)، مسند ابی یعلی (3737)، شرح السنة للبغوی (1881)، سنن الکبری للبیھقی (288/2)، من طریق حمید عن انس، صحیح مسلم (251)، سنن ابی داود (1251)، سنن النسائی (2730)، من طریق یحییٰ وعبدالعزیز وحمید عن انس۔","f":"اس حدیث سے معلوم ہوا کہ حج قران جائز ہے، اور کسی کے پیچھے سوار ہونا بھی جائز ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی اکرم صلی اللہ علیہ وسلم کو سنا، میں اس وقت سیدنا ابو طلحہ رضی اللہ عنہ کے پیچھے سوار تھا۔ نبی اکرم صلی اللہ علیہ وسلم یہ پڑھ رہے تھے: ’’میں حج اور عمرہ ایک ساتھ کرنے کے لیے حاضر ہوں۔‘‘\nتخریج: ايضا"}],[1247,"حمیدی نے سفیان سے، انھوں نے مصعب بن سلیم سے، جو بنو زہرہ کے (عریف) چھوٹے سردار تھے، اس نے کہا: میں نے انس بن مالک رضی اللہ عنہ کو، وہ رسول اللہ صلی اللہ علیہ وسلم سے مثل اس کے روایت کرتے ہیں۔ (1)","",{"k":"(1) صحیح: مسند احمد (183/3)، مسند ابی یعلی (3646)، صحیح ابی عوانة کما فی اتحاف المھرة (1830)۔","u2":"یہی روایت ایک اور سند کے ہمراہ سیدنا انس بن مالک رضی اللہ عنہ سے منقول ہے۔\nتخریج: ايضا"}],[1248,"انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے پچھنے لگوائے، ان کو انصاری خاندان کے ایک غلام نے پچھنے لگائے تھے، اس خاندان کو بنو بیاضہ کہا جاتا تھا اور اس غلام کا نام ابو طیبہ تھا اور اس کو رسول اللہ صلی اللہ علیہ وسلم نے ایک صاع یا دو صاع یا ایک سیر یا دو سیر بھی دیے اور اس کے مالکان سے اس کے خراج میں کمی کرنے کی سفارش بھی فرمائی۔ (1)","",{"k":"(1) صحیح البخاری (2102)، صحیح مسلم (1577)، سنن ابی داود (2424)، سنن الترمذی (1278)، شمائل ترمذی (360)، مسند احمد (100/3)، مؤطا امام مالک (ص 597)، سنن الدارمی (2625)، مسند ابی یعلی (3757)، سنن الکبری للبیھقی (8/9، 337)۔","f":"اس حدیث سے ثابت ہوا کہ سینگی لگوانا درست ہے، آج کل اس کے دو طریقے ہیں: ایک گلاس کے ذریعے اور دوسرا مشین کے ذریعے، سینگی لگانے والے کو اجرت دینی چاہیے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں، نبی اکرم صلی اللہ علیہ وسلم نے پچھنے لگوائے۔ انصار کے کسی قبیلے کے ایک غلام نے آپ صلی اللہ علیہ وسلم کو پچھنے لگائے تھے۔ اس قبیلے کا نام ’’بنو بیاضہ‘‘ تھا اور اس شخص کا نام ابو طیبہ تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے اسے ایک صاع یا دو صاع، ایک مد یا دو مد (معاوضے کے طور پر) عطا کیے اور آپ صلی اللہ علیہ وسلم نے اس کے آقاؤں سے بات چیت کی تو انہوں نے اس کے ذمے لازم ادائیگی کو کم کر دیا، یعنی اس کے ذمے خراج کو کم کر دیا۔\nتخریج: ايضا"}],[1249,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے، تو مہاجرین کی مختلف گھرانوں پر قرعہ اندازی کی گئی اور عبدالرحمن بن عوف کا قرعہ سعد بن ربیع پر پڑا، جناب سعد نے عبدالرحمن کو کہا: میں اپنا مال تقسیم کر کے تجھے دیتا ہوں اور میری دو عورتوں میں سے تو پسند کرلے میں تیرے لیے طلاق دے دیتا ہوں، پھر تیرا (زرعی) کام بھی میں ہی کروں گا، تو عبدالرحمن نے اس کو کہا: اللہ تعالیٰ تجھے تیرے اہل اور تیرے مال میں برکت دے، مجھے صرف بازار کا راستہ بتا دے، پھر عبدالرحمن بازار گئے، جب ان کے پاس کچھ مال آ گیا تو انھوں نے ایک عورت کو پیغام نکاح دے کر عقد کر لیا، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: تو نے مہر میں کیا دیا؟ تو انھوں نے کہا: کھجور کی گٹھلی کے برابر سونا دیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ولیمہ بھی کر، خواہ ایک بکری ہی سہی۔ (1)","",{"k":"(1) صحیح البخاری (5167)، صحیح مسلم (1427)، سنن الترمذی (1933)، سنن النسائی (3353)، مسند احمد (190/3، 274)، مسند الشافعی (6/2)، مؤطا امام مالک (ص 342، 343)، مسند ابی یعلی (3836)، صحیح ابن حبان (4060)، سنن الکبری للبیھقی (237/7)۔","f":"اس حدیث سے معلوم ہوا کہ صحابہ کرام رضوان اللہ علیہم اجمعین اپنے اوپر دوسروں کو زیادہ ترجیح دیتے تھے، اور صحابہ کرام رضوان اللہ علیہم اجمعین خود محنت کرنا پسند کرتے تھے، کسی پر بوجھ نہیں بنتے تھے۔ عورت کو مہر نکاح کا پیغام بھیج سکتا ہے، اور مہر دینا فرض ہے۔ اور دعوت ولیمہ بھی فرض ہے۔ یہ قرعہ ڈالنا ٹھیک ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے، تو لوگوں کو مختلف جگہ پر ٹھہرایا گیا سیدنا عبدالرحمان بن عوف رضی اللہ عنہ سیدنا سعد بن ربیع رضی اللہ عنہ کے ہاں مہمان ٹھہرے تو سیدنا سعد رضی اللہ عنہ نے ان سے کہا: آئیے میں اپنا مال آپ کے ساتھ تقسیم کر لیتا ہوں اور آپ میری جس بیوی کے بارے میں چاہیں گے میں اس سے دستبردار ہو جاؤں گا اور آپ کی جگہ میں کام کر لیا کروں گا۔ تو سیدنا عبدالرحمان بن عوف رضی اللہ عنہ نے ان سے کہا: اللہ تعالیٰ آپ کے اہل خانہ اور آپ کے مال میں برکت عطا فرمائے! آپ بازار کی طرف میری رہنمائی کر دیں، پھر سیدنا عبدالرحمان بن عوف رضی اللہ عنہ بازار تشریف لے گئے انہیں کچھ آمدن حاصل ہوئی تو انہوں نے ایک خاتون کو شادی کا پیغام بھیجا اور اس کے ساتھ شادی کر لی تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے دریافت کیا: تم نے کتنے مہر کے عوض میں اس کے ساتھ شادی کی ہے؟ انہوں نے جواب دیا: سونے کی گٹھلی کے عوض میں تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ولیمہ کرو! خواہ ایک بکری ذبح کر کے دعوت دو۔\nتخریج: ايضا"}],[1250,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے مسجد کی قبلہ کی دیوار پر بلغم لگا ہوا دیکھا تو آپ نے اس کو کھرچ دیا اور پھر لوگوں کی طرف غصے کے ساتھ دیکھا اور فرمایا: کیا تم میں سے کوئی پسند کرتا ہے کہ اس کے منہ پر تھوک دیا جائے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب بندہ نماز میں کھڑا ہوتا ہے تو وہ اپنے رب کریم کے روبرو ہوتا ہے، پس اپنے سامنے ہرگز نہ تھوکے اور نہ دائیں طرف، لیکن بائیں طرف یا بائیں پاؤں کے نیچے تھوک دے اور اگر اتنی فرصت نہ ملے تو اپنے کپڑے میں تھوک کر اس طرح کر دے، حمیدی نے اپنے کپڑے کے کونے کی طرف اشارہ کر کے اس کو رگڑ دیا۔ (1)","",{"k":"(1) صحیح البخاری (241)۔ کتاب الصلاة، باب حک البزاق بالید من المسجد، حدیث: 405۔ سنن ابی داود (390)۔ سنن النسائی (309)۔ مسند احمد: 199/3، 200۔ سنن الدارمی (1403)۔ مصنف عبدالرزاق: 1692۔ المنتقی لابن الجارود: 405۔ سنن الکبری للبیھقی: 255/1۔ شرح السنة للبغوی: 491۔","f":"اس حدیث سے معلوم ہوا کہ مسجد میں ہر وہ چیز جو بری لگے، وہ نہیں ہونی چاہیے، اور بلغم ناپاک نہیں ہے، نماز میں تھوکنے کا طریقہ بیان ہوا ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں قبلہ کی سمت میں بلغم لگا ہوا دیکھا تو اسے کھرچ دیا۔ آپ صلی اللہ علیہ وسلم غصے کے عالم میں لوگوں کی طرف متوجہ ہوئے اور یہ ارشاد فرمایا: کیا کوئی شخص اس بات کو پسند کرتا ہے کہ اس کے چہرے کی طرف تھوک دیا جائے؟ جب بندہ نماز کے دوران کھڑا ہوتا ہے تو وہ اپنے پروردگار کے سامنے ہوتا ہے اس لیے کوئی شخص اپنے دائیں طرف یا سامنے کی طرف نہ تھوکے بلکہ اپنے بائیں طرف یا اپنے بائیں پاؤں کے نیچے تھوکے اگر اسے زیادہ جلدی اور تیزی میں تھوک آ رہا ہو تو پھر وہ اسے کپڑے میں تھوک کر اس کو اس طرح مل دے۔ حمیدی رحمہ اللہ تعالیٰ راوی نے اپنے کپڑے کے کنارے کی طرف اشارہ کر کے اسے مل کر دکھایا۔\nتخریج: ايضا"}],[1251,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے جمروں پر کنکر مارے اور اپنی قربانی ذبح کر دی، تو سر مونڈنے والے کی طرف اپنے سر مبارک کا دایاں طرف سامنے کیا اور اس نے مونڈ دیا، پھر بایاں طرف سامنے کیا تو اس نے مونڈ دیے، پھر آپ نے بال ابو طلحہ کو دیے اور ان کو حکم دیا کہ لوگوں میں تقسیم کر دے۔ (1)","",{"k":"(1) صحیح مسلم (1305)، سنن ابی داود (1982)، سنن الترمذی (912)، سنن الکبری للنسائی (4102)، مسند احمد (111/3)، صحیح ابن خزیمہ (2928)، صحیح ابن حبان (3879)، سنن الکبری للبیھقی (25/1)، من طریق سفیان بھذا الاسناد، مسند ابی یعلی (2827)، من طریق ھشام بن سعد، صحیح البخاری (171)، من طریق عبد اللہ بن عون عن محمد بن سیرین بہ۔","f":"مسلمان زندہ ہو یا مردہ، اس کے بال پاک ہیں، اس کے دلائل درج ذیل ہیں: امام محمد بن سیرین نے عبیدہ سے کہا کہ ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کے بال مبارک ہیں، جو ہمیں سیدنا انس یا ان کے گھر والوں کی طرف سے پہنچے ہیں، تو عبیدہ نے یہ سن کر فرمایا: ”لَانْ تَکُوْنَ عِنْدِیْ شَعْرَةٌ مِّنْہُ اَحَبُّ اِلَیَّ مِنَ الدُّنْیَا وَمَا فِیْھَا“ ”میرے پاس نبی کریم صلی اللہ علیہ وسلم کا ایک بال (بھی) ہوتا تو یہ مجھے دنیا اور اس کی ہر چیز سے زیادہ محبوب ہوتا۔“ (صحیح البخاری: 170) سیدنا انس رضی اللہ عنہ سے روایت ہے کہ جب نبی کریم صلی اللہ علیہ وسلم نے اپنے بالوں کو منڈوایا تو سیدنا ابو طلحہ رضی اللہ عنہ وہ پہلے شخص تھے، جنھوں نے آپ کے بالوں کو لیا تھا۔ (صحیح بخاری: 171) ان دونوں حدیثوں پر امام بخاری نے یہ باب باندھا ہے ”باب الماء الذی یغسل بہ شعر الانسان“ باب اس پانی کے بارے میں جس کے ساتھ انسان کے بالوں کو دھویا جاتا ہے۔ (کتاب الوضو، باب: 33) حافظ ابن حجر رحمہ اللہ اس کی توجیہ بیان کرتے ہوئے لکھتے ہیں: ”ان الشعر طاہر والا لما حفظوہ ولا تمنی عبیدہ ان یکون عندہ شعرة واحدة منہ واذ کان طاہرا فالماء الذی یغسل بہ طاہر“ (بال پاک ہیں، ورنہ (صحابہ کرام رضوان اللہ علیہم اجمعین) ان کی حفاظت نہ کرتے، اور عبیدہ (تابعی) تمنا نہ کرتے کہ ان کے پاس بھی نبی کریم صلی اللہ علیہ وسلم کا ایک بال ہوتا، جب بال پاک ہیں تو اس پانی میں جس میں ان کو دھویا گیا ہو، وہ بھی پاک ہے۔ (فتح الباری: 363/1) حافظ ابن حجر رحمہ اللہ مزید فرماتے ہیں: جمہور علماء بھی بالوں کو پاک سمجھتے ہیں، اور یہی ہمارے نزدیک صحیح ہے۔ (فتح الباری: 364/1) ام المومنین سیدہ ام سلمہ رضی اللہ عنہا کے پاس نبی کریم صلی اللہ علیہ وسلم کے کچھ بال تھے، جنھیں انھوں نے ایک چھوٹے پیالے میں رکھا ہوا تھا، یہ بال مہندی کی وجہ سے سرخ تھے، جب کسی شخص کو نظر لگ جاتی یا وہ بیمار ہو جاتا تو وہ اپنا پانی کا برتن سیدہ ام سلمہ رضی اللہ عنہا کے پاس بھیج دیتا، (آپ اس پانی کے برتن میں بال ڈبو دیتیں) اس سے یہ بھی معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم کے بالوں سے تبرک حاصل کرنا جائز ہے۔ (بشرطیکہ آپ صلی اللہ علیہ وسلم کے بال کہیں سے مل جائیں) (بخاری: 5896، وفتح الباری: 353/10) یاد رہے کہ بعض شہروں میں بعض بالوں کی نسبت رسول اللہ صلی اللہ علیہ وسلم کی طرف کی جاتی ہے، جو کہ ثابت نہیں ہے۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے جب ’’جمرہ‘‘ کی رمی کر لی اور قربانی کا جانور ذبح کر لیا تو آپ صلی اللہ علیہ وسلم نے اپنے سر کا دایاں حصہ سر مونڈنے والے کی طرف بڑھایا اور اس نے اسے مونڈ دیا پھر نبی اکرم صلی اللہ علیہ وسلم نے بایاں حصہ اس کی طرف بڑھایا تو اس نے اسے بھی مونڈ دیا پھر نبی اکرم صلی اللہ علیہ وسلم نے اپنے موئے مبارک سیدنا ابو طلحہ رضی اللہ عنہ کو دیئے اور انہیں یہ ہدایت کی: وہ انہیں لوگوں کے درمیان تقسیم کر دیں۔\nتخریج: ايضا"}],[1252,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے پاس کھجوریں لائی گئیں، آپ نے پاؤں پر بیٹھ کر تقسیم کیں اور جلدی جلدی کھائیں۔ (1)","",{"k":"(1) صحیح مسلم (2044)، شمائل ترمذی (142)، سنن الکبری للنسائی (6811)، سنن ابی داود (3770)، سنن الدارمی (2068)، مسند احمد (180/3)، مصنف ابن ابی شیبة (307/8)، مسند ابی یعلی (3647)، سنن الکبری للبیھقی (283/7)، شعب الایمان (5973)، شرح السنة (2842)۔","f":"اس حدیث میں کھانا بیٹھ کر کھانے کا طریقہ بیان کیا گیا ہے، بعض روایات میں (مقعیاً) کے الفاظ ہیں۔ (صحیح مسلم: 2044) اس کے معنی ہیں: پنڈلی اور ران کو ملا کر کولہوں پر بیٹھنا۔ (نیز دیکھیں: ارواء الغلیل: 29/7) آہستہ آہستہ کھانا کھانا اچھا نہیں ہے، بلکہ جلدی جلدی کھانا کھانا چاہیے، کھجور کھانے کو زندگی کا معمول بنانا چاہیے، اس کے بہت سے فوائد ہیں۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں کھجوریں لائی گئیں، تو آپ صلی اللہ علیہ وسلم نے انہیں تقسیم کرنا شروع کر دیا۔ آپ صلی اللہ علیہ وسلم غیر آرام دہ حالت میں (یعنی پاؤں کے بل) بیٹھے ہوئے تھے اور آپ صلی اللہ علیہ وسلم تیزی سے انہیں کھا رہے تھے۔\nتخریج: اخرجه مسلم في الاشربه"}],[1253,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: ایک آدمی نے اپنا غلام مدبر قرار دیا اور اس کا اس غلام کے علاوہ کوئی مال نہیں تھا، نبی کریم صلی اللہ علیہ وسلم نے اس کو فروخت کرا دیا، نعیم بن نحام نے اس کو خریدا تھا، عمرو بن دینار نے کہا: جابر رضی اللہ عنہ نے فرمایا: وہ ایک قبطی غلام تھا، جو ابن زبیر کی حکومت کے اول سال میں فوت ہوا، اس کا نام یعقوب قبطی تھا۔ (1)","",{"k":"(1) صحیح البخاری (2231)، صحیح مسلم (997/59)، سنن الترمذی (1219)، سنن ابن ماجہ (2513)، مسند احمد (308/3)، مسند الشافعی (69/2)، مسند ابی یعلی (1825)، مصنف عبدالرزاق (16663)، من طریق سفیان بن عیینة عن عمرو بن دینار وحدہ عن جابر، صحیح مسلم (997/59)، سنن ابی داود (3957)، سنن النسائی (4656)، مسند احمد (305/3)، صحیح ابن خزیمہ (2445)، صحیح ابن حبان (3342)، من طریق ابی الزبیر وحدہ عن جابر۔","f":"غلام مدبر اس کو کہتے ہیں جس کو کہا جائے کہ جب مالک فوت ہو جائے تو تو آزاد ہو جائے گا، اس حدیث سے معلوم ہوا کہ انسان کو اپنے اہل وعیال کا خیال رکھ کر کام کرنا چاہیے، اس حدیث میں ایک صحابی نے اپنے غلام کو وفات کے بعد آزاد قرار دے دیا تھا، جبکہ اس بندے کے پاس اس غلام کے علاوہ اور کوئی مال نہیں تھا، تو نبی کریم صلی اللہ علیہ وسلم نے فوت ہونے والے کی بات کا اعتبار نہیں کیا، بلکہ غلام کو فروخت کیا، اور اس کی مالیت اہل وعیال کو دے دی، نیز اس سے یہ بھی معلوم ہوا کہ باطل شرط کا کوئی اعتبار نہیں ہوتا۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: ایک شخص نے اپنے غلام کو مدبر کر دیا۔ اس کے پاس اس غلام کے علاوہ کوئی مال نہیں تھا تو نبی اکرم صلی اللہ علیہ وسلم نے اس غلام کو فروخت کروا دیا۔ سیدنا نعیم بن نحام رضی اللہ عنہ نے اسے خرید لیا۔ عمرو بن دینار کہتے ہیں: سیدنا جابر رضی اللہ عنہ نے یہ بات بیان کی ہے وہ ایک قبطی غلام تھا، جو سیدنا عبداللہ بن زبیر رضی اللہ عنہ کی حکومت کے پہلے سال میں فوت ہوا تھا۔ ابو زبیر نامی راوی نے یہ الفاظ اضافی نقل کیے ہیں: اس کا نام ’’یعقوب قبطی‘‘ تھا۔\nتخریج: متفق عليه"}],[1254,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جمعہ کے دن خطبہ ارشاد فرما رہے تھے کہ ایک آدمی مسجد میں داخل ہوا، آپ نے فرمایا: تو نے نماز پڑھی ہے؟ اس نے کہا: نہیں، آپ نے فرمایا: دو رکعات نماز پڑھ، سفیان نے کہا: راوی ابو الزبیر کا نام سلیک بن عمرو غطفانی ہے۔ (1)","",{"k":"(1) صحیح البخاری (931)، صحیح مسلم (875)، سنن ابی داود (1115)، سنن الترمذی (510)، سنن النسائی (1410)، سنن ابن ماجہ (1112)، مسند احمد (308/333)، سنن الدارمی (1563)، مسند ابی یعلی (1830)، صحیح ابن خزیمہ (1832)، من طریق عمرو بن دینار عن جابر، صحیح مسلم (875)، سنن ابن ماجہ (1112)، جزء القراءة خلف الامام للبخاری (159)، مسند احمد (363/3)، صحیح ابن خزیمہ (1832)، من طریق ابی الزبیر عن جابر۔","f":"اس حدیث سے ثابت ہوا کہ خطبہ کے دوران نماز پڑھنا درست ہے، اور خطیب کسی کو جو بغیر نماز پڑھے بیٹھ جائے، نماز کا کہہ سکتا ہے، اور مقتدی کو بات ماننی چاہیے۔ اس حدیث سے تحیة المسجد کی تاکید ثابت ہوتی ہے، فرضیت نہیں۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: ایک شخص مسجد میں داخل ہوا۔ نبی اکرم صلی اللہ علیہ وسلم اس وقت منبر پر موجود جمعے کا خطبہ دے رہے تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے اس سے دریافت کیا: کیا تم نے نماز ادا کر لی ہے؟ اس نے عرض کی: جی نہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم دو رکعت نماز ادا کر لو۔ سفیان نامی راوی کہتے ہیں: ابو زبیر نامی راوی نے اس روایت میں ان صاحب کا نام ’’سیدنا سلیک بن عمرو الغطفانی رضی اللہ عنہ‘‘ بیان کیا ہے۔\nتخریج: ايضا"}],[1255,"حسان بن جعدہ کہتے ہیں: میں نے حسن بن ابی الحسن کو مقام واسط کی مسجد میں جمعہ کے دن داخل ہوتے دیکھا، تو اس وقت ابن ہبیرہ جمعہ کا خطبہ دے رہے تھے تو حسن نے دو رکعات پڑھیں اور بیٹھ گئے۔ (1)","",{"k":"(1) ضعیف: حسان بن جعدہ راوی مجہول ہے، تاریخ الکبیر للبخاری (35/3)، مصنف عبدالرزاق (5515)، مصنف ابن ابی شیبة (110/2، 111)۔","u2":"حسان نامی راوی کہتے ہیں: میں نے حسن بن ابو الحسن کو ’’مسجد واسط‘‘ میں جمعہ کے دن داخل ہوتے دیکھا۔ اس وقت ابن ہبیرہ منبر پر خطبہ دے رہا تھا، تو انہوں نے پہلے دو رکعت ادا کیں پھر وہ بیٹھے۔\nتخریج: اخرجه ابن ابي شيبه"}],[1256,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: حدیبیہ کے دن ہم چودہ سو آدمی تھے، پس رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فرمایا: تم زمین میں سے افضل ترین لوگ ہو، جابر نے فرمایا: اگر میں دیکھ سکتا تو تمھیں اس درخت کی جگہ بھی بتا دیتا۔ (1)","",{"k":"(1) صحیح البخاری (4154)، صحیح مسلم (1856)، سنن الکبری للنسائی (11507)، مسند احمد (308/3)، مسند عبد بن حمید (1104)، مصنف ابن ابی شیبة (439/14، 440)، مسند الشافعی (198/2)۔","f":"اس حدیث میں بیعت رضوان کا ذکر ہے جو سیدنا عثمان رضی اللہ عنہ کی شہادت کی افواہ پھیلنے کے وقت ایک درخت کے نیچے ہوئی تھی۔ اس حدیث سے مہاجرین اور صحابہ کرام رضی اللہ عنہم کی فضیلت ثابت ہوتی ہے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: حدیبیہ کے دن ہم لوگ ۱۴۰۰ کی تعداد میں تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: آج کے دن تم لوگ روئے زمین کے سب سے بہتر فرد ہو۔ سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: اگر میری بصارت کام کرتی ہوتی تو میں تمہیں اس درخت کی جگہ دکھاتا۔\nتخریج: ايضا"}],[1257,"محمد بن عباد بن جعفر مخزومی کہتے ہیں: میں نے جابر بن عبداللہ انصاری سے بیت اللہ کے طواف کے دوران سوال کیا: کیا رسول اللہ صلی اللہ علیہ وسلم نے جمعہ کے دن روزہ رکھنے سے منع کیا تھا؟ تو انھوں نے فرمایا: ہاں، قسم ہے اس گھر کے رب کی۔ (1)","",{"k":"(1) صحیح البخاری (1984)، صحیح مسلم (1143)، سنن ابن ماجہ (1724)، سنن الکبری للنسائی (2745)، مسند احمد (312/3)، مصنف عبدالرزاق (7808)، سنن الدارمی (1748)، سنن الکبری للبیھقی (301/4، 302)، مسند ابی یعلی (2206)۔","f":"اس حدیث میں جمعہ کے دن روزہ رکھنے کی حرمت کا بیان ہے۔ طواف کے دوران اہم دینی باتیں کی جا سکتی ہیں، جس بات کا علم نہ ہو اس کا علماء سے سوال کر لینا چاہیے۔ مسئلہ بتاتے وقت قسم کھانا جائز ہے۔","u2":"محمد بن عباد بیان کرتے ہیں: میں نے سیدنا جابر بن عبداللہ الانصاری رضی اللہ عنہ سے دریافت کیا: وہ اس وقت بیت اللہ کا طواف کر رہے تھے۔ کیا نبی اکرم صلی اللہ علیہ وسلم نے جمعہ کے دن روزہ رکھنے سے منع کیا ہے؟ انہوں نے جواب دیا: اس گھر کے پروردگار کی قسم! جی ہاں۔\nتخریج: متفق عليه"}],[1258,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا: (اے جابر!) تو نے شادی کی ہے؟ تو میں نے کہا: ہاں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کنواری یا ثیبہ سے؟ میں نے کہا: ثیبہ سے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کسی چھوٹی عمر کی لڑکی سے نکاح کرتا جو تجھ سے کھیلتی اور تو اس سے کھیلا کرتا، میں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میرے باپ احد کی جنگ میں شہید ہو گئے ہیں اور انھوں نے نو بیٹیاں چھوڑی ہیں، اور اس طرح میری نو بہنیں ہیں، تو میں نے یہ بات پسند کی کہ میں انھی کی ہم عمر لڑکی ان کے ساتھ جمع نہ کروں، لیکن ایسی عورت سے نکاح کروں جو ان کی کنگھی کرے اور ان کی نگرانی بھی کر سکے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تو نے خوب کیا۔ (1)","",{"k":"(1) صحیح البخاری (4052)، صحیح مسلم (715/56)، سنن الترمذی (1100)، سنن النسائی (3221)، مسند احمد (308/3)، مسند الطیالسی (1706)، مسند ابی یعلی (1974)، صحیح ابن حبان (7138)، من طریق عمرو بن دینار عن جابر بن عبداللہ، مسند احمد (294/3)، من طریق محمد بن المنکدر عن جابر۔","f":"اس حدیث سے معلوم ہوا کہ کنواری لڑکی سے شادی کرنی چاہیے، کیونکہ جو محبت کنواری کر سکتی ہے، وہ ثیب (شادی شدہ) نہیں کر سکتی۔ انسان کو دیکھ سوچ کر شادی کرنی چاہیے، ایسی عورت سے جو گھر کا ماحول بہتر کر سکے، چلا سکے، اس حدیث سے سیدنا جابر رضی اللہ عنہ کی فقاہت اور عقل مندی ثابت ہوتی ہے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے دریافت کیا: اے جابر! کیا تم نے شادی کر لی ہے؟ میں نے عرض کی: جی ہاں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: کنواری کے ساتھ یا ثیبہ کے ساتھ؟ میں نے عرض کی: ثیبہ کے ساتھ۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم نے کسی لڑکی کے ساتھ شادی کیوں نہیں کی کہ وہ تمہارے ساتھ خوش ہوتی اور تم اس کے ساتھ خوش ہوتے؟ میں نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! میرے والد غزوہ احد کے موقع پر شہید ہو گئے تھے۔ انہوں نے ۹ بیٹیاں چھوڑی ہیں تو میری ۹ بہنیں ہیں۔ مجھے یہ اچھا نہیں لگا کہ میں ان کے ساتھ ایک لڑکی کو شامل کر دوں جو ان کی مانند کم سن ہو۔ میں ایک ایسی بیوی لانا چاہتا تھا جو ان کی کنگھی کر دیا کرے ان کی دیکھ بھال کیا کرے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم نے ٹھیک کیا ہے۔\nتخریج: ايضا"}],[1259,"(ایک راوی نے اس میں یہ بھی زیادہ نقل کیا ہے کہ جناب جابر رضی اللہ عنہ نے فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے نکاح کے موقع پر فرمایا: اے جابر! تمھارے ہاں قالین موجود ہے؟ تو میں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! ہمارے ہاں قالین کیسے ہوں گے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عنقریب ہوں گے۔ (1)","",{"k":"(1) صحیح البخاری (5161)، صحیح مسلم (2083)، سنن ابی داود (4145)، سنن النسائی (3389)، سنن الترمذی (2774)، مسند احمد (294/3)، مسند ابی یعلی (1978)، صحیح ابن حبان (6683)، صحیح ابی عوانة (469/5، 470)۔","f":"اس حدیث میں صحابہ کرام رضوان اللہ علیہم اجمعین کو خوشخبری دی گئی ہے کہ صحابہ کرام رضوان اللہ علیہم اجمعین بہت زیادہ فتوحات حاصل کر سکیں گے، کفار کے مال صحابہ رضی اللہ عنہم کے پاس آئیں گے، اللہ تعالیٰ صحابہ رضی اللہ عنہم کو فراوانی عطا فرمائیں گے، اور ایسے ہی ہوا۔","u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: جب میں نے شادی کر لی تو نبی اکرم صلی اللہ علیہ وسلم نے مجھ سے فرمایا: اے جابر! کیا تم نے قالین استعمال کیا ہے؟ میں نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! ہمارے پاس کہاں سے قالین آئیں گے؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: عنقریب آئیں گے۔\nتخریج: ايضا"}],[1260,"جابر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم سے جب بھی کسی چیز کا سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے کبھی بھی یہ نہیں کہا: نہیں۔ (1)","",{"k":"(1) صحیح البخاری (6034)، صحیح مسلم (2311)، الادب المفرد للبخاری (298)، شمائل ترمذی (352)، سنن الدارمی (71)، مسند احمد (307/3)، مسند ابی یعلی (2001)، صحیح ابن حبان (6376)، طبقات ابن سعد (368/1)، مسند الطیالسی (1720)۔","f":"اس حدیث میں رسول اللہ صلی اللہ علیہ وسلم کی سخاوت کا ذکر ہے، کہ آپ صلی اللہ علیہ وسلم ہر سوال کرنے والے کو خالی ہاتھ واپس نہیں موڑتے تھے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم سے جب بھی کوئی چیز مانگی گئی تو آپ نے کبھی ’’نہ‘‘ نہیں کی۔\nتخریج: ايضا"}],[1261,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: میں بیمار ہوا تو رسول اللہ صلی اللہ علیہ وسلم میری بیمار پرسی کے لیے تشریف لائے، ان کے ساتھ ابوبکر بھی تھے، دونوں پیادہ آئے تھے، مجھے غشی آئی تو رسول اللہ صلی اللہ علیہ وسلم نے پانی طلب کیا اور وضو کیا اور میرے اوپر وہ پانی ڈالا تو مجھے ہوش آ گیا تو میں نے عرض کی کہ یا رسول اللہ صلی اللہ علیہ وسلم! میں اپنا مال کیسے تقسیم کروں؟ رسول اللہ صلی اللہ علیہ وسلم خاموش رہے یہاں تک کہ آیت میراث نازل ہوئی۔ (1)","",{"k":"(1) صحیح البخاری (5651)، صحیح مسلم (1616)، سنن ابی داود (2886)، سنن الترمذی (2097)، سنن النسائی (139)، سنن ابن ماجہ (2728)، الادب المفرد للبخاری (511)، مسند احمد (307/3)، سنن الدارمی (739)، صحیح ابن خزیمہ (106)، مسند ابی یعلی (2018)، المنتقی لابن الجارود (958)، سنن الکبری للبیہقی (223/6)۔","f":"اس حدیث سے ثابت ہوا کہ بے ہوش آدمی پر پانی ڈالنے سے اس کی بے ہوشی ختم ہو جاتی ہے، مستعمل پانی پاک ہے، اس حدیث میں آیت میراث کے شان نزول کا ذکر ہے، دیگر کتب حدیث میں اس کے سبب نزول کے بارے میں ایک دوسری روایت بھی ہے کہ سیدنا سعد بن ربیع رضی اللہ عنہ وفات پا گئے، اور ان کی بیٹیوں کے چچا نے سارا ورثہ سنبھال لیا، سیدنا سعد رضی اللہ عنہ کی دو لڑکیاں تھیں، ان کی بیوی نے آپ صلی اللہ علیہ وسلم سے ورثے کا سوال کیا، تو یہ آیت نازل ہوئی، آپ صلی اللہ علیہ وسلم نے لڑکیوں کے چچا کو پیغام بھیجا کہ سعد کی دو بیٹیوں کو دو تہائی اور ان کی ماں کو آٹھواں حصہ دے دو، اور جو بچ جائے وہ تمھارے لیے ہے۔ (سنن ابی داود، کتاب الفرائض، باب ما جاء فی میراث الصلب: حدیث: 2891۔ عن جابر بن عبداللہ رضی اللہ عنہ، سنن الترمذی: 2092، مسند احمد: 352/3، حدیث: 14810۔ وقال البانی: حسن) آیت میراث کے بارے میں حافظ ابن کثیر لکھتے ہیں کہ یہ دونوں آیات اور اس سورت کی آخری آیت وراثت میں اصول کی حیثیت رکھتی ہیں، وراثت کے تفصیلی حصے ان تین آیات سے مستنبط ہیں، اور وراثت کے حصول سے متعلقہ احادیث بھی ان آیات کی تفسیر ہیں۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: میں بیمار ہوا۔ نبی اکرم صلی اللہ علیہ وسلم اور سیدنا ابو بکر رضی اللہ عنہ میری عیادت کے لیے تشریف لائے، یہ دونوں حضرات پیدل تشریف لائے تھے۔ مجھ پر بے ہوشی طاری ہوئی۔ نبی اکرم صلی اللہ علیہ وسلم نے پانی منگوایا اور وضو کیا، پھر آپ صلی اللہ علیہ وسلم نے اسے مجھ پر انڈیلا تو مجھے ہوش آ گیا۔ میں نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! میں اپنے مال کے بارے میں کیا فیصلہ دوں؟ میں اپنے مال کے بارے میں کیا طریقہ اختیار کروں؟ تو نبی اکرم صلی اللہ علیہ وسلم خاموش رہے یہاں تک کہ وراثت سے متعلق آیت نازل ہو گئی۔\nتخریج: ايضا"}],[1262,"حمیدی نے روایت کی سفیان سے، وہ ابو الزبیر سے، وہ جابر سے، انھوں نے فرمایا: آیت میراث میرے بارے میں نازل ہوئی ہے، ابوبکر کہتے ہیں: سفیان کا ابو الزبیر سے سماع نہیں ہے۔ (1)","",{"k":"(1) صحیح: سنن ابی داود (2887)، سنن الکبری للنسائی (6290)، مسند احمد (372/3)، مسند الطیالسی (1742)، مسند ابی یعلی (2180)، سنن الکبری للبیہقی (231/6)، من طریق ہشام الدستوائی عن ابی الزبیر عن جابر۔","u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: وراثت (کے حکم) سے متعلق آیت میرے بارے میں نازل ہوئی تھی۔ امام حمیدی رحمہ اللہ کہتے ہیں: سفیان نامی راوی نے ابو زبیر نامی راوی سے یہ روایت نہیں سنی ہے۔\nتخریج: اخرجه البيهقي في الفرائض"}],[1263,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے خندق کے دن لوگوں کو آواز دی، تو صرف زبیر بولے، آپ نے دوبارہ آواز دی تو پھر زبیر ہی بولے، آپ نے تیسری بار آواز دی تو پھر بھی زبیر ہی بولے، پس نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ہر نبی کا ایک مخصوص معاون ہوتا ہے اور میرا حواری زبیر بن عوام ہے، سفیان نے کہا: ہشام بن عروہ نے یہ الفاظ زائد بیان کیے ہیں: وہ میری پھوپھی کا بیٹا ہے۔ (1)","",{"k":"(1) صحیح البخاری (2846)۔ صحیح مسلم (2415)۔ سنن الترمذی (3744)۔ سنن ابن ماجہ (122)۔ سنن الکبری للنسائی: 8860۔ مسند احمد: 307/3۔ مسند ابی یعلی: 2022۔ صحیح ابی عوانة: 401/4۔ شرح مشکل الآثار للطحاوی: 3563۔ صحیح ابن حبان: 6985۔ سنن الکبری للبیہقی: 148/6۔","f":"اس حدیث سے سیدنا زبیر بن عوام رضی اللہ عنہ کی فضیلت ثابت ہوتی ہے، اس حدیث سے معلوم ہوا کہ اہم بات کو تین دفعہ دہرانا چاہیے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے غزوہ خندق کے موقع پر (دشمن کی جاسوسی کے لیے) لوگوں کو طلب کیا، تو سیدنا زبیر رضی اللہ عنہ نے خود کو پیش کیا۔ نبی اکرم صلی اللہ علیہ وسلم نے پھر لوگوں کو طلب کیا، تو سیدنا زبیر رضی اللہ عنہ نے خود کو پیش کیا۔ نبی اکرم صلی اللہ علیہ وسلم نے پھر انہیں طلب کیا تو سیدنا زبیر رضی اللہ عنہ نے خود کو پیش کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’ہر نبی کا ایک حواری ہوتا ہے اور میرا حواری زبیر ہے۔‘‘ سفیان کہتے ہیں: ہشام بن عروہ نامی راوی نے یہ الفاظ اضافی نقل کیے ہیں ’’میرا پھوپھی زاد (زبیر ہے)۔‘‘\nتخریج: اخرجه مسلم في فضائل الصحابه"}],[1264,"جابر بن عبداللہ رضی اللہ عنہ فرماتے ہیں: ایک گھر میں ایک بچہ پیدا ہوا تو اس کے باپ نے اس کا نام قاسم رکھا، تو ہم نے بچے کے باپ کو کہا: ہم تیری کنیت ابوالقاسم نہیں رکھیں گے اور نہ اچھی نگاہ سے تجھے دیکھیں گے، وہ آدمی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: تیرے بیٹے کا نام عبدالرحمن ہے۔ (1)","",{"k":"(1) صحیح البخاری (6187)، صحیح مسلم (2133)، الادب المفرد (815)، مسند احمد (307/3)، مصنف ابن ابی شیبة (672/8)، مسند ابی یعلی (2016)، شرح معانی الآثار للطحاوی (339/4، 340)، سنن الکبری للبیہقی (308/9)۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: کسی قبیلے میں ایک بچہ پیدا ہوا تو اس کے والد نے اس کا نام ’’قاسم‘‘ رکھا۔ تو ہم نے اس کے والد سے کہا: ہم تمہاری کنیت ’ابوالقاسم‘ نہیں رکھیں گے اور ہم تمہاری آنکھیں ٹھنڈی نہیں کریں گے تو اس کا والد نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ نبی اکرم صلی اللہ علیہ وسلم نے اسے فرمایا: تم اپنے بیٹے کا نام عبد الرحمان رکھ لو۔\nتخریج: متفق عليه"}],[1265,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے جابر! اگر بحرین کا مال آیا تو میں تجھے اتنا، اتنا اور اتنا دوں گا، نبی کریم صلی اللہ علیہ وسلم وفات پا گئے اور بحرین کا مال نہ آیا، مال ابوبکر صدیق کی خلافت میں پہنچا، ابوبکر نے منادی کرا دی کہ جس کا نبی کریم صلی اللہ علیہ وسلم پر قرض ہو یا آپ نے کسی سے مال کا وعدہ کیا ہو تو وہ حاضر ہو، جناب جابر نے فرمایا: میں ابوبکر کے پاس حاضر ہوا اور میں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: بحرین کا مال آیا تو تجھے اس طرح، اس طرح اور اس طرح دوں گا، ابوبکر نے ایک بار مٹھی بھر کر مجھے دی اور کہا شمار کر، میں نے شمار کیا تو پانچ سو تھا تو ابوبکر نے کہا: اس کی مثل دوبار گن کر وصول کر لے۔ (1)","",{"k":"(1) صحیح البخاری (2296)، صحیح مسلم (2314)، طبقات ابن سعد (318/2)، مسند ابی یعلی (1966)، شرح معانی الآثار للطحاوی (355)، التمہید لابن عبدالبر (210/3، 211)، من طریق محمد بن علی عن جابر۔","f":"اس حدیث میں ایک پیش گوئی اور معجزہ ہے کہ بحرین سے مال آئے گا، اور آیا صحابہ کرام رضوان اللہ علیہم اجمعین نے دیکھا اور تقسیم کیا گیا، اس سے معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم وفات پا چکے ہیں، اس سے یہ بھی معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم بھی وعدہ کرتے تھے اور کوئی وعدوں کی پاسداری نہ کر سکے اور دنیا سے کوچ کر گئے۔","u2":"امام محمد الباقر بیان کرتے ہیں: میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو یہ بیان کرتے ہوئے سنا: نبی اکرم صلی اللہ علیہ وسلم نے مجھ سے فرمایا: اے جابر! جب اگر ہمارے پاس بحرین کا مال آئے گا، تو میں تمہیں اتنا، اتنا اور اتنا دوں گا۔ پھر نبی اکرم صلی اللہ علیہ وسلم کا وصال ہو گیا۔ بحرین کا مال نہیں آیا۔ وہ سیدنا ابو بکر رضی اللہ عنہ کے عہد خلافت میں آیا، تو سیدنا ابو بکر رضی اللہ عنہ نے ایک شخص کو اعلان کرنے کے لیے کہا کہ جس شخص کو نبی اکرم صلی اللہ علیہ وسلم نے کوئی ادائیگی کرنی ہو یا آپ صلی اللہ علیہ وسلم نے اس کے ساتھ کوئی وعدہ کیا ہو تو وہ آ جائے۔ سیدنا جابر رضی اللہ عنہ کہتے ہیں: میں سیدنا ابو بکر رضی اللہ عنہ کے پاس آیا۔ میں نے ان سے یہ کہا: نبی اکرم صلی اللہ علیہ وسلم نے یہ فرمایا تھا: ’’اگر بحرین کا مال آیا، تو میں تمہیں اتنا، اتنا اور اتنا دوں گا۔‘‘ تو سیدنا ابو بکر رضی اللہ عنہ نے دونوں ہتھیلیاں ملا کر بھر کر مجھے دیا، پھر مجھ سے فرمایا: تم اس کی گنتی کر۔ میں نے اس کی گنتی کی تو وہ پانچ سو (درہم) تھے۔ سیدنا ابو بکر رضی اللہ عنہ نے فرمایا: تم اس سے دو گنا اور لے لو۔\nتخریج: اخرجه البخاري في الكفالة"}],[1266,"ابن منکدر کی روایت میں ہے کہ جابر نے کہا: میں ابوبکر کے پاس پہلی بار آیا تو انھوں نے مجھے نہیں دیا، میں دوبارہ ان کے پاس آیا تو انھوں نے مجھے نہ دیا اور پھر میں تیسری بار آیا اور میں نے کہا: اے ابو بکر! میں نے آپ سے مال طلب کیا تو آپ نے نہ دیا، میں نے پھر طلب کیا تو آپ نے نہ دیا اور اب یہ دے دے یا بخل کر کے رکھ لے اور مجھے نہ دے، تو ابوبکر رضی اللہ عنہ نے فرمایا: تو کہتا ہے کہ تیرے ساتھ بخل کر کے نہ دوں، وہ کون سی بڑی بیماری ہو گی جو بخل سے زیادہ مہلک ہو گی؟ میں نے پہلی مرتبہ تو تجھے نہیں دیا تھا، مگر دل میں یہی ارادہ تھا کہ تجھے ضرور دوں گا۔ (1)","",{"k":"(1) صحیح البخاری (2598، 3137)، صحیح مسلم (2314)، مسند احمد (307/3)، مسند الشافعی (197/2)، طبقات ابن سعد (318/2)، مسند ابی یعلی (2019)، من طریق محمد بن المنکدر عن جابر۔","f":"قوم کا امیر بہت دانا ہوتا ہے، اگر امیر کسی وقت کسی شخص سے تعاون روک دے اور دوسرے سے تعاون کر دے اور اس کی نیت ہو کہ کسی اور موقع پر اس سے تعاون کر دوں گا، تو اس کا مقصود حوصلہ شکنی نہیں ہوتا، انسان حرص ہے، لیکن سیدنا ابوبکر رضی اللہ عنہ بخیل نہیں تھے، اگر بخیل ہوتے تو اپنا سارا مال صدقہ نہ کرتے، اور آپ کی خدمات ایک مکمل تاریخ ہیں۔","u2":"یہی روایت ایک اور سند کے ہمراہ منقول ہے تاہم اس میں یہ الفاظ ہیں: ’’سیدنا ابو بکر رضی اللہ عنہ نے دونوں ہتھیلیاں ملا کر تین مرتبہ مجھے دیا۔‘‘ ابن منکدر نامی راوی نے یہ الفاظ نقل کیے ہیں: سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: اس کے بعد میں سیدنا ابو بکر رضی اللہ عنہ کے پاس آیا۔ میں نے ان سے کہا: مجھے کچھ دیجئے، تو انہوں نے مجھے کچھ نہیں دیا۔ میں پھر ان کے پاس آیا اور ان سے کہا: مجھے کچھ دیجئے، تو انہوں نے مجھے کچھ نہیں دیا۔ میں پھر ان کے پاس آیا۔ میں نے ان سے کہا: مجھے کچھ دیجئے، تو انہوں نے مجھے کچھ نہیں دیا۔ میں نے کہا: اے ابو بکر! میں نے آپ سے کچھ مانگا ہے، آپ مجھے کچھ دیں لیکن آپ نے مجھے کچھ نہیں دیا۔ پھر میں نے آپ سے مانگا کہ آپ مجھے کچھ دیں لیکن آپ نے مجھے کچھ نہیں دیا۔ یا تو آپ مجھے کچھ دیں گے یا پھر آپ میرے حوالے سے بخل سے کام لیں گے، تو سیدنا ابو بکر رضی اللہ عنہ بولے: تم یہ کہہ رہے ہو کہ تم میرے حوالے سے بخل سے کام لو گے؟ کنجوسی سے زیادہ قابل علاج بیماری اور کون سی ہے؟ میں نے ایک مرتبہ تمہیں منع نہیں کیا ہے کیونکہ میں تمہیں دینا چاہتا ہوں۔\nتخریج: متفق عليه"}],[1267,"جابر بن عبداللہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کھانا کھا کر انگلیاں اور برتن چاٹنے کا حکم دیا اور فرمایا: کسی کو کیا معلوم برکت کہاں اور کس میں ہے؟ (1)","",{"k":"(1) صحیح مسلم (2033)، سنن ابن ماجہ (3270)، سنن الکبری للنسائی (6767)، مسند احمد (301/3)، مسند عبد بن حمید (1067)، شعب الایمان للبیہقی (5856)، مسند ابی یعلی (3246)، صحیح ابی عوانة (366/5، 370)، صحیح ابن حبان (5253)۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں، نبی اکرم صلی اللہ علیہ وسلم نے انگلیاں اور پیالہ چاٹنے کا حکم دیا ہے آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: یہ نہیں پتہ ہے اس میں کہاں برکت ہے؟\nتخریج: اخرجه مسلم في الاشربه"}],[1268,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں جنت میں داخل ہوا اور ایک محل دیکھا اور پوچھا: یہ کس کا ہے؟ تو مجھے بتایا گیا کہ یہ عمر بن خطاب کا ہے، اے ابو حفص! اگر تیری غیرت کا خیال نہ ہوتا تو میں اس میں داخل ہوتا، راوی کہتے ہیں: عمر رو دیے اور عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! کیا میں آپ پر غیرت کرتا؟ (1)","",{"k":"(1) صحیح البخاری (3679)، صحیح مسلم (2394)، سنن الکبری للنسائی (8125)، مسند احمد (309/3)، مسند ابی یعلی (2014)، مصنف ابن ابی شیبة (28/12)، صحیح ابن حبان (6886)۔","f":"اس حدیث سے سیدنا عمر رضی اللہ عنہ کی فضیلت اور غیرت ثابت ہوتی ہے، سیدنا عمر رضی اللہ عنہ کو کبھی دنیا میں جنت کی خوشخبری مل گئی تھی، سیدنا عمر رضی اللہ عنہ اتنے بہادر ہونے کے باوجود دین کے معاملے میں بہت نرم دل تھے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ روایت کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میں جنت میں داخل ہوا تو میں نے وہاں ایک محل (راوی کو شک ہے شاید یہ الفاظ ہیں) میں نے ایک گھر دیکھا۔ میں نے دریافت کیا: یہ گھر کس کا ہے؟ تو مجھے بتایا گیا: یہ عمر بن خطاب کا ہے۔ اے ابو حفص! اگر تمہارے مزاج کی تیزی کا خیال نہ ہوتا تو میں اس کے اندر چلا جاتا۔‘‘ سیدنا جابر رضی اللہ عنہ کہتے ہیں: سیدنا عمر رضی اللہ عنہ رو پڑے اور عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! کیا میں آپ صلی اللہ علیہ وسلم پر غصہ کروں گا؟\nتخریج: اخرجه مسلم في فضائل الصحابه"}],[1269,"جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں جنت میں داخل ہوا تو میں نے اس میں ایک محل یا گھر دیکھا، میں نے وہاں کچھ لوگوں کی آواز سنی، تو میں نے کہا: یہ کس کا محل ہے؟ کہا گیا: یہ قریش میں سے ایک آدمی کا ہے، مجھے امید پیدا ہوئی کہ یہ میرا محل ہو گا؟ تو کہا گیا: یہ عمر بن خطاب کا محل ہے، اے ابو حفص! اگر تیری غیرت کا خیال نہ ہوتا تو میں اس میں داخل ہوتا، راوی نے کہا کہ عمر رونے لگے، انھوں نے عرض کی: اے اللہ کے رسول صلی اللہ علیہ وسلم! آپ پر بھی غیرت آ سکتی ہے؟ (1)","",{"k":"(1) صحیح البخاری (3679)، صحیح مسلم (2394)، وانظر الحدیث السابق۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ روایت کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’میں جنت میں داخل ہوا تو میں نے اس میں ایک محل (راوی کو شک ہے شاید یہ الفاظ ہیں) ایک گھر دیکھا۔ میں نے اس میں آواز سنی۔ میں نے دریافت کیا: یہ کس کا ہے؟ تو مجھے کہا گیا: یہ قریش سے تعلق رکھنے والے ایک فرد کا ہے۔ مجھے یہ امید ہوئی کہ یہ میرا ہوگا۔ تو مجھے یہ بتایا گیا: یہ عمر بن خطاب کا ہے۔ اے ابو حفص! اگر تمہارے مزاج کی تیزی کا خیال نہ ہوتا تو میں اس کے اندر چلا جاتا۔‘‘ سیدنا جابر رضی اللہ عنہ کہتے ہیں: سیدنا عمر رضی اللہ عنہ رو پڑے اور عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! کیا آپ صلی اللہ علیہ وسلم کے سامنے غصہ کیا جا سکتا ہے؟\nتخریج: متفق عليه"}],[1270,"جابر بن عبداللہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنگ چال چلنے کا نام ہے۔ (1)","",{"k":"(1) صحیح البخاری (3030)، صحیح مسلم (1739)، سنن ابی داود (2636)، سنن الترمذی (1675)، سنن الکبری للنسائی (8589)، مسند احمد (308/2)، مسند الطیالسی (1698)، مصنف ابن ابی شیبة (530/12)، مسند ابی یعلی (1826)، مسند الشہاب (9، 10)، سنن الکبری للبیہقی (40/7)۔","f":"اس حدیث سے معلوم ہوا کہ جنگ میں دھوکا دینا درست ہے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ روایت کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا ہے: ’’جنگ دھوکہ دینے کا نام ہے۔‘‘\nتخریج: متفق عليه"}],[1271,"ہم سے بیان کیا حمیدی نے، وہ روایت کرتے ہیں سفیان سے، انھوں نے کہا: عمرو بن دینار نے کہا: یہ لفظ تو خدعہ ہے اور اہل عربیت خدعہ کہتے ہیں۔ (1)","",{"k":"(1) صحیح، غریب الحدیث للخطابی: 166/2۔","u2":"عمرو بن دینار کہتے ہیں: لفظ ’’خدعہ‘‘ کے تلفظ میں اختلاف پایا جاتا ہے۔\nتخریج: انظر معالم السنن"}],[1272,"جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوہ میں تھے، ایک مہاجر آدمی نے ایک انصاری آدمی کو مکا رسید کر دیا تو انصاری نے کہا: اے انصار والو! مہاجر نے بھی نعرہ لگایا: اے مہاجرین، رسول اللہ صلی اللہ علیہ وسلم نے سنا تو فرمایا: یہ کیسی آواز ہے؟ عرض کیا گیا: ایک مہاجر نے انصاری کو تھپڑ مارا ہے، تو انصاری نے یا انصار کا نعرہ بلند کیا اور مہاجر نے بھی اے مہاجرین کی آواز بلند کی ہے، پس نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جاہلیت کی پکار کا کیا حال ہے؟ اس کو ترک کر دو، یہ بدبودار نعرے ہیں، عبداللہ بن ابی سلول (منافق) نے کہا: اچھا ایسا ہوا ہے؟ اللہ کی قسم! مدینہ میں پہنچ کر ہم باعزت لوگ ان ذلیل لوگوں کو نکال دیں گے، جابر نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ میں تشریف لائے تھے، اس وقت انصار زیادہ تھے، پھر مہاجرین کی تعداد زیادہ ہو گئی، جناب عمر نے عرض کی: یا رسول اللہ! اجازت ہو تو اس منافق کی گردن مار دوں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کو جانے دے، لوگ یہ نہ کہیں کہ محمد صلی اللہ علیہ وسلم اپنے اصحاب کو قتل کرنے لگے ہیں۔ (1)","",{"k":"(1) صحیح البخاری (4907)، صحیح مسلم (2584)، سنن الترمذی (3315)، سنن الکبری للنسائی (11599)، عمل الیوم واللیلة للنسائی (977)، مسند احمد (392/3، 393)، مسند الطیالسی (1708)، مصنف عبدالرزاق (18041)، مسند ابی یعلی (1824)، صحیح ابن حبان (5990)، دلائل النبوة للبیہقی (53/4، 54)۔","f":"اسلام لانے کے بعد بھی صحابہ کرام رضوان اللہ علیہم اجمعین میں جاہلیت کا کچھ اثر تھا، لیکن ہر پہلو پر نبی کریم صلی اللہ علیہ وسلم ان کی تربیت کرتے تھے، نبی کریم صلی اللہ علیہ وسلم کو اپنے اصحاب سے بڑی محبت تھی، کسی مصلحت کی بنا پر اچھا کام چھوڑنا سنت ہے، بشرطیکہ وہ کام فرض نہ ہو۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: ہم لوگ ایک جنگ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے مہاجرین سے تعلق رکھنے والے ایک شخص نے ایک انصاری کی پیٹھ پر ہاتھ (یا پاؤں) مارا تو انصاری نے کہا: اے انصار (میری مدد کے لیے آؤ) اور مہاجر نے کہا: اے مہاجرین (میری مدد کے لیے آؤ) راوی کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے یہ بات سن لی، آپ صلی اللہ علیہ وسلم نے دریافت کیا: کیا ہوا ہے؟ لوگوں نے بتایا: مہاجرین سے تعلق رکھنے والے ایک شخص نے انصار سے تعلق رکھنے والے ایک شخص کو مارا تو انصاری نے یہ کہا: اے انصار (میری مدد کے لیے آؤ) تو مہاجر نے بھی یہ کہا: اے مہاجرین (میری مدد کے لیے آؤ) تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: یہ زمانہ جاہلیت کا طرز عمل ہے تم اسے چھوڑ دو کیونکہ یہ گندگی والا ہے (جب اس بات کا پتہ عبد اللہ بن ابی کو چلا) تو عبداللہ بن ابی بولا: کیا ان لوگوں نے ایسا کیا ہے؟ اللہ کی قسم! جب ہم مدینہ واپس جائیں گے تو وہاں کے عزت دار لوگ ذلیل لوگوں کو وہاں سے نکال دیں گے۔ سیدنا جابر رضی اللہ عنہ کہتے ہیں: انصار مدینہ منورہ میں مہاجرین سے زیادہ تھے جب نبی اکرم صلی اللہ علیہ وسلم مدینہ منورہ تشریف لے آئے تو مہاجرین زیادہ ہو گئے۔ سیدنا عمر رضی اللہ عنہ نے عرض کی آپ صلی اللہ علیہ وسلم مجھے اجازت دیجئے کہ میں اس منافق کی گردن اڑا دوں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اسے چھوڑ دو! ورنہ لوگ یہ کہیں گے حضور صلی اللہ علیہ وسلم! اپنے ساتھیوں کو قتل کروا رہے ہیں۔\nتخریج: متفق عليه"}],[1273,"حمیدی اپنی سند کے ساتھ روایت کرتے ہیں کہ عبداللہ بن عبداللہ بن ابی بن سلول (منافق کا بیٹا جو سچا ایمان دار تھا، ان کا نام بھی عبداللہ ہے) نے اپنے باپ عبداللہ کو کہا: تو مدینہ منورہ میں داخل نہ ہو گا یہاں تک کہ تو یہ کہے کہ رسول اللہ صلی اللہ علیہ وسلم ہی زیادہ عزت والے ہیں اور میں (ابن ابی بن سلول) ہی بہت ذلیل ہوں، راوی کہتے ہیں کہ وہ (عبداللہ بن عبداللہ) دوڑ کر نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: مجھے یہ خبر پہنچی ہے کہ آپ میرے باپ کو قتل کرانے کا ارادہ رکھتے ہیں، اے اللہ کے رسول صلی اللہ علیہ وسلم! جس ذات نے آپ کو حق کے ساتھ مبعوث کیا ہے، میں اپنے باپ کے چہرے کی طرف اس کی ہیبت اور احترام کی وجہ سے دیکھ بھی نہیں سکا ہوں لیکن اگر آپ چاہتے تو میں خود اس کا سر کاٹ کر خدمت میں پیش کر دیتا ہوں، البتہ مجھے ضرور نا گوار ہو گا کہ میں اپنے باپ کے قاتل کو دیکھتا رہوں۔ (1)","",{"k":"(1) ضعیف: سند مرسل ہے، ابوہارون موسیٰ تابعی صغیر ہے، سیرة ابن ہشام (526/1، 527)، اسد الغابة (296/3، 297)، الاصابة (142/6، 143)، تفسیر ابن جریر (113/28)، تفسیر در منثور (166/8)۔","f":"اس حدیث سے معلوم ہوا کہ صحابہ کرام رضوان اللہ علیہم اجمعین کو اپنے والدین سے زیادہ رسول اللہ صلی اللہ علیہ وسلم سے محبت تھی۔","u2":"ابو ہارون مدنی بیان کرتے ہیں: عبداللہ بن ابی کے بیٹے سیدنا عبداللہ رضی اللہ عنہ نے اپنے والد سے کہا: اللہ کی قسم! تم اس وقت تک مدینہ میں داخل نہیں ہو سکتے جب تک تم یہ نہیں کہو گے کہ نبی اکرم صلی اللہ علیہ وسلم عزت دار ہیں اور تم ذلیل ترین ہو۔ راوی بیان کرتے ہیں: وہ شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! مجھے پتہ چلا کہ آپ صلی اللہ علیہ وسلم میرے والد کو قتل کروانا چاہ رہے ہیں؟ اس ذات کی قسم! جس نے آپ صلی اللہ علیہ وسلم کو حق کے ساتھ مبعوث کیا ہے۔ اپنے باپ کی ہیبت کی وجہ سے میں اس کے قتل میں تامل نہیں کروں گا، اگر آپ صلی اللہ علیہ وسلم چاہتے ہیں میں اس کا سر لے کر آؤں تو میں وہ بھی لے آتا ہوں۔ لیکن مجھے یہ بات پسند نہیں ہے میں اپنے باپ کے قاتل کو دیکھوں (یا مجھے اپنے باپ کا قاتل سمجھا جائے)۔\nتخریج: ايضا"}],[1274,"جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے کہ ایک اعرابی مدینہ میں آیا اور نبی کریم صلی اللہ علیہ وسلم سے ہجرت پر بیعت کی، پھر اس کو بخار ہو گیا تو وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہنے لگا: یا رسول اللہ! میری بیعت واپس کر دیں، آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں، پھر بخار تیز ہوا تو وہ پھر حاضر ہوا، اور عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! میری بیعت مجھے واپس کر دیں، آپ نے پھر فرمایا: نہیں، پھر اس کا بخار مزید شدت اختیار کر گیا، اور وہ تیسری بار آپ کی خدمت میں حاضر ہوا اور عرض کی: اے اللہ کے رسول صلی اللہ علیہ وسلم! میری بیعت واپس کر دیں تو آپ نے انکار فرمایا، پھر بخار زیادہ تیز ہوا تو وہ بھاگ گیا اور مدینہ سے نکل گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مدینہ منورہ لوہار کی بھٹی کی مانند ہے، جیسے لوہار کی بھٹی میل کو دور کر دیتی ہے اور عمدہ کو صاف کر کے باقی رہنے دیتی ہے۔ (1)","",{"k":"(1) صحیح البخاری (1883)، صحیح مسلم (1383)، سنن الترمذی (3920)، سنن النسائی (4190)، مؤطا امام مالک (ص 545)، مسند احمد (307/3)، مسند ابی یعلی (2023)، شرح مشکل الآثار للطحاوی (1730)، صحیح ابن حبان (2732)، شرح السنة للبغوی (2015)۔","f":"اس حدیث سے معلوم ہوا کہ کوئی فاسق وفاجر شخص مدینہ میں نہیں رہ سکتا، صرف عمدہ اور اچھے لوگ مدینہ میں رہ سکتے ہیں۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: ایک دیہاتی مدینہ منورہ آیا۔ اس نے نبی اکرم صلی اللہ علیہ وسلم کے دست اقدس پر ہجرت کی بیعت کی۔ اسے بخار ہو گیا۔ وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! میری بیعت مجھے واپس کیجئے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جی نہیں! پھر تب اس کا بخار تیز ہو گیا۔ وہ پھر نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! میری بیعت مجھے واپس کر دیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جی نہیں! پھر اس کا بخار اور تیز ہو گیا۔ وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! میری بیعت مجھے واپس کر دیں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جی نہیں! پھر اس کا بخار اور شدید ہو گیا تو وہ مدینہ منورہ سے خوفزدہ ہو کر چلا گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: مدینہ منورہ کی مثال بھٹی کی مانند ہے جو زنگ کو نکال دیتی ہے اور صاف چیز کو نکھار دیتی ہے۔\nتخریج: متفق عليه"}],[1275,"جابر بن عبداللہ رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہم تین سو افراد کو ابو عبیدہ بن جراح رضی اللہ عنہ کی سرکردگی میں قریش کے ایک قافلہ کی گھات میں روانہ کیا، ہمیں شدید بھوک اور فاقہ پیش آیا، یہاں تک کہ ہم نے درختوں کے پتے کھائے، اسی وجہ سے اس سریہ کا نام جیش الخبط پڑ گیا، انھوں نے فرمایا: ہم ساحل سمندر پر تھے پس سمندر نے ایک بہت بڑی مچھلی باہر پھینک دی، جس کو عنبر مچھلی کہا جاتا تھا، نصف ماہ تک ہم اس کا گوشت کھاتے، شوربا بناتے اور چربی بطور تیل استعمال کرتے رہے، ہمارے جسم اچھی طرح مضبوط ہو گئے، ابو عبیدہ نے اس کی پسلی کی ہڈی نصب کر کے طویل قد والا مرد بڑے اونٹ پر سوار کر کے اس کے نیچے سے گزار دیا تو وہ آسانی سے گزر گیا، پھر ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ کو واقعہ سنایا، آپ نے فرمایا: اس میں سے کچھ باقی ہے؟ ہم نے کہا: نہیں۔ (1)","",{"k":"(1) صحیح البخاری (4361)، صحیح مسلم (1935)، سنن النسائی (4357)، مسند احمد (308/3، 309)، سنن الدارمی (2018)، مصنف عبدالرزاق (8667)، صحیح ابی عوانة (145/5)، مسند ابی یعلی (1955)، صحیح ابن حبان (5259)، سنن الکبری للبیہقی (251/9)۔","f":"اس حدیث سے صحابہ کرام رضوان اللہ علیہم اجمعین کی فضیلت ثابت ہوتی ہے، اور اللہ تعالیٰ اپنے بندوں کے لیے مچھلیوں کو بھی مسخر کر دیتے ہیں، اللہ تعالیٰ کی عجیب وغریب تخلیقات ہیں، اور وہ ان کو روزی دیتا ہے، سمندر کے کنارے پر پڑی مچھلی حلال ہے، یہ بڑا معجزہ ہے، بہت بڑا معجزہ ہے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے ہم ۳۰۰ سواروں کو ایک مہم پر بھیجا۔ ہمارے امیر سیدنا ابو عبیدہ بن الجراح رضی اللہ عنہ تھے۔ ہم قریش کے ایک قافلے کی گھات میں تھے۔ ہمیں شدید بھوک لاحق ہو گئی، یہاں تک کہ ہم پتے کھانے پر مجبور ہو گئے۔ اس لیے اس لشکر کا نام ’’پتوں والا لشکر‘‘ رکھا گیا۔ سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: سمندر سے ہمارے سامنے ایک سمندری مخلوق آئی۔ ہم اس وقت ساحل پر موجود تھے۔ اسے ’’عنبر‘‘ کہا جاتا تھا۔ ہم پندرہ دن تک اس کا گوشت کھاتے رہے۔ ہم نے اس کے تیل کے ساتھ روٹی کھائی۔ اس کی چربی کو جسم پر ملا یہاں تک کہ ہم موٹے تازے ہو گئے۔ پھر سیدنا ابو عبیدہ رضی اللہ عنہ نے اس کی ایک پسلی کو کھڑا کیا۔ پھر انہوں نے سب سے طویل ترین شخص اور لشکر کے سب سے اونچے اونٹ کا جائزہ لیا۔ پھر اس شخص کو حکم دیا کہ وہ اس اونٹ پر سوار ہو اور اس پسلی کے نیچے سے گزرے۔ تو اس شخص نے ایسا ہی کیا۔ وہ اس کے نیچے سے گزر گیا۔ ہم نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم کو اس بارے میں بتایا تو آپ صلی اللہ علیہ وسلم نے دریافت کیا: کیا تمہارے پاس اس کا کچھ حصہ ہے؟ ہم نے عرض کی: جی نہیں!\nتخریج: ايضا"}],[1276,"جابر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے مثل روایت سابق نقل کیا ہے اور اس میں مزید یہ ذکر بھی ہے کہ ہمارے درمیان ایک آدمی کے پاس ایک بوری میں کھجوریں تھی اور وہ مٹھی قدر ہمیں دیا کرتا تھا، پھر ایک ایک دانا دیا کرتا تھا یہاں تک کہ وہ بھی ختم ہو گئے تو خوراک ختم ہونے کا زیادہ احساس ہوا۔ (1)","",{"k":"(1) صحیح مسلم (1935)، سنن النسائی (4357)، سنن ابی داود (3840)، مسند احمد (311/3)، صحیح ابی عوانة (145/5، 146)، صحیح ابن حبان (5260)، سنن الکبری للبیہقی (251/9)۔","f":"اس حدیث میں کھجور کی اہمیت بیان کی گئی ہے، یعنی یہ زاد راہ کے طور پر اکثر استعمال ہوتی تھی، جیسا کہ حضرت ابراہیم علیہ السلام نے اپنی بیوی اور بیٹے کو دی تھیں، اور مدینہ کھجوروں کا شہر ہے۔","u2":"یہی روایت ایک اور سند کے ہمراہ بھی منقول ہے تاہم اس میں یہ الفاظ زائد ہیں۔ ’’ہمارے درمیان ایک شخص تھا جس کے پاس بوری تھی جس میں کھجوریں موجود تھیں۔ وہ اس میں سے ایک ایک مٹھی کھجوریں ہمیں دیا کرتا تھا، پھر نوبت ایک کھجور تک آ گئی۔ جب وہ بھی ختم ہو گئی، تو ہمیں اس کی غیر موجودگی کا شدت سے احساس ہوا۔‘‘\nتخریج: متفق عليه"}],[1277,"عمرو کہتے ہیں: انھوں نے جناب جابر سے سنا، انھوں نے فرمایا: ایک آدمی ہمارے درمیان موجود تھا (قیس بن سعد بن عبادہ) جس نے تین اونٹ ذبح کرائے، پھر تین ذبح کرائے، پھر تین ذبح کرائے، جب وہ نو اونٹ ذبح کرا چکا تو ابو عبیدہ بن جراح نے ان کو منع کر دیا۔ (1)","",{"k":"(1) صحیح البخاری (4361)، صحیح مسلم (1935/19)۔","u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: ہمارے درمیان ایک شخص موجود تھا، جب بھوک شدید ہو گئی تو اس نے تین اونٹ ذبح کر لیے پھر تین اونٹ ذبح کیے، پھر تین اونٹ ذبح کیے۔ پھر سیدنا ابو عبیدہ بن الجراح رضی اللہ عنہ نے اسے ایسا کرنے سے منع کر دیا۔\nتخریج: ايضا"}],[1278,"قیس بن سعد بن عبادہ نے کہا: میں اس فوج (جیش الخبط) میں موجود تھا، جب لوگوں پر فاقہ اور بھوک پڑی تھی، تو میں نے اپنے باپ کو واپس آ کر اس کی خبر دی تو اس نے کہا: تو اونٹ ذبح کراتا، میں نے ذبح کرائے مگر پھر بھوک پڑی، تو انھوں نے فرمایا: اونٹ ذبح کراتا، میں نے کہا: میں نے ذبح کرا دیے ہیں اور تیسری بار پھر لوگ فاقہ سے عاجز آگئے تو انھوں نے کہا: پھر ذبح کراتا، میں نے کہا: ذبح کرائے تھے، چوتھی بار پھر بھوک نے لوگوں کو ستایا، میرے باپ نے کہا: اونٹ ذبح کرا تو میں نے کہا: مجھے منع کر دیا گیا ہے۔ (1)","",{"k":"(1) صحیح البخاری (4361)، صحیح ابی عوانة (8059)، مصنف عبد الرزاق (8938)۔","f":"اس حدیث میں 1278 حدیث کی وضاحت آگئی ہے کہ بھوک کی وجہ سے انھوں نے اونٹ ذبح کیے تھے، جب کسی قوم پر فاقہ پڑھتا تو وہ اونٹ ذبح کر لیتے تھے۔","u2":"قیس بن سعد بیان کرتے ہیں: میں نے اپنے والد سے کہا: میں اس لشکر میں موجود تھا، جسے ’پتوں والا لشکر‘ کا نام دیا گیا لوگوں کو بھوک لاحق ہو گئی تو میرے والد نے مجھ سے کہا: تم قربان کرو میں نے جواب دیا: میں قربان کر لیتا ہوں، پھر لوگوں کو شدید بھوک کا سامنا کرنا پڑا تو میرے والد نے مجھے فرمایا: تم قربان کرو! میں نے جواب دیا: میں قربان کر دیتا ہوں، پھر لوگوں کو بھوک کا سامنا کرنا پڑا تو میرے والد نے مجھے کہا: تم قربان کرو تو میں نے کہا: میں قربان کر لیتا ہوں، پھر میرے والد نے مجھ سے کہا: تم قربان کرو تو میں نے جواب دیا: مجھے (لشکر کے امیر کی طرف سے) اس سے منع کر دیا گیا ہے۔\nتخریج: اخرجه البخاري في المغازي"}],[1279,"عمرو بن دینار بیان کرتے ہیں کہ جابر بن عبد اللہ نے اپنے کان کی طرف اشارہ کر کے فرمایا: میں نے اپنے ان دو کانوں سے سنا ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جہنم سے نکل کر کچھ لوگ جنت میں داخل ہوں گے۔ (1)","",{"k":"(1) صحیح البخاری (6558)، صحیح مسلم (191)، مسند احمد (308/3)، مسند الطیالسی (1704)، مسند ابی یعلی (1831)، صحیح ابن حبان (7483)، التوحید لابن خزیمة (668/2)، السنة لابن ابی عاصم (839)۔","f":"اس حدیث سے بعض گمراہ فرقوں کا رد ہوتا ہے، جو کہتے ہیں کہ جس نے کوئی گناہ کیا وہ ہمیشہ کے لیے جہنم میں جائے گا، اس حدیث سے اللہ تعالیٰ کی رحمت کی وسعت ثابت ہوتی ہے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ اپنے کانوں کی طرف اشارہ کرتے ہوئے یہ بات بیان کرتے ہیں: میں گواہی دے کر یہ بات کہتا ہوں کہ میں نے اپنے ان دو کانوں سے نبی اکرم صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا ہے: ’’بے شک کچھ لوگ جہنم سے نکالے جائیں گے اور جنت میں داخل کر دیے جائیں گے۔‘‘\nتخریج: متفق عليه"}],[1280,"جابر بن عبد اللہ رضی اللہ عنہ سے مروی ہے کہ معاذ بن جبل عشاء کی نماز نبی کریم صلی اللہ علیہ وسلم کے ساتھ پڑھتے تھے، پھر واپس آ کر اپنے محلہ والوں کو یہ ہی نماز عشاء پڑھاتے تھے، انھوں نے کہا: ایک دن رسول اللہ صلی اللہ علیہ وسلم نے نماز عشاء تاخیر کر کے پڑھی تو معاذ نے بھی آپ کے ساتھ نماز پڑھی، پھر واپس آ کر اپنی قوم کی امامت کی اور سورت البقرہ پڑھنا شروع کردی، ایک آدمی جماعت سے علیحدہ ہو کر تنہا نماز پڑھ کر چلا گیا، تو لوگوں نے کہا: تو منافق ہو گیا ہے، اس نے کہا: یہ بات تو نہیں ہے، مگر میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر ہو کر خبردوں گا، پھر وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس نے عرض کی: یا رسول اللہ! کل رات آپ نے نماز عشاء تاخیر سے پڑھائی اور معاذ نے آپ کے ساتھ نماز پڑھی، پھر واپس لوٹ کر ہمیں نماز پڑھائی اور سورت البقرہ شروع کردی، جب میں نے یہ حال دیکھا تو میں پیچھے ہٹا اور علیحدہ نماز پڑھ لی، ہم اونٹوں والے ہیں، ان کا چارہ اپنے ہاتھوں سے تیار کرتے اور کام کاج کرتے ہیں، پس نبی کریم صلی اللہ علیہ وسلم معاذ کی طرف متوجہ ہوئے اور فرمایا: اے معاذ! کیا تو فتنے اور آزمائش میں ڈالنے والا ہے؟ کیا تو فتنہ انگیز ہے؟ فلاں اور فلاں سورتیں پڑھا کر۔ چند سورتوں کا ذکر کیا، سفیان کہتے ہیں: ابو زبیر کی حدیث میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: سبح اسم ربک الاعلیٰ، واللیل اذا یغشیٰ، والسماء ذات البروج، والشمس وضحہا اور والسماء والطارق پڑھا کر، سفیان کہتے ہیں: میں نے عمرو بن دینار سے کہا: ابو زبیر نے کہا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: سبح اسم ربک الاعلیٰ، واللیل اذا یغشیٰ، والشمس وضحہا، والسماء والطارق، والسماء ذات البروج پڑھو، عمرو نے کہا: وہ اسی طرح سے ہے، یا اس کی مثل فرمایا۔ (1)","",{"k":"(1) صحیح البخاری (701)، صحیح مسلم (465)، سنن ابی داود (790)، سنن النسائی (836)، مسند احمد (308/3)، سنن الدارمی (1300)، صحیح ابن خزیمة (521)، صحیح ابن حبان (2400)، مسند الشافعی (103/1)، سنن الکبری للبیہقی (85/3)۔","f":"اس حدیث سے ثابت ہوا کہ امام کو لوگوں کے احوال دیکھ کر نماز پڑھانی چاہیے، اس قدر لمبی نمازیں نہ پڑھانی جائیں کہ لوگ فتنے میں مبتلا ہو جائیں۔ سیدنا معاذ بن جبل رضی اللہ عنہ کے متعلق جس صحابی نے شکایت لگائی تھی اس کی مختلف وجوہات میں سے ایک بڑی اہم وجہ الاوسط لابن المنذر (2002) میں ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے نماز عشاء لیٹ پڑھائی، جس کی وجہ سے سیدنا معاذ بن جبل رضی اللہ عنہ کافی لیٹ اپنی قوم کے پاس پہنچے، پھر جب نماز پڑھانے لگے تو سورة البقرہ کی تلاوت شروع کردی، یعنی ایک تو نبی کریم صلی اللہ علیہ وسلم نے نماز خاصی لیٹ کردی، جس کی وجہ سے سیدنا معاذ بن جبل رضی اللہ عنہ کی قوم کافی دیر تک ان کا انتظار کرتی رہی، چاہیے تو یہ تھا کہ سیدنا معاذ رضی اللہ عنہ لوگوں کو مختصری نماز پڑھا کر فارغ کر دیتے، لیکن چونکہ انھیں قرآن کریم سے بہت زیادہ محبت تھی، اس لیے انھوں نے نیک نیتی سے سورة البقرہ پڑھنی شروع کردی، لیکن قوم میں سے ایک بندے نے نماز توڑ کر الگ پڑھ لی، اور پھر صحیح شکایت کر دی۔ نیز اس حدیث سے یہ بھی ثابت ہوا کہ مقتدی کے امام کے پیچھے مفترض کی نماز کی ہو جاتی ہے۔ رعایا امام یا استاد کی شکایت حاکم وقت سے کر سکتی ہے، حاکم وقت فیصلہ کرنے میں دیر نہ کرے، بلکہ جلدی سے جلدی فیصلہ کر دے، تاکہ مزید نقصان نہ ہو۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: سیدنا معاذ بن جبل رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کی اقتداء میں نماز ادا کرتے تھے پھر وہ (اپنے محلے) واپس تشریف لے جاتے تھے اور اپنی قوم کو یہ نماز پڑھایا کرتے تھے۔ راوی بیان کرتے ہیں: ایک رات نبی اکرم صلی اللہ علیہ وسلم نے عشاء کی نماز تاخیر سے ادا کی تو سیدنا معاذ رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کی اقتداء میں عشاء کی نماز ادا کی پھر وہ واپس چلے گئے اور انہوں نے اپنی قوم کو نماز پڑھانا شروع کی تو سورۃ بقرہ کی تلاوت شروع کر دی۔ ان کے پیچھے نماز ادا کرنے والوں میں سے ایک صاحب پیچھے ہٹے۔ انہوں نے تنہا نماز ادا کی اور چلے گئے۔ لوگوں نے ان سے کہا: تم منافق ہو گئے ہو؟ تو وہ بولا: جی نہیں! میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں جا کر آپ صلی اللہ علیہ وسلم کو اس بارے میں بتاؤں گا۔ پھر وہ شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! گزشتہ رات آپ صلی اللہ علیہ وسلم نے عشاء کی نماز تاخیر سے ادا کی تھی۔ سیدنا معاذ رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کی اقتداء میں یہ نماز ادا کی۔ پھر وہ واپس آئے اور انہوں نے ہمیں نماز پڑھانا شروع کی اور سورۃ بقرہ پڑھنی شروع کر دی۔ جب میں نے یہ دیکھا تو میں پیچھے ہٹ گیا۔ پھر میں نے اکیلے نماز ادا کر لی۔ ہم اونٹ پالنے والے لوگ ہیں ہم نے اپنے ہاتھوں سے کام کاج کرنا ہوتا ہے (راوی کہتے ہیں:) تو نبی اکرم صلی اللہ علیہ وسلم سیدنا معاذ رضی اللہ عنہ کی طرف متوجہ ہوئے آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: اے معاذ! کیا تم آزمائش میں مبتلا کرنا چاہتے ہو؟ کیا تم آزمائش میں مبتلا کرنا چاہتے ہو؟ تم فلاں اور فلاں سورت کی تلاوت کیا کرو! پھر آپ صلی اللہ علیہ وسلم نے ان سورتوں کی گنتی کروائی۔ سفیان نامی راوی کہتے ہیں: ابو زبیر نامی راوی نے اس میں یہ الفاظ مزید نقل کیے ہیں: ’’نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: تم سورۃ الاعلیٰ، سورۃ اللیل، سورۃ البروج، سورۃ الشمس اور سورۃ الطارق کی تلاوت کیا کرو۔‘‘ سفیان کہتے ہیں: میں نے عمرو بن دینار سے کہا: ابو زبیر نے تو یہ بات بیان کی ہے نبی اکرم صلی اللہ علیہ وسلم نے یہ فرمایا: ’’تم سورۃ الاعلیٰ، سورۃ اللیل، سورۃ الشمس، سورۃ الطارق اور سورۃ البروج کی تلاوت کیا کرو۔‘‘ تو عمرو بن دینار نے کہا: یہ الفاظ یہی ہیں یا اس کی مانند ہیں۔\nتخریج: ايضا"}],[1281,"جابر بن عبد اللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عبد اللہ بن ابی بن سلول کے پاس اس کو قبر میں اتارنے کے بعد گئے اور حکم دیا، پس وہ نکالا گیا تو آپ نے اس کو اپنے زانوں مبارک پر تھام کر اپنا کرتا پہنایا اور اس پر اپنا لعاب مبارک بھی تھوکا، واللہ اعلم۔ (1)","",{"k":"(1) صحیح البخاری (1270)، صحیح مسلم (2773)، سنن النسائی (1902، 1903)۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں، نبی اکرم صلی اللہ علیہ وسلم عبداللہ بن ابی بن سلول (کی میت) کے پاس تشریف لائے اس وقت جب اسے قبر میں رکھا جا چکا تھا۔ نبی اکرم صلی اللہ علیہ وسلم کے حکم کے تحت اسے باہر نکالا گیا اور اس کی میت کو آپ صلی اللہ علیہ وسلم کے گھٹنوں پر رکھا گیا نبی اکرم صلی اللہ علیہ وسلم نے اپنی قمیص اسے پہنوائی اور اس پر اپنا لعاب دہن ڈالا۔ باقی اللہ بہتر جانتا ہے۔\nتخریج: ايضا"}],[1282,"موسی بن ابی عیسیٰ بیان کرتے ہیں: عبد اللہ بن ابی بن سلول کے بیٹے عبد اللہ نے عرض کی: نبی کریم صلی اللہ علیہ وسلم نے اس وقت دو قمیص پہنی ہوئی تھیں، یا رسول اللہ صلی اللہ علیہ وسلم! اپنی قمیص جو آپ صلی اللہ علیہ وسلم کے جسم اطہر سے لگی ہوئی ہے اس کو پہنا دیں۔ (1)","",{"k":"(1) صحیح البخاری (1350)، غوامض الاسماء المبہمة لابن بشکوال (657/2)۔","u2":"ابو ہارون کہتے ہیں: عبداللہ بن ابی کے صاحبزادے سیدنا عبداللہ رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے یہ گزارش کی: نبی اکرم صلی اللہ علیہ وسلم نے اس وقت دو قمیصیں پہنی ہوئی تھیں، اس نے عرض کی تھی: یا رسول اللہ (صلی اللہ علیہ وسلم)! آپ صلی اللہ علیہ وسلم وہ قمیص اسے پہنا دیجئے جو آپ صلی اللہ علیہ وسلم کے جسم کے ساتھ مس ہو رہی ہے۔\nتخریج: اخرجه ابن بشكول في غوامض الاسماء المبهمة"}],[1283,"جابر بن عبد اللہ رضی اللہ عنہ نے فرمایا: احد کے دن ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! آپ یہ بتائیں اگر میں اللہ کی راہ میں لڑوں، یہاں تک کہ قتل کر دیا جاؤں تو میں کہاں جاؤں گا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جنت میں، اس کے ہاتھ میں جو کھجوریں تھی وہ پھینک کر لڑا یہاں تک کہ شہید کر دیا گیا۔ (1)","",{"k":"(1) صحیح البخاری (4046)، صحیح مسلم (1899)، سنن النسائی (3156)، مسند احمد (308/3)، مسند ابی یعلی (1972)، صحیح ابی عوانة (34/5)، صحیح ابن حبان (4652)، سنن الکبری للبیہقی (43/9)۔","f":"اس حدیث سے معلوم ہوا کہ شہید کا بدلہ جنت ہے، اور صحابہ کرام رضوان اللہ علیہم اجمعین کو زیادہ سے زیادہ جنت کی حرص و طمع ہوتی تھی، اللہ تعالیٰ ہمیں شہادت کی موت نصیب فرمائے۔","u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں: غزوہ احد کے دن ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے عرض کی: یا رسول اللہ (صلی اللہ علیہ وسلم)! آپ صلی اللہ علیہ وسلم کی کیا رائے ہے؟ اگر میں اللہ کی راہ میں قتل کرتے ہوئے مارا جاتا ہوں تو میں کہاں جاؤں گا؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جنت میں۔ راوی کہتے ہیں: اس شخص نے اپنے ہاتھ میں موجود کھجوریں ایک طرف رکھیں اور پھر جنگ میں حصہ لیا یہاں تک کہ شہید ہو گیا۔\nتخریج: متفق عليه"}]])